      SUBROUTINE CAAB_INCLUDED(IEXOP,INCLUDED_CAAB)
*
* Is excitation operator CAAB included in the 
* list of excitations
*
#include "implicit.inc"
#include "ipoist8.inc"
#include "mxpdim.inc"
#include "cgas.inc"
*
*. Specific input
      INTEGER IEXOP(NGAS,4)
*
      INCLUDED_CAAB = 1
* Creation alpha
      CALL OCC_INCLUDED(IEXOP(1,1),INCLUDED)
      IF(INCLUDED.EQ.0) INCLUDED_CAAB = 0
* Creation beta
      CALL OCC_INCLUDED(IEXOP(1,2),INCLUDED)
      IF(INCLUDED.EQ.0) INCLUDED_CAAB = 0
* Annihilation alpha
      CALL OCC_INCLUDED(IEXOP(1,3),INCLUDED)
      IF(INCLUDED.EQ.0) INCLUDED_CAAB = 0
* Annihilation beta
      CALL OCC_INCLUDED(IEXOP(1,4),INCLUDED)
      IF(INCLUDED.EQ.0) INCLUDED_CAAB = 0
*
#if defined LUCI_DEBUG
      NTEST = 000
      IF(NTEST.GE.100) THEN
       WRITE(6,*) ' CAAB excitation operator '
       CALL WRT_SPOX_TP(IEXOP,1)
       WRITE(6,*) ' INCLUDED_CAAB = ', INCLUDED_CAAB
      END IF
#endif
*
      END
***********************************************************************

      SUBROUTINE CCEX_OCC_OCC(INOCC,IOUTOCC,NGAS,ICCEXC,ISZERO)
*
* A set of occupations INOCC is given
*
* Find occupation generated by applying coupled cluster operator ICCEXC
* in either creation or annihilation form
*
* Jeppe Olsen, Summer of 99
*
#include "implicit.inc"
#include "ipoist8.inc"
*. Input
      INTEGER INOCC(NGAS)
      INTEGER ICCEXC(NGAS)
*. Output
      INTEGER IOUTOCC(NGAS)
*
      min_occ = 0
      do jgas = 1, ngas
        IOUTOCC(JGAS) = INOCC(JGAS) - ICCEXC(JGAS)
        min_occ       = min(min_occ,IOUTOCC(JGAS))
      end do
      ISZERO = 0
      if(min_occ.lt.0) ISZERO = 1
*
#if defined LUCI_DEBUG
      NTEST = 000
      IF(NTEST.GE.100) THEN
        write(6,*) 'CCEX_OCC_OCC speaking:'
        WRITE(6,*) ' Input occupation '   
        CALL IWRTMA(INOCC,1,NGAS,1,NGAS)
        IF(IAC.EQ.1) THEN
          WRITE(6,*) ' String of annihilation operators'
        ELSE
          WRITE(6,*) ' String of creation operators'
        END IF
        CALL IWRTMA(ICCEXC,1,NGAS,1,NGAS)
        WRITE(6,*) ' Output string '
        CALL IWRTMA(IOUTOCC,1,NGAS,1,NGAS)
      END IF
#endif
*
      END
C&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&

      SUBROUTINE GET_HX_RELA(IFLAG,IHTYPE,NO_TTWO,NOBPT,NHX,
     &                       IFTONE,IFTTWO,ILTTWO,IFSFLT1,ILSFLT1,
     &                       IHX_LOC,IHX,IHINDX,
     &                       SIGN_NHX,I2DIATP,LABEL,IOP_REO,SIGN_OPREO,
     &                       IPRNT)
C***********************************************************************
C
C     General purpose: obtain number (IFLAG = 1) or number and types (IFLAG.NE.1) 
C     of excitations in relativistic Hamiltonian 
C
C     written by Jeppe Olsen and Timo Fleig - March/April 2001
C
C     last revisions:
C
C     Stefan Knecht Nov 2008 - fix one-electron operator matrix elements for 
C                              correct behavior under time-reversal
C                              symmetry. 
C
C     Stefan Knecht Dec 2009 - removed introduced "time-reversal
C                              correction". With my new and proper
C                              one-electron integral fetching we get the 
C                              correct integrals.
C============================================================================
C  
C     Hans Joergen Aa. Jensen and Stefan Knecht Mar 2008
C       NO_TTWO.gt.0 for only one-electron terms
C
C     Timo Fleig, June 2001
C       orbital and electron number limitations
C
C     JO and TF - Oct 2001
C       updated to exclude unwanted components
C       included LABEL specification of excitation type for DIRAC
C       (and other interfaces)
C============================================================================
C
C IHTYPE = 1 : Include only Delta MK = 0 terms
C IHTYPE = 2 : Include Delta Mk = 0 for two-electron part 
C              and complete one-electron part
C IHTYPE = 3 : Include all terms for relativisitic Hamiltonian
C              in a basis of non-relativistic orbitals
C IHTYPE = 4 : Include all terms for relativisitic Hamiltonian
C              in a basis of relativistic spinors
C
C LABEL :  1 for unbarred (alpha)
C         -1 for barred   (beta)
C         and refers to integral (not operator!) indexing !!
C
C IOP_REO : Reordering array for output density elements.
C           Relate definition of operator in this routine with
C           general output CA AA CB AB (or corresponding scheme
C           in DMK .ne. 0 cases). Not used in 1-el. case, but
C           due to NHX type counting need to be defined.
C
C SIGN_OPREO : Sign for this operator reordering
C          1.0 or -1.0 : Non-redundant density and sign
C          0.0         : Redundant density type
C
C
C An excitation is stored as : 
C (alpha creation, beta creation, alpha annihilation, beta annihilation)
C
C***********************************************************************
C
       use interface_to_mpi
#include "implicit.inc"
#include "ipoist8.inc"
#if defined (VAR_MPI2)
#include "infpar.h"
      INTEGER   ISTAT(df_MPI_STATUS_SIZE)
#endif
#include "parluci.h"
#include "mxpdim.inc"
#include "cgas.inc"
C     INPUT
C     -----
      DIMENSION NOBPT(NGAS)
C     OUTPUT
C     ------
      INTEGER IHX(NGAS,4,*),IHINDX(4,*),LABEL(4,*),IOP_REO(4,*)
      DIMENSION SIGN_NHX(*), SIGN_OPREO(*)
C     local scratch
      INTEGER IHX_LOC(4*NGAS)
C
C
      NTESTL = 000
      NTEST = max(NTESTL,IPRNT)
C
      ZERO = 0.D0
      ONE = 1.0D0
      DMONE = -1.0D0
C
C     WRITE(LUWRT,*) 'GET_HX_RELA: IHTYPE is',IHTYPE
C
C
      NHX = 0
C
C Determine maximum number of electrons per GAS first:
C FIXME  : Hardwired only one type of GASSPC calculation for the
C          moment. This would require other changes as well.
      MXNELGS(1) = IGSOCCX(1,2,1)
      do IGAS=2,NGAS,1
        MXNELGS(IGAS) = IGSOCCX(IGAS,2,1) - IGSOCCX(IGAS-1,1,1)
        MXNELGS(IGAS) = min(MXNELGS(IGAS),2*NOBPT(IGAS))
      end do
C
C  Delta MK = 0 terms
C
C Operator: a+i alpha a j alpha
C           where i belongs to IGAS and j belongs to JGAS
      DO IGAS = 1, NGAS
        DO JGAS = 1, NGAS
          if (NOBPT(IGAS).ge.1.and.NOBPT(JGAS).ge.1) then
            if (MXNELGS(IGAS).ge.1.and.MXNELGS(JGAS).ge.1) then
              CALL IZERO(IHX_LOC,4*NGAS)
              IHX_LOC(IGAS+(1-1)*NGAS) = 1
              IHX_LOC(JGAS+(3-1)*NGAS) = 1
*. Is this excitation type included ?
              CALL CAAB_INCLUDED(IHX_LOC,INCLUDED)
              IF (INCLUDED.EQ.0) THEN 
                WRITE(LUWRT,*) ' Hamiltonian type excluded '
                CALL WRT_SPOX_TP(IHX_LOC,1)
              ELSE
                NHX = NHX + 1
                if (IFLAG.ne.1) then
                  CALL ICOPVE(IHX_LOC,IHX(1,1,NHX),4*NGAS)
                  IHINDX(1,NHX) = 1
                  IHINDX(2,NHX) = 2
                  IHINDX(3,NHX) = 0
                  IHINDX(4,NHX) = 0
                  SIGN_NHX(NHX) = ONE
                  LABEL(IHINDX(1,NHX),NHX) = 1
                  LABEL(IHINDX(2,NHX),NHX) = 1
                  LABEL(3,NHX) = 0
                  LABEL(4,NHX) = 0
                  IOP_REO(1,NHX) = 1
                  IOP_REO(2,NHX) = 2
                  IOP_REO(3,NHX) = 0
                  IOP_REO(4,NHX) = 0
                  SIGN_OPREO(NHX) = ONE
C                 WRITE(LUWRT,*) ' alpha alpha type ',NHX
                end if
              END IF
            end if
          end if
        END DO
      END DO
*
* operator: a+i beta a j beta
*           where i belongs to IGAS and j belongs to JGAS
      DO IGAS = 1, NGAS
        DO JGAS = 1, NGAS
          if (NOBPT(IGAS).ge.1.and.NOBPT(JGAS).ge.1) then
            if (MXNELGS(IGAS).ge.1.and.MXNELGS(JGAS).ge.1) then
              CALL IZERO(IHX_LOC,4*NGAS)
              IHX_LOC(IGAS+(2-1)*NGAS) = 1
              IHX_LOC(JGAS+(4-1)*NGAS) = 1
              CALL CAAB_INCLUDED(IHX_LOC,INCLUDED)
              IF (INCLUDED.EQ.0) THEN 
                WRITE(LUWRT,*) ' Hamiltonian type excluded '
                CALL WRT_SPOX_TP(IHX_LOC,1)
              ELSE
                NHX = NHX + 1
                if (IFLAG.ne.1) then
                  CALL ICOPVE(IHX_LOC,IHX(1,1,NHX),4*NGAS)
                  IHINDX(1,NHX) = 1
                  IHINDX(2,NHX) = 2
                  IHINDX(3,NHX) = 0
                  IHINDX(4,NHX) = 0
                  SIGN_NHX(NHX) = ONE
C                 WRITE(LUWRT,*) ' beta beta: NHX, SIGN_NHX = ',
C    &                             NHX,SIGN_NHX(NHX)
                  LABEL(IHINDX(1,NHX),NHX) = -1
                  LABEL(IHINDX(2,NHX),NHX) = -1
                  LABEL(3,NHX) = 0
                  LABEL(4,NHX) = 0
                  IOP_REO(1,NHX) = 1
                  IOP_REO(2,NHX) = 2
                  IOP_REO(3,NHX) = 0
                  IOP_REO(4,NHX) = 0
                  SIGN_OPREO(NHX) = ONE
C                 WRITE(LUWRT,*) ' beta beta type ',NHX
                end if
              END IF
            end if
          end if
        END DO
      END DO
*
* For general purposes: First type with 
*                       1-electron and 2-electron integrals:
      IFTONE = 1
C     if only one-elecron operator (NO_TTWO > 0): spin-flip 
C     integral types (one-electron integrals) are included as 
C     2e-integrals depending on the operator symmetry...
C     even for pure one-electron operators... - SK: 18 Sep 08
      IFTTWO = NHX + 1
C
      IF (NO_TTWO .gt. 0) GOTO 200
*
* operator:
*. a+i alpha  a+j alpha  a k alpha  a l alpha, ordered so i.ge.j, k.ge.l
      DO IGAS = 1, NGAS
        DO JGAS = 1, IGAS 
          DO KGAS = 1, NGAS
            DO LGAS = 1, KGAS
              if (((IGAS.eq.JGAS.and.MXNELGS(IGAS).ge.2.and.
     &              NOBPT(IGAS).ge.2).and.
     &             (KGAS.eq.LGAS.and.MXNELGS(KGAS).ge.2.and.
     &              NOBPT(KGAS).ge.2)).or.
     &            ((IGAS.eq.JGAS.and.MXNELGS(IGAS).ge.2.and.
     &              NOBPT(IGAS).ge.2).and.
     &             (KGAS.ne.LGAS.and.MXNELGS(KGAS).ge.1.and.
     &              NOBPT(KGAS).ge.1.and.NOBPT(LGAS).ge.1.and.
     &                               MXNELGS(LGAS).ge.1)).or.
     &            ((IGAS.ne.JGAS.and.MXNELGS(IGAS).ge.1.and.
     &              NOBPT(IGAS).ge.1.and.NOBPT(JGAS).ge.1.and.
     &                               MXNELGS(JGAS).ge.1).and.
     &             (KGAS.eq.LGAS.and.MXNELGS(KGAS).ge.2.and.
     &              NOBPT(KGAS).ge.2)).or.
     &            ((IGAS.ne.JGAS.and.MXNELGS(IGAS).ge.1.and.
     &              NOBPT(IGAS).ge.1.and.NOBPT(JGAS).ge.1.and.
     &                               MXNELGS(JGAS).ge.1).and.
     &             (KGAS.ne.LGAS.and.MXNELGS(KGAS).ge.1.and.
     &              NOBPT(KGAS).ge.1.and.NOBPT(LGAS).ge.1.and.
     &                               MXNELGS(LGAS).ge.1))) then
                CALL IZERO(IHX_LOC,4*NGAS)
                IHX_LOC(IGAS+(1-1)*NGAS) = 1
                IHX_LOC(JGAS+(1-1)*NGAS) = IHX_LOC(JGAS+(1-1)*NGAS) + 1
                IHX_LOC(KGAS+(3-1)*NGAS) = 1
                IHX_LOC(LGAS+(3-1)*NGAS) = IHX_LOC(LGAS+(3-1)*NGAS) + 1
C               IHX(IGAS,1,NHX) = 1
C               IHX(JGAS,1,NHX) = IHX(JGAS,1,NHX)+1
* means IGAS=JGAS, so the number of creators of this type is 2!
C               IHX(KGAS,3,NHX) = 1
C               IHX(LGAS,3,NHX) = IHX(LGAS,3,NHX)+1
                CALL CAAB_INCLUDED(IHX_LOC,INCLUDED)
                IF (INCLUDED.EQ.0) THEN 
                  WRITE(LUWRT,*) ' Hamiltonian type excluded '
                  CALL WRT_SPOX_TP(IHX_LOC,1)
                ELSE
                  NHX = NHX + 1
                  if (IFLAG.ne.1) then
                    CALL ICOPVE(IHX_LOC,IHX(1,1,NHX),4*NGAS)
* This excitation corresponds to the integral
*  (+a  a | +a  a)
* so reorder accordingly:
                    IHINDX(1,NHX) = 1
                    IHINDX(2,NHX) = 3
                    IHINDX(3,NHX) = 4
                    IHINDX(4,NHX) = 2
                    SIGN_NHX(NHX) = ONE
                    LABEL(IHINDX(1,NHX),NHX) = 1
                    LABEL(IHINDX(2,NHX),NHX) = 1
                    LABEL(IHINDX(3,NHX),NHX) = 1
                    LABEL(IHINDX(4,NHX),NHX) = 1
                    IOP_REO(1,NHX) = 1
                    IOP_REO(2,NHX) = 4
                    IOP_REO(3,NHX) = 3
                    IOP_REO(4,NHX) = 2
                    SIGN_OPREO(NHX) = -ONE
                  end if
                END IF
              END IF
            END DO
          END DO
        END DO
      END DO
*
* operator:
*. a+i beta a+j beta a k beta a l beta, ordered so i.ge.j, k.ge.l
      DO IGAS = 1, NGAS
        DO JGAS = 1, IGAS 
          DO KGAS = 1, NGAS
            DO LGAS = 1, KGAS
              if (((IGAS.eq.JGAS.and.MXNELGS(IGAS).ge.2.and.
     &              NOBPT(IGAS).ge.2).and.
     &             (KGAS.eq.LGAS.and.MXNELGS(KGAS).ge.2.and.
     &              NOBPT(KGAS).ge.2)).or.
     &            ((IGAS.eq.JGAS.and.MXNELGS(IGAS).ge.2.and.
     &              NOBPT(IGAS).ge.2).and.
     &             (KGAS.ne.LGAS.and.MXNELGS(KGAS).ge.1.and.
     &              NOBPT(KGAS).ge.1.and.NOBPT(LGAS).ge.1.and.
     &                               MXNELGS(LGAS).ge.1)).or.
     &            ((IGAS.ne.JGAS.and.MXNELGS(IGAS).ge.1.and.
     &              NOBPT(IGAS).ge.1.and.NOBPT(JGAS).ge.1.and.
     &                               MXNELGS(JGAS).ge.1).and.
     &             (KGAS.eq.LGAS.and.MXNELGS(KGAS).ge.2.and.
     &              NOBPT(KGAS).ge.2)).or.
     &            ((IGAS.ne.JGAS.and.MXNELGS(IGAS).ge.1.and.
     &              NOBPT(IGAS).ge.1.and.NOBPT(JGAS).ge.1.and.
     &                               MXNELGS(JGAS).ge.1).and.
     &             (KGAS.ne.LGAS.and.MXNELGS(KGAS).ge.1.and.
     &              NOBPT(KGAS).ge.1.and.NOBPT(LGAS).ge.1.and.
     &                               MXNELGS(LGAS).ge.1))) then
                CALL IZERO(IHX_LOC,4*NGAS)
                IHX_LOC(IGAS+(2-1)*NGAS) = 1
                IHX_LOC(JGAS+(2-1)*NGAS) = IHX_LOC(JGAS+(2-1)*NGAS) + 1
                IHX_LOC(KGAS+(4-1)*NGAS) = 1
                IHX_LOC(LGAS+(4-1)*NGAS) = IHX_LOC(LGAS+(4-1)*NGAS) + 1
                CALL CAAB_INCLUDED(IHX_LOC,INCLUDED)
                IF (INCLUDED.EQ.0) THEN 
                  WRITE(LUWRT,*) ' Hamiltonian type excluded '
                  CALL WRT_SPOX_TP(IHX_LOC,1)
                ELSE
                  NHX = NHX + 1
                  if (IFLAG.ne.1) then
                    CALL ICOPVE(IHX_LOC,IHX(1,1,NHX),4*NGAS)
* This excitation corresponds to the integral
*  (+b  b | +b  b)
* so reorder accordingly:
                    IHINDX(1,NHX) = 1
                    IHINDX(2,NHX) = 3
                    IHINDX(3,NHX) = 4
                    IHINDX(4,NHX) = 2
                    SIGN_NHX(NHX) = ONE
                    LABEL(IHINDX(1,NHX),NHX) = -1
                    LABEL(IHINDX(2,NHX),NHX) = -1
                    LABEL(IHINDX(3,NHX),NHX) = -1
                    LABEL(IHINDX(4,NHX),NHX) = -1
                    IOP_REO(1,NHX) = 1
                    IOP_REO(2,NHX) = 4
                    IOP_REO(3,NHX) = 3
                    IOP_REO(4,NHX) = 2
                    SIGN_OPREO(NHX) = -ONE
                  end if
                END IF
              END IF
            END DO
          END DO
        END DO
      END DO
*
* First type of integrals for 2-electron diagonal
  200 I2DIATP = NHX + 1
      IF (NO_TTWO .GT. 0) GO TO 300
C     ... skip next set of two-electron terms
*
* operator:
*. a+i alpha  a+j beta  a k beta  a l alpha
      DO IGAS = 1, NGAS
        DO JGAS = 1, NGAS
          DO KGAS = 1, NGAS
            DO LGAS = 1, NGAS 
              if (MXNELGS(IGAS).ge.1.and.MXNELGS(JGAS).ge.1.and.
     &            MXNELGS(KGAS).ge.1.and.MXNELGS(LGAS).ge.1.and.
     &            NOBPT(IGAS).ge.1.and.NOBPT(JGAS).ge.1.and.
     &            NOBPT(KGAS).ge.1.and.NOBPT(LGAS).ge.1) then
                CALL IZERO(IHX_LOC,4*NGAS)
                IHX_LOC(IGAS+(1-1)*NGAS) = 1
                IHX_LOC(JGAS+(2-1)*NGAS) = 1
                IHX_LOC(KGAS+(4-1)*NGAS) = 1
                IHX_LOC(LGAS+(3-1)*NGAS) = 1
                CALL CAAB_INCLUDED(IHX_LOC,INCLUDED)
                IF (INCLUDED.EQ.0) THEN 
                  WRITE(LUWRT,*) ' Hamiltonian type excluded '
                  CALL WRT_SPOX_TP(IHX_LOC,1)
                ELSE
                  NHX = NHX + 1
                  if (IFLAG.ne.1) then
                    CALL ICOPVE(IHX_LOC,IHX(1,1,NHX),4*NGAS)
* This excitation corresponds to the integral
*  (+a  a | +b  b)
* so reorder accordingly:
                    IHINDX(1,NHX) = 1
                    IHINDX(2,NHX) = 3
                    IHINDX(3,NHX) = 4
                    IHINDX(4,NHX) = 2
                    SIGN_NHX(NHX) = -1.D0 * ONE
                    LABEL(IHINDX(1,NHX),NHX) = 1
                    LABEL(IHINDX(2,NHX),NHX) = -1
                    LABEL(IHINDX(3,NHX),NHX) = -1
                    LABEL(IHINDX(4,NHX),NHX) = 1
                    IOP_REO(1,NHX) = 1
                    IOP_REO(2,NHX) = 4
                    IOP_REO(3,NHX) = 2
                    IOP_REO(4,NHX) = 3
                    SIGN_OPREO(NHX) = -1.D0 * ONE
                  end if
                END IF
              END IF
            END DO
          END DO
        END DO
      END DO
*
      if (IHTYPE.ge.4) then
*
* operator:
*. a+i alpha  a+j beta  a k alpha  a l beta
*   Generates type (ub|bu) of integrals.
*
        do IGAS = 1,NGAS,1
          do JGAS = 1,NGAS,1
            do KGAS = 1,NGAS,1
              do LGAS = 1,NGAS,1
                if (MXNELGS(IGAS).ge.1.and.MXNELGS(JGAS).ge.1.and.
     &              MXNELGS(KGAS).ge.1.and.MXNELGS(LGAS).ge.1.and.
     &              NOBPT(IGAS).ge.1.and.NOBPT(JGAS).ge.1.and.
     &              NOBPT(KGAS).ge.1.and.NOBPT(LGAS).ge.1) then
                  CALL IZERO(IHX_LOC,4*NGAS)
                  IHX_LOC(IGAS+(1-1)*NGAS) = 1
                  IHX_LOC(JGAS+(2-1)*NGAS) = 1
                  IHX_LOC(KGAS+(3-1)*NGAS) = 1
                  IHX_LOC(LGAS+(4-1)*NGAS) = 1
                  call caab_included(IHX_LOC,INCLUDED)
                  if (INCLUDED.eq.0) then
                    write(LUWRT,*) 'Hamiltonian type excluded '
                    call wrt_spox_tp(IHX_LOC,1)
                  else
                    NHX = NHX + 1
                    if (IFLAG.ne.1) then
                      call icopve(IHX_LOC,IHX(1,1,NHX),4*NGAS)
* This excitation corresponds to the integral
*  (+a  b | +b  a)
* so reorder accordingly:
                      IHINDX(1,NHX) = 1
                      IHINDX(2,NHX) = 3
                      IHINDX(3,NHX) = 4
                      IHINDX(4,NHX) = 2
                      SIGN_NHX(NHX) = ONE
                      LABEL(IHINDX(1,NHX),NHX) = 1
                      LABEL(IHINDX(2,NHX),NHX) = -1
                      LABEL(IHINDX(3,NHX),NHX) = 1
                      LABEL(IHINDX(4,NHX),NHX) = -1
                      IOP_REO(1,NHX) = 1
                      IOP_REO(2,NHX) = 4
                      IOP_REO(3,NHX) = 2
                      IOP_REO(4,NHX) = 3
                      SIGN_OPREO(NHX) = ZERO
                    end if
                  end if
                end if
              end do
            end do
          end do
        end do
*
      end if
*
* Last type of non-spin-flip integrals
  300 ILTTWO = NHX
      IFSFLT1= ILTTWO + 1
*
* one-electron spin orbit
*
      IF (IHTYPE.GT.2) THEN
*
* operator: a+i alpha  j beta
*           where i belongs to IGAS and j belongs to JGAS
        DO IGAS = 1, NGAS
          DO JGAS = 1, NGAS
            if (MXNELGS(IGAS).ge.1.and.MXNELGS(JGAS).ge.1.and.
     &          NOBPT(IGAS).ge.1.and.NOBPT(JGAS).ge.1) then
              CALL IZERO(IHX_LOC,4*NGAS)
              IHX_LOC(IGAS+(1-1)*NGAS) = 1
              IHX_LOC(JGAS+(4-1)*NGAS) = 1
              CALL CAAB_INCLUDED(IHX_LOC,INCLUDED)
              IF (INCLUDED.EQ.0) THEN 
                WRITE(LUWRT,*) ' Hamiltonian type excluded '
                CALL WRT_SPOX_TP(IHX_LOC,1)
              ELSE
                NHX = NHX + 1
                if (IFLAG.ne.1) then
                  CALL ICOPVE(IHX_LOC,IHX(1,1,NHX),4*NGAS)
                  IHINDX(1,NHX) = 1
                  IHINDX(2,NHX) = 2
                  IHINDX(3,NHX) = 0
                  IHINDX(4,NHX) = 0
                  SIGN_NHX(NHX) = ONE
                  LABEL(1,NHX) = 1
                  LABEL(2,NHX) = -1
                  LABEL(3,NHX) = 0
                  LABEL(4,NHX) = 0
                  IOP_REO(1,NHX) = 1
                  IOP_REO(2,NHX) = 2
                  IOP_REO(3,NHX) = 0
                  IOP_REO(4,NHX) = 0
                  SIGN_OPREO(NHX) = ONE
C                 WRITE(LUWRT,*) ' alpha beta spin flip type ',NHX
                end if
              END IF
            END IF
          END DO
        END DO
*
* operator: a+i beta a j alpha 
*           where i belongs to IGAS and j belongs to JGAS
        DO IGAS = 1, NGAS
          DO JGAS = 1, NGAS
            if (MXNELGS(IGAS).ge.1.and.MXNELGS(JGAS).ge.1.and.
     &          NOBPT(IGAS).ge.1.and.NOBPT(JGAS).ge.1) then
              CALL IZERO(IHX_LOC,4*NGAS)
              IHX_LOC(IGAS+(2-1)*NGAS) = 1
              IHX_LOC(JGAS+(3-1)*NGAS) = 1
              CALL CAAB_INCLUDED(IHX_LOC,INCLUDED)
              IF (INCLUDED.EQ.0) THEN 
                WRITE(LUWRT,*) ' Hamiltonian type excluded '
                CALL WRT_SPOX_TP(IHX_LOC,1)
              ELSE
                NHX = NHX + 1
                if (IFLAG.ne.1) then
                  CALL ICOPVE(IHX_LOC,IHX(1,1,NHX),4*NGAS)
                  SIGN_NHX(NHX) = ONE
                  IHINDX(1,NHX) = 1
                  IHINDX(2,NHX) = 2
                  IHINDX(3,NHX) = 0
                  IHINDX(4,NHX) = 0
                  LABEL(1,NHX) = -1
                  LABEL(2,NHX) = 1
                  LABEL(3,NHX) = 0
                  LABEL(4,NHX) = 0
                  IOP_REO(1,NHX) = 1
                  IOP_REO(2,NHX) = 2
                  IOP_REO(3,NHX) = 0
                  IOP_REO(4,NHX) = 0
                  SIGN_OPREO(NHX) = ONE
C                 WRITE(LUWRT,*) ' beta alpha spin flip type ',NHX
                end if
              END IF
            END IF
          END DO
*         quaternionic matrix groups only!
        END DO
      END IF
*     last one-electron spin-flip type integral
      ILSFLT1 = NHX
*
*     two-electron terms with Delta mk .ne. 0
*
      if (NO_TTWO .eq. 0) THEN
*         include two-electron terms when NO_TTWO .gt. 0
      if (IHTYPE.eq.3.or.IHTYPE.eq.5) THEN
*
**********************************************************
*  Spin-dependent spinor basis. E.g. DIRAC environment   *
*    (ub|uu), (bu|uu), (bu|bb), (ub|bb) integral classes *
**********************************************************
*
* operator:
*. a+i alpha a+j alpha a k alpha a l beta, i .ge. j
        DO IGAS = 1, NGAS
          DO JGAS = 1, IGAS
            DO KGAS = 1, NGAS
              DO LGAS = 1, NGAS 
                if ((IGAS.eq.JGAS.and.MXNELGS(IGAS).ge.2.and.
     &               MXNELGS(KGAS).ge.1.and.MXNELGS(LGAS).ge.1.and.
     &               NOBPT(IGAS).ge.2.and.NOBPT(KGAS).ge.1.and.
     &               NOBPT(LGAS).ge.1).or.
     &               (IGAS.ne.JGAS.and.
     &                MXNELGS(IGAS).ge.1.and.MXNELGS(JGAS).ge.1.and.
     &                MXNELGS(KGAS).ge.1.and.MXNELGS(LGAS).ge.1.and.
     &                NOBPT(IGAS).ge.1.and.NOBPT(JGAS).ge.1.and.
     &                NOBPT(KGAS).ge.1.and.NOBPT(LGAS).ge.1)) then
                  CALL IZERO(IHX_LOC,4*NGAS)
                  IHX_LOC(IGAS+(1-1)*NGAS) = 1
                  IHX_LOC(JGAS+(1-1)*NGAS) = IHX_LOC(JGAS+(1-1)*NGAS)+1
                  IHX_LOC(KGAS+(3-1)*NGAS) = 1
                  IHX_LOC(LGAS+(4-1)*NGAS) = 1
                  CALL CAAB_INCLUDED(IHX_LOC,INCLUDED)
                  IF (INCLUDED.EQ.0) THEN 
                    WRITE(LUWRT,*) ' Hamiltonian type excluded '
                    CALL WRT_SPOX_TP(IHX_LOC,1)
                  ELSE
                    NHX = NHX + 1
                    if (IFLAG.ne.1) then
                      CALL ICOPVE(IHX_LOC,IHX(1,1,NHX),4*NGAS)
* This excitation corresponds to the integral
*  (+a  a | b  a+)
* so reorder accordingly:
                      IHINDX(1,NHX) = 1
                      IHINDX(2,NHX) = 3
                      IHINDX(3,NHX) = 4
                      IHINDX(4,NHX) = 2
                      SIGN_NHX(NHX) = ONE
                      LABEL(IHINDX(1,NHX),NHX) = 1
                      LABEL(IHINDX(2,NHX),NHX) = 1
                      LABEL(IHINDX(3,NHX),NHX) = 1
                      LABEL(IHINDX(4,NHX),NHX) = -1 
                      IOP_REO(1,NHX) = 1
                      IOP_REO(2,NHX) = 3
                      IOP_REO(3,NHX) = 2
                      IOP_REO(4,NHX) = 4
                      SIGN_OPREO(NHX) = -1.D0 * ONE
                    end if
                  END IF
                END IF
              END DO
            END DO
          END DO
        END DO
*
* operator:
*. a+i beta a+j alpha a k alpha a l alpha, k .ge. l
        DO IGAS = 1, NGAS
          DO JGAS = 1, NGAS
            DO KGAS = 1, NGAS
              DO LGAS = 1, KGAS 
                if ((KGAS.eq.LGAS.and.MXNELGS(KGAS).ge.2.and.
     &               MXNELGS(IGAS).ge.1.and.MXNELGS(JGAS).ge.1.and.
     &               NOBPT(KGAS).ge.2.and.NOBPT(IGAS).ge.1.and.
     &               NOBPT(JGAS).ge.1).or.
     &               (KGAS.ne.LGAS.and.
     &                MXNELGS(IGAS).ge.1.and.MXNELGS(JGAS).ge.1.and.
     &                MXNELGS(KGAS).ge.1.and.MXNELGS(LGAS).ge.1.and.
     &                NOBPT(IGAS).ge.1.and.NOBPT(JGAS).ge.1.and.
     &                NOBPT(KGAS).ge.1.and.NOBPT(LGAS).ge.1)) then
                  CALL IZERO(IHX_LOC,4*NGAS)
                  IHX_LOC(IGAS+(1-1)*NGAS) = 1
                  IHX_LOC(JGAS+(2-1)*NGAS) = 1
                  IHX_LOC(KGAS+(3-1)*NGAS) = 1
                  IHX_LOC(LGAS+(3-1)*NGAS) = IHX_LOC(LGAS+(3-1)*NGAS)+1
                  CALL CAAB_INCLUDED(IHX_LOC,INCLUDED)
                  IF (INCLUDED.EQ.0) THEN 
                    WRITE(LUWRT,*) ' Hamiltonian type excluded '
                    CALL WRT_SPOX_TP(IHX_LOC,1)
                  ELSE
                    NHX = NHX + 1
                    if (IFLAG.ne.1) then
                      CALL ICOPVE(IHX_LOC,IHX(1,1,NHX),4*NGAS)
* This excitation corresponds to the integral
*  (+b  a | a  a+)
* so reorder accordingly:
                      IHINDX(1,NHX) = 1
                      IHINDX(2,NHX) = 3
                      IHINDX(3,NHX) = 4
                      IHINDX(4,NHX) = 2
                      SIGN_NHX(NHX) = ONE
                      LABEL(IHINDX(1,NHX),NHX) = -1
                      LABEL(IHINDX(2,NHX),NHX) = 1
                      LABEL(IHINDX(3,NHX),NHX) = 1
                      LABEL(IHINDX(4,NHX),NHX) = 1 
                      IOP_REO(1,NHX) = 3
                      IOP_REO(2,NHX) = 1
                      IOP_REO(3,NHX) = 2
                      IOP_REO(4,NHX) = 4
                      SIGN_OPREO(NHX) = ONE
                    end if
                  END IF
                END IF
              END DO
            END DO
          END DO
        END DO
*
* operator:
*. a+i beta  a+j beta  a k beta  a l alpha , i .ge. j
        DO IGAS = 1, NGAS
          DO JGAS = 1, IGAS
            DO KGAS = 1, NGAS
              DO LGAS = 1, NGAS 
                if ((IGAS.eq.JGAS.and.MXNELGS(IGAS).ge.2.and.
     &               MXNELGS(KGAS).ge.1.and.MXNELGS(LGAS).ge.1.and.
     &               NOBPT(IGAS).ge.2.and.NOBPT(KGAS).ge.1.and.
     &               NOBPT(LGAS).ge.1).or.
     &               (IGAS.ne.JGAS.and.
     &                MXNELGS(IGAS).ge.1.and.MXNELGS(JGAS).ge.1.and.
     &                MXNELGS(KGAS).ge.1.and.MXNELGS(LGAS).ge.1.and.
     &                NOBPT(IGAS).ge.1.and.NOBPT(JGAS).ge.1.and.
     &                NOBPT(KGAS).ge.1.and.NOBPT(LGAS).ge.1)) then
                  CALL IZERO(IHX_LOC,4*NGAS)
                  IHX_LOC(IGAS+(2-1)*NGAS) = 1
                  IHX_LOC(JGAS+(2-1)*NGAS) = IHX_LOC(JGAS+(2-1)*NGAS)+1
                  IHX_LOC(KGAS+(4-1)*NGAS) = 1
                  IHX_LOC(LGAS+(3-1)*NGAS) = 1
                  CALL CAAB_INCLUDED(IHX_LOC,INCLUDED)
                  IF (INCLUDED.EQ.0) THEN 
                    WRITE(LUWRT,*) ' Hamiltonian type excluded '
                    CALL WRT_SPOX_TP(IHX_LOC,1)
                  ELSE
                    NHX = NHX + 1
                    if (IFLAG.ne.1) then
                      CALL ICOPVE(IHX_LOC,IHX(1,1,NHX),4*NGAS)
* This excitation corresponds to the integral
*  (+b  a | b  b+)
* so reorder accordingly:
                      IHINDX(1,NHX) = 1
                      IHINDX(2,NHX) = 4
                      IHINDX(3,NHX) = 3
                      IHINDX(4,NHX) = 2
C  ???                SIGN_NHX(NHX) = -1 * ONE
                      SIGN_NHX(NHX) = ONE
                      LABEL(IHINDX(1,NHX),NHX) = -1
                      LABEL(IHINDX(2,NHX),NHX) = -1
                      LABEL(IHINDX(3,NHX),NHX) = -1
                      LABEL(IHINDX(4,NHX),NHX) = 1 
                      IOP_REO(1,NHX) = 1
                      IOP_REO(2,NHX) = 3
                      IOP_REO(3,NHX) = 2
                      IOP_REO(4,NHX) = 4
                      SIGN_OPREO(NHX) = ZERO
                    end if
                  END IF
                END IF
              END DO
            END DO
          END DO
        END DO
*
* operator:
*. a+i alpha  a+j beta  a k beta  a l beta , k .ge. l
        DO IGAS = 1, NGAS
          DO JGAS = 1, NGAS
            DO KGAS = 1, NGAS
              DO LGAS = 1, KGAS 
                if ((KGAS.eq.LGAS.and.MXNELGS(KGAS).ge.2.and.
     &               MXNELGS(IGAS).ge.1.and.MXNELGS(JGAS).ge.1.and.
     &               NOBPT(KGAS).ge.2.and.NOBPT(IGAS).ge.1.and.
     &               NOBPT(JGAS).ge.1).or.
     &               (KGAS.ne.LGAS.and.
     &                MXNELGS(IGAS).ge.1.and.MXNELGS(JGAS).ge.1.and.
     &                MXNELGS(KGAS).ge.1.and.MXNELGS(LGAS).ge.1.and.
     &                NOBPT(IGAS).ge.1.and.NOBPT(JGAS).ge.1.and.
     &                NOBPT(KGAS).ge.1.and.NOBPT(LGAS).ge.1)) then
                  CALL IZERO(IHX_LOC,4*NGAS)
                  IHX_LOC(IGAS+(1-1)*NGAS) = 1
                  IHX_LOC(JGAS+(2-1)*NGAS) = 1
                  IHX_LOC(KGAS+(4-1)*NGAS) = 1
                  IHX_LOC(LGAS+(4-1)*NGAS) = IHX_LOC(LGAS+(4-1)*NGAS)+1
                  CALL CAAB_INCLUDED(IHX_LOC,INCLUDED)
                  IF (INCLUDED.EQ.0) THEN 
                    WRITE(LUWRT,*) ' Hamiltonian type excluded '
                    CALL WRT_SPOX_TP(IHX_LOC,1)
                  ELSE
                    NHX = NHX + 1
                    if (IFLAG.ne.1) then
                      CALL ICOPVE(IHX_LOC,IHX(1,1,NHX),4*NGAS)
* This excitation corresponds to the integral
*  (+a  b | +b  b)
* so reorder accordingly:
                      IHINDX(1,NHX) = 1
                      IHINDX(2,NHX) = 3
                      IHINDX(3,NHX) = 4
                      IHINDX(4,NHX) = 2
                      SIGN_NHX(NHX) = ONE  !!??
                      LABEL(IHINDX(1,NHX),NHX) = 1
                      LABEL(IHINDX(2,NHX),NHX) = -1
                      LABEL(IHINDX(3,NHX),NHX) = -1
                      LABEL(IHINDX(4,NHX),NHX) = -1 
                      IOP_REO(1,NHX) = 1
                      IOP_REO(2,NHX) = 3
                      IOP_REO(3,NHX) = 2
                      IOP_REO(4,NHX) = 4
                      SIGN_OPREO(NHX) = ZERO
                    end if
                  END IF
                END IF
              END DO
            END DO
          END DO
        END DO
*
      end if
*     end if (IHTYPE.eq.3.or.IHTYPE.eq.5)
*
**********************************************************
*  Spin-dependent spinor basis. E.g. DIRAC environment   *
*      (bu|bu), (ub|ub) integral classes                 *
**********************************************************
*
      if (IHTYPE.eq.4) then
*
* operator:
*. a+i alpha  a+j alpha  a k beta  a l beta, i.ge.j, k.ge.l
        DO IGAS = 1, NGAS
          DO JGAS = 1, IGAS
            DO KGAS = 1, NGAS
              DO LGAS = 1, KGAS
                if (((IGAS.eq.JGAS.and.MXNELGS(IGAS).ge.2.and.
     &                NOBPT(IGAS).ge.2).and.
     &               (KGAS.eq.LGAS.and.MXNELGS(KGAS).ge.2.and.
     &                NOBPT(KGAS).ge.2)).or.
     &              ((IGAS.eq.JGAS.and.MXNELGS(IGAS).ge.2.and.
     &                NOBPT(IGAS).ge.2).and.
     &               (KGAS.ne.LGAS.and.MXNELGS(KGAS).ge.1.and.
     &                NOBPT(KGAS).ge.1.and.NOBPT(LGAS).ge.1.and.
     &                                 MXNELGS(LGAS).ge.1)).or.
     &              ((IGAS.ne.JGAS.and.MXNELGS(IGAS).ge.1.and.
     &                NOBPT(IGAS).ge.1.and.NOBPT(JGAS).ge.1.and.
     &                                 MXNELGS(JGAS).ge.1).and.
     &               (KGAS.eq.LGAS.and.MXNELGS(KGAS).ge.2.and.
     &                NOBPT(KGAS).ge.2)).or.
     &              ((IGAS.ne.JGAS.and.MXNELGS(IGAS).ge.1.and.
     &                NOBPT(IGAS).ge.1.and.NOBPT(JGAS).ge.1.and.
     &                                 MXNELGS(JGAS).ge.1).and.
     &               (KGAS.ne.LGAS.and.MXNELGS(KGAS).ge.1.and.
     &                NOBPT(KGAS).ge.1.and.NOBPT(LGAS).ge.1.and.
     &                                 MXNELGS(LGAS).ge.1))) then
                  CALL IZERO(IHX_LOC,4*NGAS)
                  IHX_LOC(IGAS+(1-1)*NGAS) = 1
                  IHX_LOC(JGAS+(1-1)*NGAS) = IHX_LOC(JGAS+(1-1)*NGAS)+1
                  IHX_LOC(KGAS+(4-1)*NGAS) = 1
                  IHX_LOC(LGAS+(4-1)*NGAS) = IHX_LOC(LGAS+(4-1)*NGAS)+1
                  CALL CAAB_INCLUDED(IHX_LOC,INCLUDED)
                  IF (INCLUDED.EQ.0) THEN 
                    WRITE(LUWRT,*) ' Hamiltonian type excluded '
                    CALL WRT_SPOX_TP(IHX_LOC,1)
                  ELSE
                    NHX = NHX + 1
                    if (IFLAG.ne.1) then
                      CALL ICOPVE(IHX_LOC,IHX(1,1,NHX),4*NGAS)
* This excitation corresponds to the integral
*  (+a  b | +a  b )
* so reorder accordingly:
                      IHINDX(1,NHX) = 1
                      IHINDX(2,NHX) = 3
                      IHINDX(3,NHX) = 4
                      IHINDX(4,NHX) = 2
                      SIGN_NHX(NHX) = 1 * ONE
                      LABEL(IHINDX(1,NHX),NHX) = 1
                      LABEL(IHINDX(2,NHX),NHX) = 1
                      LABEL(IHINDX(3,NHX),NHX) = -1
                      LABEL(IHINDX(4,NHX),NHX) = -1 
                      IOP_REO(1,NHX) = 1
                      IOP_REO(2,NHX) = 4
                      IOP_REO(3,NHX) = 3
                      IOP_REO(4,NHX) = 2
                      SIGN_OPREO(NHX) = -ONE
                    end if
                  END IF
                END IF
              END DO
            END DO
          END DO
        END DO
*
* operator:
*. a+i beta  a+j beta  a k alpha  a l alpha, i.ge.j, k.ge.l
        DO IGAS = 1, NGAS
          DO JGAS = 1, IGAS
            DO KGAS = 1, NGAS
              DO LGAS = 1, KGAS
                if (((IGAS.eq.JGAS.and.MXNELGS(IGAS).ge.2.and.
     &                NOBPT(IGAS).ge.2).and.
     &               (KGAS.eq.LGAS.and.MXNELGS(KGAS).ge.2.and.
     &                NOBPT(KGAS).ge.2)).or.
     &              ((IGAS.eq.JGAS.and.MXNELGS(IGAS).ge.2.and.
     &                NOBPT(IGAS).ge.2).and.
     &               (KGAS.ne.LGAS.and.MXNELGS(KGAS).ge.1.and.
     &                NOBPT(KGAS).ge.1.and.NOBPT(LGAS).ge.1.and.
     &                                 MXNELGS(LGAS).ge.1)).or.
     &              ((IGAS.ne.JGAS.and.MXNELGS(IGAS).ge.1.and.
     &                NOBPT(IGAS).ge.1.and.NOBPT(JGAS).ge.1.and.
     &                                 MXNELGS(JGAS).ge.1).and.
     &               (KGAS.eq.LGAS.and.MXNELGS(KGAS).ge.2.and.
     &                NOBPT(KGAS).ge.2)).or.
     &              ((IGAS.ne.JGAS.and.MXNELGS(IGAS).ge.1.and.
     &                NOBPT(IGAS).ge.1.and.NOBPT(JGAS).ge.1.and.
     &                                 MXNELGS(JGAS).ge.1).and.
     &               (KGAS.ne.LGAS.and.MXNELGS(KGAS).ge.1.and.
     &                NOBPT(KGAS).ge.1.and.NOBPT(LGAS).ge.1.and.
     &                                 MXNELGS(LGAS).ge.1))) then
                  CALL IZERO(IHX_LOC,4*NGAS)
                  IHX_LOC(IGAS+(2-1)*NGAS) = 1
                  IHX_LOC(JGAS+(2-1)*NGAS) = IHX_LOC(JGAS+(2-1)*NGAS)+1
                  IHX_LOC(KGAS+(3-1)*NGAS) = 1
                  IHX_LOC(LGAS+(3-1)*NGAS) = IHX_LOC(LGAS+(3-1)*NGAS)+1
                  CALL CAAB_INCLUDED(IHX_LOC,INCLUDED)
                  IF (INCLUDED.EQ.0) THEN 
                    WRITE(LUWRT,*) ' Hamiltonian type excluded '
                    CALL WRT_SPOX_TP(IHX_LOC,1)
                  ELSE
                    NHX = NHX + 1
                    if (IFLAG.ne.1) then
                      CALL ICOPVE(IHX_LOC,IHX(1,1,NHX),4*NGAS)
* This excitation corresponds to the integral
*  (+b  a | +b  a)
* so reorder accordingly:
                      IHINDX(1,NHX) = 1
                      IHINDX(2,NHX) = 3
                      IHINDX(3,NHX) = 2
                      IHINDX(4,NHX) = 4
                      SIGN_NHX(NHX) = 1 * ONE
                      LABEL(IHINDX(1,NHX),NHX) = -1
                      LABEL(IHINDX(2,NHX),NHX) = -1
                      LABEL(IHINDX(3,NHX),NHX) = 1
                      LABEL(IHINDX(4,NHX),NHX) = 1 
                      IOP_REO(1,NHX) = 1
                      IOP_REO(2,NHX) = 4
                      IOP_REO(3,NHX) = 3
                      IOP_REO(4,NHX) = 2
                      SIGN_OPREO(NHX) = -ONE
                    end if
                  END IF
                END IF
              END DO
            END DO
          END DO
        END DO
      end if ! end if (IHTYPE .eq. 4)
*
      end if ! end if (NO_TTWO .gt. 0)
*
#if defined LUCI_DEBUG
      if (IFLAG.ne.1.and.NTEST.ge.50) then
C     if(IFLAG.ne.1)then
        WRITE(LUWRT,'(/A/)') '  *** Information from  GET_HX_RELA ***'
        WRITE(LUWRT,'(/A,I10)') '  Number of excitation types ', NHX
        do I=1,NHX
          write(LUWRT,*) '  excitation type and sign SIGN_NHX ',
     &                     I,SIGN_NHX(I)
        end do
      end if
#endif
*
      if (IFLAG.ne.1) then
#if defined LUCI_DEBUG
        write(LUWRT,'(/A)') '  Max. no of electrons per GAS:'
        call iwrtma(MXNELGS,1,NGAS,1,NGAS)
        WRITE(LUWRT,*) ' The excitation types '
        CALL WRT_SPOX_TP(IHX,NHX)
C              WRT_SPOX_TP(IEX_TP,NEX_TP)
#endif
      end if
*
      END 
***********************************************************************

      SUBROUTINE GNSIDE_REL()

      END
***********************************************************************

      SUBROUTINE GNSIDE_REL_opt(ISD,IRIS,IRIC,ICA,ICB,IAA,IAB,
     &           IAOC,IBOC,JAOC,JBOC,
     &           NIA,NIB,NJA,NJB,
     &           TB,T_BUFF,T_SCR_CC,IXTP,
     &           SB,CB,ISSM,ICSM,
     &           I1,XI1S,I2,XI2S,I3,XI3S,I4,XI4S,
     &           TBSUB,CJRES,SIRES,MAXLB,
     &           ICA_STR,ICB_STR,IAA_STR,IAB_STR,
     &           KJA,XKJA,KJB,XKJB,KIA,XKIA,KIB,XKIB,
     &           KJAD,XKJAD,KJBD,XKJBD,KIAD,XKIAD,KIBD,XKIBD,
     &           SIGN_EXTERNAL,IPRS,IPRD,ISMDST,
     &           NICA,NICB,NIAA,NIAB,NKA,NKB,
     &           IB_CA,IB_CB,IB_AA,IB_AB,IB_T,
     &           NIKAINTM,NIKBINTM,NJKAINTM,NJKBINTM
#if defined (VAR_MPI2)
     &          ,IOFF_BLK_C,IOFF_BLK_S,IACT_C,IACT_S
#endif
     &           )

*
* Sigma routine and density routine for general operator 
*
* sum(Ica,Icb,Iaa,Iab) T(Ica,Icb,Iaa,Iab) Ica+ Icb+ Iaa Iab
*
* contribution from C vector with occupation JAOC,IBOC
* to Sigma vector with occupation IAOC, IBOC
*
* All symmetryblocks of C and Sigma are treated 
*
* SIGN_EXTERNAL : A sign multiplying all contributions
*                 ( And he said : Mighty Lord, Give me a sign)
*
* ======
* Output
* ======
* SB : updated sigma block
*
* =======
* Scratch
* =======
*
*
* Jeppe Olsen, August 1999    
* Timo Fleig, June 2001, modified for relativistic case
*             cont'd, 11th of July, Mallorca, around noon (I'm crazy)
*                     15th of July
*                     August 2001
*                     August 2003, ISMDST 
*
*
      use mospinor_info
      use symmetry_setup_krci
      use interface_to_mpi
      IMPLICIT REAL*8(A-H,O-Z)
#include "ipoist8.inc"
#if defined (VAR_MPI2)
#include "infpar.h"
#endif
*. General input
#include "mxpdim.inc"
#include "gasstr.inc"
#include "cgas.inc"
#include "ctcc.inc"
#include "parluci.h"
#include "krmc_shmem.h"
*     
*.Input
      DIMENSION CB(*)
      INTEGER NIA(*),NIB(*),NJA(*),NJB(*)
      INTEGER IAOC(*),IBOC(*),JAOC(*),JBOC(*)
      INTEGER ICA(*),ICB(*),IAA(*),IAB(*)
#if defined (VAR_MPI2)
      INTEGER IACT_C(*), IACT_S(*)
#endif
*.Input or Output
      DIMENSION SB(*)
      dimension TB(*), T_BUFF(*)
*.Local Scratch
      INTEGER KAOC(MXPNGAS), KBOC(MXPNGAS)
      integer KAGP(MXPNGAS), KBGP(MXPNGAS)
      integer JAGP(MXPNGAS), JBGP(MXPNGAS)
      INTEGER ICAGP(MXPNGAS),ICBGP(MXPNGAS)
      INTEGER IAAGP(MXPNGAS),IABGP(MXPNGAS)

*. 
      INTEGER ICA_EXP(MXNOP),ICB_EXP(MXNOP)
      INTEGER IAA_EXP(MXNOP),IAB_EXP(MXNOP)

      INTEGER IB_C(MXNDGIRR),IB_S(MXNDGIRR)
*. Scratch through input 
      DIMENSION I1(*),XI1S(*),I2(*),XI2S(*)
      DIMENSION I3(*),XI3S(*),I4(*),XI4S(*)
      DIMENSION TBSUB(*), T_SCR_CC(*)
      DIMENSION ISMDST(*)
      INTEGER    KJA(MAXLB), KJB(MAXLB), KIA(MAXLB), KIB(MAXLB)
      DIMENSION XKJA(*),XKJB(*),XKIA(*),XKIB(*)
      INTEGER    KJAD(MAXLB), KJBD(MAXLB), KIAD(MAXLB), KIBD(MAXLB)
      DIMENSION XKJAD(*),XKJBD(*),XKIAD(*),XKIBD(*)

      INTEGER NICA(MXNDGIRR),NICB(MXNDGIRR)
      INTEGER NIAA(MXNDGIRR),NIAB(MXNDGIRR)
      INTEGER NKA(MXNDGIRR), NKB(MXNDGIRR)

      INTEGER IB_CA(MXNDGIRR,MXNDGIRR,MXNOP) 
      INTEGER IB_CB(MXNDGIRR,MXNDGIRR,MXNOP)
      INTEGER IB_AA(MXNDGIRR,MXNDGIRR,MXNOP)
      INTEGER IB_AB(MXNDGIRR,MXNDGIRR,MXNOP)
      INTEGER IB_T(MXNDGIRR,MXNDGIRR,MXNDGIRR)
      INTEGER NIKAINTM(MXPOBS,MXNOP),NIKBINTM(MXPOBS,MXNOP)
      INTEGER NJKAINTM(MXPOBS,MXNOP),NJKBINTM(MXPOBS,MXNOP)
*. ... Must hold excitations for all intermediate strings of given sym 
*. and all orbitals of given type
      INTEGER ICA_STR(*),ICB_STR(*),IAA_STR(*),IAB_STR(*)
*     ... Must hold strings of given sym for T ops.
      DIMENSION CJRES(*),SIRES(*)
*

      COMMON/MATMLST/XNFLOP,XNCALL,XLCROW,XLCCOL,XLCROWCOL,TMULT

      COMMON/CMXCJ/MXCJ
      INTEGER*8 ITOFF
*
!     NTESTL = 5000 ! debug
      NTESTL = 0000 
!#define LUCI_DEBUG
      NTEST = MAX(NTESTL,max(IPRS,IPRD))
*
      ISKIP = 0
#if defined (VAR_MPI2)
      LEN_C = LEN_TT_BLOCK_PAR(ICSM,NJA,NJB,IACT_C,IOFF_BLK_C,0)
#else
      LEN_C = LEN_TT_BLOCK(ICSM,NJA,NJB)
#endif
!     print *,'C (input) ==> LEN_C',LEN_C
!     call wrtmat(CB,1,LEN_C,1,LEN_C)
C     check norm
      XCNORM = DDOT(LEN_C,CB,1,CB,1)
      IF(XCNORM.EQ.0.0d0) GOTO 9999
*
C
C     symmetry of operator (Hamiltonian)
C     ----------------------------------
      IOPSM = IDBGMULT(INVELM(ICSM),ISSM)
!
!     print '(a,i4)', ' symmetry of Hamiltonian ==>',IOPSM
!     print '(a,i4)', ' symmetry of c-vector    ==>',ICSM
!     print '(a,i4)', ' symmetry of s-vector    ==>',ISSM
!
C
C     total length of sigma block
#if defined (VAR_MPI2)
      LEN_S = LEN_TT_BLOCK_PAR(ISSM,NIA,NIB,IACT_S,IOFF_BLK_S,1)
#else
      LEN_S = LEN_TT_BLOCK(ISSM,NIA,NIB)
#endif
!     print *,'LEN_S is',LEN_S
      if(LEN_S.eq.0) goto 9999
      IF(ISD.EQ.2)THEN ! check S norm (only density runs)
        XSNORM = DDOT(LEN_S,SB,1,SB,1)
        IF(XSNORM.EQ.0.0D0) GOTO 9999
      END IF
#if defined (VAR_MPI2)
C
C     vector partitioning has been changed! we have to be careful
C     calculating the proper offset for each block ( sigma and c )!!!
C
C     adapted offset of c and sigma routines
      CALL IOFF_SYMBLK_MAT_PAR(NSMST,NJA,NJB,ICSM,IB_C,
     &                         IACT_C,IOFF_BLK_C,0)
      CALL IOFF_SYMBLK_MAT_PAR(NSMST,NIA,NIB,ISSM,IB_S,
     &                         IACT_S,IOFF_BLK_S,1)
C
#else
C     offset of c and sigma routines
      CALL IOFF_SYMBLK_MAT(NSMST,NJA,NJB,ICSM,IB_C)
      CALL IOFF_SYMBLK_MAT(NSMST,NIA,NIB,ISSM,IB_S)
#endif
C     types of strings in T in groupnotation
      CALL OCC_TO_GRP(ICA,ICAGP,1)
      CALL OCC_TO_GRP(ICB,ICBGP,1)
      CALL OCC_TO_GRP(IAA,IAAGP,1)
      CALL OCC_TO_GRP(IAB,IABGP,1)
#ifdef LUCI_DEBUG
      write(6,*) ' GNSID... Output from OCC_TO_GRP : '
      write(6,*) ' ICA_GRP : ',(ICAGP(I),I=1,NGAS,1)
      write(6,*) ' ICB_GRP : ',(ICBGP(I),I=1,NGAS,1)
      write(6,*) ' IAA_GRP : ',(IAAGP(I),I=1,NGAS,1)
      write(6,*) ' IAB_GRP : ',(IABGP(I),I=1,NGAS,1)
#endif
C     operators in T in expanded form
      CALL REF_OP(ICA,ICA_EXP,NCA_OP,NGAS,1,MXNOP)
      CALL REF_OP(ICB,ICB_EXP,NCB_OP,NGAS,1,MXNOP)
      CALL REF_OP(IAA,IAA_EXP,NAA_OP,NGAS,1,MXNOP)
      CALL REF_OP(IAB,IAB_EXP,NAB_OP,NGAS,1,MXNOP)
C          REF_OP(IOPGAS,IOP,NOP,NGAS,IWAY)
C     sign for bringing operators and amplitudes into new order
      NPERM =  NAA_OP* NCB_OP 
     &       + NAA_OP*(NAA_OP-1)/2
     &       + NAB_OP*(NAB_OP-1)/2
      IF(MOD(NPERM,2).EQ.1) THEN
        SIGNXXX  =  -1.0D0*SIGN_EXTERNAL
!       WRITE(LUWRT,*) ' new SIGNXXX for type IXTP =',IXTP
      ELSE
!       WRITE(LUWRT,*) ' old SIGNXXX for type IXTP =',IXTP
        SIGNXXX = SIGN_EXTERNAL
      END IF

C     type of Ka and Kb
      CALL CCEX_OCC_OCC(JAOC,KAOC,NGAS,IAA,IKA_ZERO)
      CALL CCEX_OCC_OCC(JBOC,KBOC,NGAS,IAB,IKB_ZERO)

C     check that annihilation has not acted upon empty GAS:
      IF(IKA_ZERO.EQ.0.AND.IKB_ZERO.EQ.0) THEN
C       get group of K mapped occupations
        call occ_to_grp(KAOC,KAGP,1)
        call occ_to_grp(KBOC,KBGP,1)
C       number of strings in this supergroup (new DBG routine)
!       NEL_KA = IELSUM(KAOC,NGAS)
!       NEL_KB = IELSUM(KBOC,NGAS)
        do KSM = 1, NSMST
          call nst_spgrp_dbg(NGAS,KAGP,KSM,NSMST,NKA(KSM),NKADST,1)
!         call getstr2_totsm_spgp_rel(1,KAGP,NGAS,KSM,NEL_KA,
!    &                                NKA(KSM),NKADST)
          call nst_spgrp_dbg(NGAS,KBGP,KSM,NSMST,NKB(KSM),NKBDST,2)
!         call getstr2_totsm_spgp_rel(2,KBGP,NGAS,KSM,NEL_KB,
!    &                                NKB(KSM),NKBDST)
        end do
!       NEL_CA = IELSUM(ICA,NGAS)
!       NEL_CB = IELSUM(ICB,NGAS)
!       NEL_AA = IELSUM(IAA,NGAS)
!       NEL_AB = IELSUM(IAB,NGAS)
C       number of strings in excitation ops
        do ISYM = 1, NSMST

!         call getstr2_totsm_spgp_rel(1,ICAGP,NGAS,ISYM,NEL_CA,
!    &                                NICA(ISYM),NCADST)
!         call getstr2_totsm_spgp_rel(2,ICBGP,NGAS,ISYM,NEL_CB,
!    &                                NICB(ISYM),NCBDST)
!         call getstr2_totsm_spgp_rel(1,IAAGP,NGAS,ISYM,NEL_AA,
!    &                                NIAA(ISYM),NAADST)
!         call getstr2_totsm_spgp_rel(2,IABGP,NGAS,ISYM,NEL_AB,
!    &                                NIAB(ISYM),NABDST)
          call nst_spgrp_dbg(NGAS,ICAGP,ISYM,NSMST,NICA(ISYM),NCADST,1)
          call nst_spgrp_dbg(NGAS,ICBGP,ISYM,NSMST,NICB(ISYM),NCBDST,2)
          call nst_spgrp_dbg(NGAS,IAAGP,ISYM,NSMST,NIAA(ISYM),NAADST,1)
          call nst_spgrp_dbg(NGAS,IABGP,ISYM,NSMST,NIAB(ISYM),NABDST,2)
        end do
C       offset for symmetryblocks of T
        CALL Z_TCC_OFF_opt(IB_T,NICA,NICB,NIAA,NIAB,IOPSM)
C            Z_TCC_OFF(IBT,NCA,NCB,NAA,NAB,ITSYM)
C       creation path from C/S strings to K strings
C       mappings from !I> to !K> are annihilations mappings 

C       CA : KA => IA mappings in 1
C            MAP_EXSTR(IOP,IAC,NOP,IREFOC,IX,SX,NK,IB,ISMDST,IAB)
        IAB_MAP = 1
        CALL MAP_EXSTR(ICA_EXP,NCA_OP,IAOC,I1,XI1S,
     &                 NIKAINTM,IB_CA,ISMDST,IAB_MAP)
C       CB : KB => IB     
        IAB_MAP = 2
        CALL MAP_EXSTR(ICB_EXP,NCB_OP,IBOC,I2,XI2S,
     &                 NIKBINTM,IB_CB,ISMDST,IAB_MAP)
C       AA : KA => JA
        IAB_MAP = 1
        CALL MAP_EXSTR(IAA_EXP,NAA_OP,JAOC,I3,XI3S,
     &                 NJKAINTM,IB_AA,ISMDST,IAB_MAP)
C       AB : KB => JB
        IAB_MAP = 2
        CALL MAP_EXSTR(IAB_EXP,NAB_OP,JBOC,I4,XI4S,
     &                 NJKBINTM,IB_AB,ISMDST,IAB_MAP)
C       loop over symmetry-blocks of C and Sigma
#if defined (VAR_MPI2)
C       initialize offsets for sigma-block loop
        I_BLK_S_SCR = 0
        I_BLK_S_SCR = IOFF_BLK_S
#endif
!
!      sigma-vector loop
       DO IASM = 1, NSMST
C        parallel calculation: - sigma-blocks distributed
C                              - check of 'active' c-blocks enabled
#if defined (VAR_MPI2)
         IF( IACT_S( I_BLK_S_SCR ) .ne. MYPROC ) GOTO 3003
#endif
         IBSM = IDBGMULT(ISSM,INVELM(IASM))
!        print *,'IASM, IBSM ==> ',IASM,IBSM,NIA(IASM)*NIB(IBSM)
         if(NIA(IASM)*NIB(IBSM).eq.0) goto 3003
#if defined (VAR_MPI2)
C
C        reset offset for c-block loop
         I_BLK_C_SCR = 0
         I_BLK_C_SCR = IOFF_BLK_C
#endif
!        c-vector loop
         DO JASM = 1, NSMST
#if defined (VAR_MPI2)
           IF( IACT_C( I_BLK_C_SCR ) .eq. 0 ) GOTO 2002
#endif
           JBSM = IDBGMULT(ICSM,INVELM(JASM))
!          print *,'JASM, JBSM ==> ',JASM,JBSM,NJA(JASM)*NJB(JBSM)
           if(NJA(JASM)*NJB(JBSM).eq.0) goto 2002

           DO 100 KASM = 1, NSMST
C            IAA_SM is symmetry of ANNIHILATOR string
             IAA_SM  = IDBGMULT(KASM,INVELM(JASM))
             ICA_SM  = IDBGMULT(IASM,INVELM(KASM))
C            to obtain the number of annnihilator strings of a given sym
C            we find the number of creator strings of conjugated symmetry
             LIAA_SM = NIAA(INVELM(IAA_SM))
             LICA_SM = NICA(ICA_SM)
             LKA_SM  = NKA(KASM)
             if(LIAA_SM*LICA_SM*LKA_SM.le.0) goto 100
!             print *, ' alpha nonzero'
C
             DO KBSM = 1, NSMST
C
              IAB_SM = IDBGMULT(KBSM,INVELM(JBSM))
              ICB_SM = IDBGMULT(IBSM,INVELM(KBSM))
C
              LIAB_SM = NIAB(INVELM(IAB_SM))
              LICB_SM = NICB(ICB_SM)
              LKB_SM  = NKB(KBSM)
C
              if(LIAB_SM*LICB_SM*LKB_SM.gt.0)then

                ICBOFF = IB_C(JASM)
                ISBOFF = IB_S(IASM)
!               print *, ' beta nonzero'
C
C               the operator strings of ICA, ICB, IAA, IAB 
                IUB = 1
                CALL GETSTR2_TOTSM_SPGP_REL(IUB,ICAGP,NGAS,ICA_SM,
     &                                      NCA_OP,LICA_SM2,ICA_STR)
                IUB = 2
                CALL GETSTR2_TOTSM_SPGP_REL(IUB,ICBGP,NGAS,ICB_SM,
     &                                      NCB_OP,LICB_SM2,ICB_STR)
                IUB = 1
*               we are generating strings of creation operators so 
                IAA_SM_ADJ = INVELM(IAA_SM)
                CALL GETSTR2_TOTSM_SPGP_REL(IUB,IAAGP,NGAS,IAA_SM_ADJ,
     &                                      NAA_OP,LIAA_SM2,IAA_STR)
                IUB = 2
                IAB_SM_ADJ = INVELM(IAB_SM)
                CALL GETSTR2_TOTSM_SPGP_REL(IUB,IABGP,NGAS,IAB_SM_ADJ,
     &                                      NAB_OP,LIAB_SM2,IAB_STR)
C               batching                   
                LEN_KA_BAT = MAXLB
                LEN_KB_BAT = MAXLB
C
                IF(LKA_SM.LT.MAXLB) THEN
                  LEN_KA_BAT = LKA_SM
                  LEN_KB_BAT = MIN(LKB_SM,MAXLB*MAXLB/LKA_SM)
                END IF
C
                IF(LKB_SM.LT.MAXLB) THEN
                  LEN_KB_BAT = LKB_SM
                  LEN_KA_BAT = MIN(LKA_SM,MAXLB*MAXLB/LKB_SM)
                END IF
C
                NKA_BT = LKA_SM/LEN_KA_BAT
                IF(NKA_BT*LEN_KA_BAT. LT. LKA_SM) NKA_BT = NKA_BT + 1
                NKB_BT = LKB_SM/LEN_KB_BAT
                IF(NKB_BT*LEN_KB_BAT. LT. LKB_SM) NKB_BT = NKB_BT + 1
C
                NCA_BT = LICA_SM/MAXLB
                IF(NCA_BT*MAXLB.LT.LICA_SM) NCA_BT = NCA_BT + 1
                NCB_BT = LICB_SM/MAXLB
                IF(NCB_BT*MAXLB.LT.LICB_SM) NCB_BT = NCB_BT + 1
                NAA_BT = LIAA_SM/MAXLB
                IF(NAA_BT*MAXLB.LT.LIAA_SM) NAA_BT = NAA_BT + 1
                NAB_BT = LIAB_SM/MAXLB
                IF(NAB_BT*MAXLB.LT.LIAB_SM) NAB_BT = NAB_BT + 1
C               loop over batches
                DO IKA_BT = 1, NKA_BT
                  DO IKB_BT = 1, NKB_BT
                    IKA_B  = (IKA_BT-1)*LEN_KA_BAT + 1
                    IKA_E  = MIN(LKA_SM,IKA_B + LEN_KA_BAT - 1)
                    NKA_B  = IKA_E - IKA_B + 1
                    NKA_B0 = NKA_B
                    IKB_B  = (IKB_BT-1)*LEN_KB_BAT + 1
                    IKB_E  = MIN(LKB_SM,IKB_B +  LEN_KB_BAT - 1)
                    NKB_B  = IKB_E - IKB_B + 1
                    NKB_B0 = NKB_B
C                   loop over annihilation batches
                    DO IAA_BT = 1, NAA_BT
                      IAA_B = (IAA_BT-1)*MAXLB + 1
                      IAA_E = MIN(LIAA_SM,IAA_B + MAXLB -1)
                      NAA_B = IAA_E-IAA_B+1
C                     KA => JA mapping
                      IUB_KJ = 1
!                     print *,'KASM, IAA_SM, invelm(KASM) ==> ',
!    &                         KASM, IAA_SM, invelm(KASM)
                  CALL K_TO_J_TOT(KJAD,XKJAD,KASM , IKA_B,IKA_E,
     &                                IAA_STR,NAA_B,IAA_B,IAA_E,
     &                                I3,XI3S,IB_AA,NJKAINTM,NAA_OP,
     &                                IZEROKAJA,IUB_KJ)
!                     print *,'IZEROKAJA ==> ',IZEROKAJA
                      IF(IZEROKAJA.EQ.0) THEN
                        DO IAB_BT = 1, NAB_BT
C                         B(eginning) and E(nd) of each Batch
                          IAB_B = (IAB_BT-1)*MAXLB + 1
                          IAB_E = MIN(LIAB_SM,IAB_B + MAXLB -1)
                          NAB_B = IAB_E-IAB_B+1
C                         KB => JB mapping
                          IUB_KJ = 2
!                      print *,'KBSM, IAB_SM, invelm(IAB_SM) ==> ',
!    &                          KBSM, IAB_SM,invelm(IAB_SM)
                  CALL K_TO_J_TOT(KJBD,XKJBD,        KBSM, IKB_B,IKB_E,
     &                                    IAB_STR,NAB_B,IAB_B,
     &                                    IAB_E,I4,XI4S,IB_AB,NJKBINTM,
     &                                    NAB_OP,IZEROKBJB,IUB_KJ)
!                         print *,'IZEROKBJB ==> ',IZEROKBJB
                          IF(IZEROKBJB.EQ.0) THEN
C                           loop over creation batches 
                            DO ICA_BT = 1, NCA_BT
                              ICA_B = (ICA_BT-1)*MAXLB + 1
                              ICA_E = MIN(LICA_SM,ICA_B + MAXLB -1)
                              NCA_B = ICA_E-ICA_B+1
C                             KA => IA mapping
                              IUB_KJ = 1
!                           print *,'ICA_BT: enter K_TO_J_TOT'
                              CALL K_TO_J_TOT(KIAD,XKIAD,KASM,IKA_B,
     &                                        IKA_E,ICA_STR,
     &                                        NCA_B,ICA_B,ICA_E,I1,
     &                                        XI1S,IB_CA,NIKAINTM,
     &                                        NCA_OP,IZEROKAIA,IUB_KJ)
!                           print *,'ICA_BT: left K_TO_J_TOT',IZEROKAIA
                              IF(IZEROKAIA.eq.0)THEN
                              DO ICB_BT = 1, NCB_BT
                                ICB_B = (ICB_BT-1)*MAXLB + 1
                                ICB_E = MIN(LICB_SM,ICB_B + MAXLB -1)
                                NCB_B = ICB_E-ICB_B+1
C                               KB => IB mapping
                                IUB_KJ = 2
!                           print *,'ICB_BT: enter K_TO_J_TOT'
                                CALL K_TO_J_TOT(KIBD,XKIBD,KBSM,IKB_B,
     &                                          IKB_E,ICB_STR,
     &                                          NCB_B,ICB_B,ICB_E,
     &                                          I2,XI2S,IB_CB,NIKBINTM,
     &                                          NCB_OP,IZEROKBIB,IUB_KJ)
!                           print *,'ICB_BT: left K_TO_J_TOT',IZEROKBIB
                                IF(IZEROKBIB.eq.0)THEN
C                                 Compress Ka and Kb strings to active subset 
C                                 Ka
                                  CALL COMPRS2LST_B(KIAD,XKIAD,NCA_B,
     &                                              KJAD,XKJAD,NAA_B,
     &                                              NKA_B0,NKA_B,KIA,
     &                                              XKIA,KJA,XKJA)
C                                 Kb
                                  CALL COMPRS2LST_B(KIBD,XKIBD,NCB_B,
     &                                              KJBD,XKJBD,NAB_B,
     &                                              NKB_B0,NKB_B,KIB,
     &                                              XKIB,KJB,XKJB)
                                  IM_ACTIVE = 1
C                                 offset and form of T-coefficients
!                           print *,'after COMPRS2LST_B'
                                  ITOFF = 
     &                            IB_T(ICA_SM,ICB_SM,IAA_SM_ADJ)
!                               WRITE(LUWRT,*) 
!    &                        ' output of IB_T for current block',ITOFF
                                  IDIAG = 0
                                  IF(ITOFF.LT.0) THEN
                                    ITOFF = -ITOFF
                                    ITRNSP = 1
                                  ELSE
                                    ITRNSP = 0
                                  END IF
C
                                  IF(ISD.EQ.1) THEN
                                    if ((IRIS.eq.1.and.IRIC.eq.2).or.
     &                                  (IRIS.eq.2.and.IRIC.eq.1)) then
                                      if( SPLIT_IJKL )then
                                        ITOFF = ITOFF + LEN_T_BUFF
                                      end if
                                    end if
                                    CALL TCC_SUBBLK(TB(ITOFF),
     &                                              T_BUFF(ITOFF),
     &                                              T_SCR_CC(ITOFF),
     &                                              TBSUB,1,LICA_SM,
     &                                              NCA_B,ICA_B,
     &                                              LICB_SM,NCB_B,ICB_B,
     &                                              LIAA_SM,NAA_B,IAA_B,
     &                                              LIAB_SM,NAB_B,IAB_B,
     &                                              ITRNSP,IDIAG,NTEST)
                                  ELSE
C                                   zero density subblock
                                    CALL DZERO(TBSUB,
     &                                         NCA_B*NCB_B*NAA_B*NAB_B)
                                  END IF
C  
C                                 C(Ka,Kb,Iaa,Iab) = sum(Ja,Jb) <Ka!Iaa!Ja><Kb!Iab!Jb> C(Ja,Jb)
C                                 -------------------------------------------------------------
                                  CALL C_TO_CKK(CB(ICBOFF),CJRES,1,
     &                                          NJA(JASM),NJB(JBSM),
     &                                          NKA_B,NKB_B,NAA_B,NAB_B,
     &                                          KJA,XKJA,KJB,XKJB)
C
                                  IF(ISD.EQ.2) THEN
                                    CALL C_TO_CKK(SB(ISBOFF),SIRES,1,
     &                                            NIA(IASM),NIB(IBSM),
     &                                            NKA_B,NKB_B,NCA_B,
     &                                            NCB_B,KIA,XKIA,KIB,
     &                                            XKIB)
                                  END IF
!          print '(a,6i3)', 
!    &     ' calc sigma ==> IASM, IBSM, JASM, JBSM, KASM, KBSM', 
!    &                      IASM, IBSM, JASM, JBSM, KASM, KBSM
C
C                                 ISD == 1:
C                                 SIRES(Ka,Kb,Ica,Icb) = CJRES(Ka,Kb,Iaa,Iab)*T(Ica,Icb,Iaa,Iab)
C                               ----------------------------------------------------------------
C                                 ISD == 2:
C                                 T(Ica,Icb,Iaa,Iab)   = SIRES(Ka,Kb,Ica,Icb)*CJRES(Ka,Kb,Ica,Icb)
C                                 ----------------------------------------------------------------
                                  LKAB = NKA_B*NKB_B
                                  LCAB = NCA_B*NCB_B 
                                  LAAB = NAA_B*NAB_B
                                  FACTORC = 0.0D0
                                  FACTORAB = 1.0D0*SIGNXXX
C                                 statistics
                                  XNCALL = XNCALL + 1
                                  T_INI = Second()
C
#if defined (VAR_MPI2)
                                  xxxsitime = interface_MPI_WTIME()
#endif
                                  IF(ISD.EQ.1) THEN
C
C                                   call DGEMM - statistics
                                    XLCROW = XLCROW + LKAB
                                    XLCCOL = XLCCOL + LCAB
                                    XLCROWCOL = XLCROWCOL + LKAB*LCAB
                                    XNFLOP = XNFLOP + 2*LKAB*LCAB*LAAB
C                                   input
                                    LDA = MAX(1,LKAB)
                                    LDB = MAX(1,LCAB)
C                                   output
                                    LDC = MAX(1,LKAB)
C
                                    CALL DGEMM('N','T',LKAB,LCAB,LAAB,
     &                                         FACTORAB,CJRES,LDA,TBSUB,
     &                                         LDB,FACTORC,SIRES,LDC)
                                  ELSE
C
C                                   call DGEMM - statistics
                                    XLCROW = XLCROW + LCAB
                                    XLCCOL = XLCCOL + LAAB
                                    XLCROWCOL = XLCROWCOL + LCAB*LAAB
                                    XNFLOP = XNFLOP + 2*LCAB*LAAB*LKAB
C                                   input
                                    LDA = MAX(1,LKAB)
                                    LDB = MAX(1,LKAB)
C                                   output
                                    LDC = MAX(1,LCAB)
C
                                    CALL DGEMM('T','N',LCAB,LAAB,LKAB,
     &                                         FACTORAB,SIRES,LDA,CJRES,
     &                                         LDB,FACTORC,TBSUB,LDC)
C
                                  END IF
C
                                  T_END = Second()
                                  TMULT = TMULT + T_END - T_INI
C
#if defined (VAR_MPI2)
                                  xcomputesi = xcomputesi - xxxsitime 
     &                                       + interface_MPI_WTIME()
#endif
C                                 ISD == 1:
C                                 S(Ia,IB) = SI(Ia,Ib) + <Ka!O+_ca!Ia><Kb!O+cb!Ib>SIRES(Ka,Kb,Ica,Icb)
C                                 ----------------------------------------------------------------
C                                 ISD == 2:
C                                 just scatter out to complete density block
C                                 ----------------------------------------------------------------
                                  IF(ISD.EQ.1) THEN
                                    CALL C_TO_CKK(SB(ISBOFF),SIRES,
     &                                            2,NIA(IASM),NIB(IBSM),
     &                                            NKA_B,NKB_B,NCA_B,
     &                                            NCB_B,KIA,XKIA,KIB,
     &                                            XKIB)
!                                   print *,'ISBOFF, length',
!    &                                       ISBOFF,NIA(IASM)*NIB(IBSM)
                                  ELSE IF(ITRNSP.EQ.0) THEN
                                    if ((IRIS.eq.1.and.IRIC.eq.2).or.
     &                                  (IRIS.eq.2.and.IRIC.eq.1)) then
                                      if( SPLIT_IJKL )then
                                        ITOFF = ITOFF + LEN_T_BUFF
                                      end if
                                    end if
                                    CALL TCC_SUBBLK(TB(ITOFF),
     &                                              T_BUFF(ITOFF),
     &                                              T_SCR_CC(ITOFF),
     &                                              TBSUB,2,
     &                                              LICA_SM,NCA_B,ICA_B,
     &                                              LICB_SM,NCB_B,ICB_B,
     &                                              LIAA_SM,NAA_B,IAA_B,
     &                                              LIAB_SM,NAB_B,IAB_B,
     &                                              ITRNSP,IDIAG,NTEST)
                                  END IF
                                END IF ! if all maps are nonvanishings
                              END DO
                              END IF ! IZEROKAIA
                            END DO ! loop over batches of creation   operators
                          END IF ! if batch of beta annihilation was nontrivial
                        END DO
                      END IF ! if batch of alpha annihilation was nontrivial
                    END DO ! loop over batches of annihilation operators
                  END DO
                END DO ! loop over batches of Ka,Kb
              END IF ! if symmetry combinations have nonvanishing dimensions
            END DO ! loop over KBSM
  100     CONTINUE ! loop over KASM
 2002     CONTINUE ! skip c-block not included in active-block-list (parallel run)
#if defined (VAR_MPI2)
          I_BLK_C_SCR = I_BLK_C_SCR + 1
#endif
        END DO ! loop over JASM
 3003   CONTINUE ! skip s-block not included in node-list (parallel run)
#if defined (VAR_MPI2)
        I_BLK_S_SCR = I_BLK_S_SCR + 1
#endif
       END DO ! loop over IASM
      END IF ! if Ka and Kb are nontrivial strings
C
 9999 RETURN
!#undef LUCI_DEBUG
      END
!*****************************************************************
      SUBROUTINE New_GNSIDE_REL_opt(ISD,IRIS,IRIC,ICA,ICB,IAA,IAB,
     &           IAOC,IBOC,JAOC,JBOC,
     &           NIA,NIB,NJA,NJB,
     &           TB,T_BUFF,T_SCR_CC,IXTP,
     &           SB,CB,ISSM,ICSM,
     &           I1,XI1S,I2,XI2S,I3,XI3S,I4,XI4S,
     &           TBSUB,CJRES,SIRES,MAXLB,
!     &           TBSUB,CJRES,SIRES,MAXLBORIG,
     &           ICA_STR,ICB_STR,IAA_STR,IAB_STR,
     &           KJA,XKJA,KJB,XKJB,KIA,XKIA,KIB,XKIB,
     &           KJAD,XKJAD,KJBD,XKJBD,KIAD,XKIAD,KIBD,XKIBD,
     &           SIGN_EXTERNAL,IPRS,IPRD,ISMDST,
     &           NICA,NICB,NIAA,NIAB,NKA,NKB,
     &           IB_CA,IB_CB,IB_AA,IB_AB,IB_T,
     &           NIKAINTM,NIKBINTM,NJKAINTM,NJKBINTM,
     &           L_Sym_Block,L_A_Block,L_B_Block,INum_Sym_A,
     &           ISym_AA,ISym_AB,IAA_SM_STR_S,IAB_SM_STR_S,
     &           IAA_SM_STR_E,IAB_SM_STR_E,NSubBlk_A,NStrings_A,
     &           INum_Sym_C,ISym_CA,ISym_CB,ICA_SM_STR_S,
     &           ICB_SM_STR_S,ICA_SM_STR_E,ICB_SM_STR_E,NSubBlk_C,
     &           NStrings_C,CJRES_BAT,SIRES_BAT,T_BAT
#if defined (VAR_MPI2)
     &          ,IOFF_BLK_C,IOFF_BLK_S,IACT_C,IACT_S
#endif
     &           )

      use mospinor_info
      use symmetry_setup_krci
      use interface_to_mpi
      implicit none
!      implicit real*8(A-H,O-Z)
#include "ipoist8.inc"
#if defined (VAR_MPI2)
#include "infpar.h"
#endif
*. General input
#include "mxpdim.inc"
#include "gasstr.inc"
#include "cgas.inc"
#include "ctcc.inc"
#include "parluci.h"
#include "krmc_shmem.h"
*     
*.Input
      real(8) CB(*)
!      double precision CB(*)
!     dimension CB(*) 
      integer NIA(*),NIB(*),NJA(*),NJB(*)
      integer IAOC(*),IBOC(*),JAOC(*),JBOC(*)
      integer ICA(*),ICB(*),IAA(*),IAB(*)
      integer ISD, IRIS, IRIC, IPRS, IPRD, ICSM, ISSM !7/5/18 was implicit before

#if defined (VAR_MPI2)
      integer IACT_C(*), IACT_S(*)
      integer LEN_TT_BLOCK_PAR
      integer IOFF_BLK_C, IOFF_BLK_S
      integer I_BLK_S_SCR, I_BLK_C_SCR
      real(8) xxxsitime
      integer IC_Blk

#else
      integer LEN_T_BUFF !Defined in a common block for MPI
#endif
      double precision SIGN_EXTERNAL
*.Input or Output
      real(8) SB(*)
!      double precision SB(*)
!      DIMENSION SB(*)
      real(8) TB(*), T_BUFF(*)
!      double precision TB(*), T_BUFF(*)
!      dimension TB(*), T_BUFF(*)
*.Local Scratch
      integer KAOC(MXPNGAS), KBOC(MXPNGAS)
      integer KAGP(MXPNGAS), KBGP(MXPNGAS)
      integer JAGP(MXPNGAS), JBGP(MXPNGAS)
      integer ICAGP(MXPNGAS),ICBGP(MXPNGAS)
      integer IAAGP(MXPNGAS),IABGP(MXPNGAS)

*. 
      integer ICA_EXP(MXNOP),ICB_EXP(MXNOP)
      integer IAA_EXP(MXNOP),IAB_EXP(MXNOP)

      integer IB_C(MXNDGIRR),IB_S(MXNDGIRR)
*. Scratch through input 
      integer I1(*), I2(*), I3(*), I4(*), ISMDST(*)
      double precision    XI1S(*), XI2S(*), XI3S(*), XI4S(*)
      real(8)    TBSUB(*), T_SCR_CC(*)
!      double precision    TBSUB(*), T_SCR_CC(*)
!      DIMENSION I1(*),XI1S(*),I2(*),XI2S(*)
!      DIMENSION I3(*),XI3S(*),I4(*),XI4S(*)
!      DIMENSION TBSUB(*), T_SCR_CC(*)
!      DIMENSION ISMDST(*)
      integer MAXLB
!      Integer, parameter :: MAXLB = 4
!Change back when done with this subroutine
      integer    KJA(MAXLB), KJB(MAXLB), KIA(MAXLB), KIB(MAXLB)
      double precision XKJA(*),XKJB(*),XKIA(*),XKIB(*)
!      DIMENSION XKJA(*),XKJB(*),XKIA(*),XKIB(*)
      integer    KJAD(MAXLB), KJBD(MAXLB), KIAD(MAXLB), KIBD(MAXLB)
!      INTEGER    KJAD(*), KJBD(*), KIAD(*), KIBD(*)
!      double precisin XKJAD(*),XKJBD(*),XKIAD(*),XKIBD(*)
      real(8) XKJAD(*),XKJBD(*),XKIAD(*),XKIBD(*)
!      DIMENSION XKJAD(*),XKJBD(*),XKIAD(*),XKIBD(*)

      integer NICA(MXNDGIRR),NICB(MXNDGIRR)
      integer NIAA(MXNDGIRR),NIAB(MXNDGIRR)
      integer NKA(MXNDGIRR), NKB(MXNDGIRR)

      integer IB_CA(MXNDGIRR,MXNDGIRR,MXNOP) 
      integer IB_CB(MXNDGIRR,MXNDGIRR,MXNOP)
      integer IB_AA(MXNDGIRR,MXNDGIRR,MXNOP)
      integer IB_AB(MXNDGIRR,MXNDGIRR,MXNOP)
      integer IB_T(MXNDGIRR,MXNDGIRR,MXNDGIRR)
      integer NIKAINTM(MXPOBS,MXNOP),NIKBINTM(MXPOBS,MXNOP)
      integer NJKAINTM(MXPOBS,MXNOP),NJKBINTM(MXPOBS,MXNOP)
*. ... Must hold excitations for all intermediate strings of given sym 
*. and all orbitals of given type
      integer ICA_STR(*),ICB_STR(*),IAA_STR(*),IAB_STR(*)
*     ... Must hold strings of given sym for T ops.
      real(8) CJRES(*),SIRES(*)
      real(8) CJRES_BAT(MAXLB**4), SIRES_BAT(MAXLB**4)
      real(8) T_BAT(MAXLB**4)
!      real(8), allocatable :: CJRES_BAT(:), SIRES_BAT(:)
!      real(8), allocatable :: T_BAT(:)
!      DIMENSION CJRES(*),SIRES(*)
*
      !Variables for statistics
      double precision XNFLOP,XNCALL,XLCROW,XLCCOL,XLCROWCOL,TMULT
!      real(8) Batch_time, Cvec_time
!      real(8) T_time, Sigma_time, 
      real(8) Time1, Time2
!      real(8) CalcMatTime
      COMMON/MATMLST/XNFLOP,XNCALL,XLCROW,XLCCOL,XLCROWCOL,TMULT
      double precision T_INI, T_END

      COMMON/CMXCJ/MXCJ
      integer MXCJ, IXTP
      integer*8 ITOFF

!      integer ISD, IRIS, IRIC, ICA(*), ICB(*), IAA(*),IAB(*)
!      integer IAOC(*), IBOC(*), JAOC(*), JBOC(*),
!      integer NIA(*), NIB(*), NJA(*), NJB(*)
      integer LEN_C, LEN_TT_BLOCK, LEN_S !Length of c and function LEN_TT_BLOCK
      integer IASM, IBSM, JASM, JBSM, KSM, KASM, IOPSM
      integer NCA_OP, NCB_OP, NAA_OP, NAB_OP, NPERM !No. of operators
      integer IKA_ZERO, IKB_ZERO, NKADST, NKBDST, NCADST !Look at these
      integer NCBDST, NAADST, NABDST, IAB_MAP !And these
      integer IKA_B, IKA_E, NKA_B, NKA_B0, IKB_B, IKB_E !And these
      integer NKB_B, NKB_B0, NCA_B, NCB_B, NAA_B, NAB_B 
      integer IAA_B, IAA_E, IAB_B, IAB_E, IUB_KJ 
      integer ICA_B, ICA_E, ICB_B, ICB_E
      integer IZEROKAJA, IZEROKBJB, IZEROKAIA, IZEROKBIB
      integer NRSUB, NCSUB, LCAB, LAAB, LKAB
      integer LDA, LDB, LDC
      integer IAA_SM, IAB_SM, IAB_SM_ADJ,IAA_SM_ADJ,IUB,LIAA_SM2  
      integer LIAB_SM2, LICA_SM2, LICB_SM2
      integer IAA_JA_SM, ICA_IA_SM, LKA_SM, KBSM, LKB_SM
      integer LICA_SM, LICB_SM, LIAA_SM, LIAB_SM, ICA_IA_SM_INVELM
      integer IAB_JB_SM, ICB_IB_SM, LEN_KA_BAT, LEN_KB_BAT, NKA_BT
      integer NKB_BT, IKA_BT, IKB_BT 
      integer ICA_ICB_SM, IAA_IAB_SM, LICA_ICB_TOT, ICA_SM
      integer ICB_SM, LIAA_IAB_TOT, LEN_ICA_ICB_BT, LEN_IAA_IAB_BT 
      integer NIAA_IAB_BT, NICA_ICB_BT, Min_Size
      integer IAA_IAB_BT, ICA_ICB_BT
      integer LEN_BLOCK LEN_TMP_BT, IOFFC, IOFFR
      integer ISYM, JSym_A, JSym_C, IBuffer, ISubBlk_A, ISubBlk_C
      integer INum_Sym_A(100),ISym_AA(NSMST,100),ISym_AB(NSMST,100)
      integer IAA_SM_STR_S(2,NSMST,100),IAB_SM_STR_S(2,NSMST,100)
      integer IAA_SM_STR_E(2,NSMST,100),IAB_SM_STR_E(2,NSMST,100)
      integer NSubBlk_A(NSMST,100),NStrings_A(100)
      integer INum_Sym_C(100),ISym_CA(NSMST,100),ISym_CB(NSMST,100)
      integer ICA_SM_STR_S(2,NSMST,100),ICB_SM_STR_S(2,NSMST,100)
      integer ICA_SM_STR_E(2,NSMST,100),ICB_SM_STR_E(2,NSMST,100)
      integer NSubBlk_C(NSMST,100),NStrings_C(100)
      integer L_Sym_Block(NSMST), L_A_Block(NSMST), L_B_Block(NSMST)
      integer NBat_CA_CB(NSMST), NBat_AA_AB(NSMST), IBatch_not_zero

      integer INum_Sym_A_red,ISym_AA_red(NSMST),ISym_AB_red(NSMST)
      integer IAA_SM_STR_S_red(2,NSMST),IAB_SM_STR_S_red(2,NSMST)
      integer IAA_SM_STR_E_red(2,NSMST),IAB_SM_STR_E_red(2,NSMST)
      integer N_SubBlk_A_red(NSMST),N_Strings_A_red

      integer INum_Sym_C_red,ISym_CA_red(NSMST),ISym_CB_red(NSMST)
      integer ICA_SM_STR_S_red(2,NSMST),ICB_SM_STR_S_red(2,NSMST)
      integer ICA_SM_STR_E_red(2,NSMST),ICB_SM_STR_E_red(2,NSMST)
      integer N_SubBlk_C_red(NSMST), N_Strings_C_red

      integer IZeroKJABMap, IZeroKIABMap, IKJA_Off, IKJB_Off
      integer IKIA_Off, IKIB_Off
      logical batch_not_zero
!      integer, allocatable :: INum_Sym_A(:),ISym_AA(:,:),ISym_AB(:,:) 
!      integer, allocatable :: IAA_SM_STR_S(:,:,:), IAB_SM_STR_S(:,:,:)
!      integer, allocatable :: IAA_SM_STR_E(:,:,:), IAB_SM_STR_E(:,:,:)
!      integer, allocatable :: NSubBlk_A(:,:), NStrings_A(:)
!      integer, allocatable :: INum_Sym_C(:),ISym_CA(:,:),ISym_CB(:,:) 
!      integer, allocatable :: ICA_SM_STR_S(:,:,:), ICB_SM_STR_S(:,:,:)
!      integer, allocatable :: ICA_SM_STR_E(:,:,:), ICB_SM_STR_E(:,:,:)
!      integer, allocatable :: NSubBlk_C(:,:), NStrings_C(:)
      !for test purposes
      integer NTEST, NTESTL
!      integer Num_C_str_stat, Num_A_str_stat
      !Transposition/diagonalisation conditions, offsets in arrays
      integer ISKIP, ITRNSP, IDIAG, ICBOFF, ISBOFF, ICJ_OFF, ISI_OFFC
      !print indices
      integer I,J,K 
      real(8) SIGNXXX, XCNORM, XSNORM, DDOT !implicit real before
      real(8) FACTORAB, FACTORC !for matrix multiplication


      !REMEMBER THE FOLLOWING VARIABLES - might need to be removed
      integer MAXLBORIG
      !The following should be allocated further up

      !External function:
!      real(8) DLANGE
      real(8) DNRM2, CNORM

      !Last is intermediate of CPU time
!      double precision, allocatable :: T_BAT(:)

#ifdef GNSIDE_debug
      write(LUWRT,*) '              Welcome to New_GNSIDE'
#endif

*
!     NTESTL = 5000 ! debug
      NTESTL = 0000 
!#define LUCI_DEBUG
      NTEST = MAX(NTESTL,max(IPRS,IPRD))
*
      ISKIP = 0
#if defined (VAR_MPI2)
      LEN_C = LEN_TT_BLOCK_PAR(ICSM,NJA,NJB,IACT_C,IOFF_BLK_C,0)
#else
      LEN_C = LEN_TT_BLOCK(ICSM,NJA,NJB)
      LEN_T_BUFF = 0
#endif
!     print *,'C (input) ==> LEN_C',LEN_C
!     call wrtmat(CB,1,LEN_C,1,LEN_C)
C     check norm
      XCNORM = DDOT(LEN_C,CB,1,CB,1)
      if(XCNORM.EQ.0.0d0) return 
*
C
C     symmetry of operator (Hamiltonian)
C     ----------------------------------
      IOPSM = IDBGMULT(INVELM(ICSM),ISSM)
!
!      print '(a,i4)', ' symmetry of Hamiltonian ==>',IOPSM
!      print '(a,i4)', ' symmetry of c-vector    ==>',ICSM
!      print '(a,i4)', ' symmetry of s-vector    ==>',ISSM
!
C
C     total length of sigma block
#if defined (VAR_MPI2)
      LEN_S = LEN_TT_BLOCK_PAR(ISSM,NIA,NIB,IACT_S,IOFF_BLK_S,1)
#else
      LEN_S = LEN_TT_BLOCK(ISSM,NIA,NIB)
#endif
!     print *,'LEN_S is',LEN_S
      if(LEN_S.eq.0) return
      if(ISD.EQ.2)then ! check S norm (only density runs)
        XSNORM = DDOT(LEN_S,SB,1,SB,1)
        if(XSNORM.EQ.0.0D0) return
      end if
#if defined (VAR_MPI2)
C
C     vector partitioning has been changed! we have to be careful
C     calculating the proper offset for each block ( sigma and c )!!!
C
C     adapted offset of c and sigma routines
        Time1 = interface_mpi_wtime()
      call IOFF_SYMBLK_MAT_PAR(NSMST,NJA,NJB,ICSM,IB_C,
     &                         IACT_C,IOFF_BLK_C,0)
      call IOFF_SYMBLK_MAT_PAR(NSMST,NIA,NIB,ISSM,IB_S,
     &                         IACT_S,IOFF_BLK_S,1)
C
#else
C     offset of c and sigma routines
      call IOFF_SYMBLK_MAT(NSMST,NJA,NJB,ICSM,IB_C)
      call IOFF_SYMBLK_MAT(NSMST,NIA,NIB,ISSM,IB_S)
#endif
C     types of strings in T in groupnotation
      call OCC_TO_GRP(ICA,ICAGP,1)
      call OCC_TO_GRP(ICB,ICBGP,1)
      call OCC_TO_GRP(IAA,IAAGP,1)
      call OCC_TO_GRP(IAB,IABGP,1)

#ifdef LUCI_DEBUG
      write(6,*) ' GNSID... Output from OCC_TO_GRP : '
      write(6,*) ' ICA_GRP : ',(ICAGP(I),I=1,NGAS,1)
      write(6,*) ' ICB_GRP : ',(ICBGP(I),I=1,NGAS,1)
      write(6,*) ' IAA_GRP : ',(IAAGP(I),I=1,NGAS,1)
      write(6,*) ' IAB_GRP : ',(IABGP(I),I=1,NGAS,1)
#endif
C     operators in T in expanded form
      call REF_OP(ICA,ICA_EXP,NCA_OP,NGAS,1,MXNOP)
      call REF_OP(ICB,ICB_EXP,NCB_OP,NGAS,1,MXNOP)
      call REF_OP(IAA,IAA_EXP,NAA_OP,NGAS,1,MXNOP)
      call REF_OP(IAB,IAB_EXP,NAB_OP,NGAS,1,MXNOP)
C          REF_OP(IOPGAS,IOP,NOP,NGAS,IWAY)
C     sign for bringing operators and amplitudes into new order
      NPERM =  NAA_OP* NCB_OP 
     &       + NAA_OP*(NAA_OP-1)/2
     &       + NAB_OP*(NAB_OP-1)/2
      if(MOD(NPERM,2).EQ.1) then
        SIGNXXX  =  -1.0D0*SIGN_EXTERNAL
!       WRITE(LUWRT,*) ' new SIGNXXX for type IXTP =',IXTP
      else
!       WRITE(LUWRT,*) ' old SIGNXXX for type IXTP =',IXTP
        SIGNXXX = SIGN_EXTERNAL
      end if



C     type of Ka and Kb
      call CCEX_OCC_OCC(JAOC,KAOC,NGAS,IAA,IKA_ZERO)
      call CCEX_OCC_OCC(JBOC,KBOC,NGAS,IAB,IKB_ZERO)

C     check that annihilation has not acted upon empty GAS:
!#define GNSIDE_debug
      if(IKA_ZERO.EQ.0.AND.IKB_ZERO.EQ.0) then
C       get group of K mapped occupations
        call occ_to_grp(KAOC,KAGP,1)
        call occ_to_grp(KBOC,KBGP,1)
C       number of strings in this supergroup (new DBG routine)
!       NEL_KA = IELSUM(KAOC,NGAS)
!       NEL_KB = IELSUM(KBOC,NGAS)
        do KSM = 1, NSMST
          call nst_spgrp_dbg(NGAS,KAGP,KSM,NSMST,NKA(KSM),NKADST,1)
!         call getstr2_totsm_spgp_rel(1,KAGP,NGAS,KSM,NEL_KA,
!    &                                NKA(KSM),NKADST)
          call nst_spgrp_dbg(NGAS,KBGP,KSM,NSMST,NKB(KSM),NKBDST,2)
!         call getstr2_totsm_spgp_rel(2,KBGP,NGAS,KSM,NEL_KB,
!    &                                NKB(KSM),NKBDST)
        end do
!       NEL_CA = IELSUM(ICA,NGAS)
!       NEL_CB = IELSUM(ICB,NGAS)
!       NEL_AA = IELSUM(IAA,NGAS)
!       NEL_AB = IELSUM(IAB,NGAS)
C       number of strings in excitation ops
        do ISYM = 1, NSMST

!         call getstr2_totsm_spgp_rel(1,ICAGP,NGAS,ISYM,NEL_CA,
!    &                                NICA(ISYM),NCADST)
!         call getstr2_totsm_spgp_rel(2,ICBGP,NGAS,ISYM,NEL_CB,
!    &                                NICB(ISYM),NCBDST)
!         call getstr2_totsm_spgp_rel(1,IAAGP,NGAS,ISYM,NEL_AA,
!    &                                NIAA(ISYM),NAADST)
!         call getstr2_totsm_spgp_rel(2,IABGP,NGAS,ISYM,NEL_AB,
!    &                                NIAB(ISYM),NABDST)
          call nst_spgrp_dbg(NGAS,ICAGP,ISYM,NSMST,NICA(ISYM),NCADST,1)
          call nst_spgrp_dbg(NGAS,ICBGP,ISYM,NSMST,NICB(ISYM),NCBDST,2)
          call nst_spgrp_dbg(NGAS,IAAGP,ISYM,NSMST,NIAA(ISYM),NAADST,1)
          call nst_spgrp_dbg(NGAS,IABGP,ISYM,NSMST,NIAB(ISYM),NABDST,2)
        end do
C       offset for symmetryblocks of T
        call Z_TCC_OFF_opt(IB_T,NICA,NICB,NIAA,NIAB,IOPSM)
C            Z_TCC_OFF(IBT,NCA,NCB,NAA,NAB,ITSYM)
C       creation path from C/S strings to K strings
C       mappings from !I> to !K> are annihilations mappings 

C       CA : KA => IA mappings in 1
C            MAP_EXSTR(IOP,IAC,NOP,IREFOC,IX,SX,NK,IB,ISMDST,IAB)
        IAB_MAP = 1
        call MAP_EXSTR(ICA_EXP,NCA_OP,IAOC,I1,XI1S,
     &                 NIKAINTM,IB_CA,ISMDST,IAB_MAP)
C       CB : KB => IB     
        IAB_MAP = 2
        call MAP_EXSTR(ICB_EXP,NCB_OP,IBOC,I2,XI2S,
     &                 NIKBINTM,IB_CB,ISMDST,IAB_MAP)
C       AA : KA => JA
        IAB_MAP = 1
        call MAP_EXSTR(IAA_EXP,NAA_OP,JAOC,I3,XI3S,
     &                 NJKAINTM,IB_AA,ISMDST,IAB_MAP)
C       AB : KB => JB
        IAB_MAP = 2
        call MAP_EXSTR(IAB_EXP,NAB_OP,JBOC,I4,XI4S,
     &                 NJKBINTM,IB_AB,ISMDST,IAB_MAP)
C       loop over symmetry-blocks of C and Sigma
#if defined (VAR_MPI2)
C       initialize offsets for sigma-block and c block loop
        I_BLK_S_SCR = 0
        I_BLK_S_SCR = IOFF_BLK_S
        I_BLK_C_SCR = 0
        I_BLK_C_SCR = IOFF_BLK_C
!
        Time2 = interface_mpi_wtime()
        Start_Gnside = Start_Gnside + Time2 - Time1
#endif
!Now we start the loops        

      IBuffer = 1
      !Buffer parameter so that batches do not consist of too small
      !subblocks
      Min_Size = (MaxLB - IBuffer)**2

      do KASM = 1, NSMST !Resolution string: K up symmetry
         LKA_SM = NKA(KASM)
!         write(LUWRT,*) 'KASM = ',KASM
!         write(LUWRT,*) 'LKA_SM = ',LKA_SM

         IF(LKA_SM==0) cycle !No elements for symmetry KASM
         !IAA_JA_SM is symmetry of annihilator UP C UP string
         IAA_JA_SM = KASM
         ICA_IA_SM = INVELM(KASM) !Symmetry of C UP S UP string
         ICA_IA_SM_INVELM = INVELM(ICA_IA_SM)

!         write(LUWRT,*) 'KASM, IAA_JA_SM, ICA_IA_SM '
!     &   , KASM, IAA_JA_SM, ICA_IA_SM
       KB_SM:  do KBSM = 1, NSMST !K down symmtry
            LKB_SM = NKB(KBSM)
            IF(LKB_SM==0) cycle KB_SM !No elements for symmetry KBSM

            IAB_JB_SM = KBSM
            ICB_IB_SM = INVELM(KBSM)

         Call IZero(NBat_CA_CB,NSMST)
         Call IZero(NBat_AA_AB,NSMST)
         IBatch_not_zero = 0
         Batch_not_zero = .false.

         CA_CB_SM_BT: Do ICA_ICB_SM = 1,NSMST

            !Symmetry of whole annihilator string
            IAA_IAB_SM = IDBGMULT(INVELM(ICA_ICB_SM),IOPSM)
            LICA_ICB_TOT = 0
!                     write(LUWRT,*) 'Creation length loop'
!#if defined (VAR_MPI2)
!            ca_b_sm_start = interface_mpi_wtime()
!#endif
            !Finding total number of creation strings
            do ICA_SM = 1, NSMST

               IASM =
     &         IDBGMULT(ICA_SM,ICA_IA_SM_INVELM)

#if defined (VAR_MPI2)
               I_BLK_S_SCR = 0
               I_BLK_S_SCR = IOFF_BLK_S + IASM - 1
               if(IACT_S(I_BLK_S_SCR).ne.MYPROC) then
!                  write(LUWRT,*) 'IASM, MYPROC',IASM,MYPROC
!                  write(LUWRT,*) 
                  cycle !ICA_SM
               end if
#endif
               ICB_SM =
     &         IDBGMULT(INVELM(ICA_SM),ICA_ICB_SM)

               LICA_SM = NICA(ICA_SM)
               LICB_SM = NICB(ICB_SM)
#if defined (VAR_MPI2)
               if(LICA_SM*LICB_SM==0) cycle !ICA_SM
#endif
               IBSM =
     &         IDBGMULT(ISSM,INVELM(IASM))
               !Checking if the determinant string
               !symmetries may mix
               if(IBSM/=IDBGMULT(ICB_SM,INVELM(ICB_IB_SM))) cycle
                        
#if !defined (VAR_MPI2)
               if(NIA(IASM)*NIB(IBSM)*
     &         LICA_SM*LICB_SM.eq.0) then 
                  cycle !ICA_SM
!                 write(LUWRT,*) 'ICA_ICB_SM ',ICA_ICB_SM
!                 write(LUWRT,*) 'IAA_IAB_SM ',IAA_IAB_SM
!                 write(LUWRT,*) 'Elements for'
!                 write(LUWRT,*) 'IASM, IBSM =',IASM,IBSM
!                 write(LUWRT,*) 
!                 write(LUWRT,*) 'NIA(IASM),NIB(IBSM) ='
!                 write(LUWRT,*) NIA(IASM),NIB(IBSM)
!                 write(LUWRT,*) 'Elements for'
!                 write(LUWRT,*) 'ICA_SM, ICB_SM=',ICA_SM,ICB_SM
!                 write(LUWRT,*) 'NICA(ICA_SM),NICB(ICB_SM) ='
!                 write(LUWRT,*) NICA(ICA_SM),NICB(ICB_SM)
               end if
#endif
!                        write(LUWRT,*) 'ICA_SM =',ICA_SM
!                        write(LUWRT,*) 'ICB_SM =',ICB_SM
!                        write(LUWRT,*) 'NICA(ICA_SM) =',NICA(ICA_SM)
!                        write(LUWRT,*) 'NICB(ICB_SM) =',NICB(ICB_SM)
                LICA_ICB_TOT = LICA_ICB_TOT +
     &          LICA_SM*LICB_SM
            end do !ICA_SM

!#if defined (VAR_MPI2)
!            ca_b_sm_end = interface_mpi_wtime()
!            ca_b_sm_tot = ca_b_sm_tot + ca_b_sm_end - ca_b_sm_start
!#endif

            if(LICA_ICB_TOT==0) then 
               cycle CA_CB_SM_BT 
               !No creation elements for this symmetry
            end if

!                     write(LUWRT,*) 'LICA_ICB_TOT =', LICA_ICB_TOT
!Put in some buffer

            LEN_ICA_ICB_BT = Min_Size
            if(LICA_ICB_TOT < Min_Size) then
               LEN_ICA_ICB_BT = LICA_ICB_TOT
            end if
!Number of creation batches
            NICA_ICB_BT = LICA_ICB_TOT/LEN_ICA_ICB_BT
            if(NICA_ICB_BT*LEN_ICA_ICB_BT < LICA_ICB_TOT) then
               NICA_ICB_BT = NICA_ICB_BT + 1
            end if
            if(NICA_ICB_BT>=100) then
               write(LUWRT,*) 'TOO MANY BATCHES'
               stop
            end if
!Find number of up/down annihilation batches

!           write(LUWRT,*) 'Annihilation length loop'
            LIAA_IAB_TOT = 0
!                     write(LUWRT,*) 'Just before AA and AB section'
!#if defined (VAR_MPI2)
!            aa_b_sm_start = interface_mpi_wtime()
!#endif

            do IAA_SM = 1, NSMST !Annihilation up symmetry
               !Finding total number of annihilation strings
               JASM = IDBGMULT(IAA_JA_SM,INVELM(IAA_SM))
#if defined (VAR_MPI2)
               I_BLK_C_SCR = 0
               I_BLK_C_SCR = IOFF_BLK_C + JASM - 1
               if(IACT_C(I_BLK_C_SCR).eq.0) then
!                  write(LUWRT,*) 'JASM',JASM
!                  write(LUWRT,*) 'No s-c connections'
                  cycle !IAA_SM
               end if
#endif
               IAB_SM = IDBGMULT(IAA_IAB_SM,INVELM(IAA_SM))
               LIAA_SM = NIAA(INVELM(IAA_SM))
               LIAB_SM = NIAB(INVELM(IAB_SM))
#if defined (VAR_MPI2)
               if(LIAA_SM*LIAB_SM==0) cycle !IAA_SM
#endif

               JBSM = IDBGMULT(ICSM,INVELM(JASM))
               !Checking if the determinant string
               !symmetries may mix
               if(JBSM/=IDBGMULT(IAB_JB_SM,INVELM(IAB_SM))) cycle
               !IAA_SM

#if !defined (VAR_MPI2)
               if(NJA(JASM)*NJB(JBSM)*
     &         LIAA_SM*LIAB_SM.eq.0) then 
                  cycle !IAA_SM
!                              else
!                        write(LUWRT,*) 'Elements for'
!                        write(LUWRT,*) 'JASM, JBSM =',JASM,JBSM
!                        write(LUWRT,*) 'NJA(JASM),NJB(JBSM) ='
!                        write(LUWRT,*) NJA(JASM),NJB(JBSM)
!                        write(LUWRT,*) 'Elements for'
!                        write(LUWRT,*) 'IAA_SM, IAB_SM=',IAA_SM,IAB_SM
!                        write(LUWRT,*) 'NIAA(IAA_SM),NIAB(IAB_SM) ='
!                        write(LUWRT,*)
!     &                  NIAA(INVELM(IAA_SM)),NIAB(INVELM(IAB_SM))
               end if
#endif
               LIAA_IAB_TOT = LIAA_IAB_TOT +
     &         LIAA_SM*LIAB_SM

             end do !IAA_SM
!Put in some buffer

!#if defined (VAR_MPI2)
!             aa_b_sm_end = interface_mpi_wtime()
!             aa_b_sm_tot = aa_b_sm_tot + aa_b_sm_end - aa_b_sm_start
!#endif
             if(LIAA_IAB_TOT==0) then
                   cycle CA_CB_SM_BT 
                   !No annihilation elements for this
             else
                IBatch_not_zero = 1
                Batch_not_zero = .true.
             end if

!            write(LUWRT,*) 'WAHEY, non-zero number elements'
!            write(LUWRT,*) 'LICA_ICB_TOT = ',LICA_ICB_TOT
!            write(LUWRT,*) 'LIAA_IAB_TOT = ',LIAA_IAB_TOT
!            write(LUWRT,*) 'ICA_ICB_SM = ',ICA_ICB_SM
!            write(LUWRT,*) 'IAA_IAB_SM = ',IAA_IAB_SM

             LEN_IAA_IAB_BT = Min_Size
             if(LIAA_IAB_TOT < Min_Size) then
!                write(LUWRT,*) 
!     &          'Total block length smaller than Min_Size'
                LEN_IAA_IAB_BT = LIAA_IAB_TOT
             end if

!                     write(LUWRT,*) 'Length of each Anni. batch '
!     &               ,LEN_IAA_IAB_BT
             !Number of annihilation batches
             NIAA_IAB_BT = LIAA_IAB_TOT/LEN_IAA_IAB_BT
             if(NIAA_IAB_BT*LEN_IAA_IAB_BT < LIAA_IAB_TOT) then
                NIAA_IAB_BT = NIAA_IAB_BT + 1
             end if

             if(NIAA_IAB_BT>=100) then
                write(LUWRT,*) 'TOO MANY BATCHES'
                stop
             end if

             NBat_CA_CB(ICA_ICB_SM) = NICA_ICB_BT
             NBat_AA_AB(ICA_ICB_SM) = NIAA_IAB_BT

#if defined (VAR_MPI2)
                     Time1 = interface_MPI_WTIME()
#else                     
                     call CPU_time(Time1)
#endif
                     !Distributing annihilation elements in batches
                     call DST_BLOCKS_OVER_BATCHES(.false.,NIAA_IAB_BT,
     &                     IAA_IAB_SM,NIAA,NIAB,
     &                     MaxLB,Min_Size,
     &                     NJA,NJB,ICSM,IAA_JA_SM,IAB_JB_SM,
     &                     INum_Sym_A,ISym_AA,ISym_AB,IAA_SM_STR_S,
     &                     IAB_SM_STR_S,IAA_SM_STR_E,IAB_SM_STR_E,
     &                     NSubBlk_A,NStrings_A,
     &                     L_A_Block,L_B_Block,L_Sym_Block
#if defined (VAR_MPI2)
     &                     , IOFF_BLK_C,IACT_C
#endif
     &                     )

                     !Statistics on number of strings
                     Do I=1,NIAA_IAB_BT
                     Num_A_str_stat = Num_A_Str_stat + NStrings_A(I)
                     End do
                     Ave_Num_A_str =
     &                dble(Num_A_str_stat)/dble(NIAA_IAB_BT)


!                     write(LUWRT,*) '  Now NIAA_IAB_BT = ', NIAA_IAB_BT
!                        write(LUWRT,*) 'INum_Sym_A(1) = ',INum_Sym_A(1)
!                     do I=1,NIAA_IAB_BT
!                        write(LUWRT,*) 'Batch number ',I
!                        write(LUWRT,*) 'INum_Sym_A(I) = ',INum_Sym_A(I)
!                        do J=1,INum_Sym_A(I)
!                           write(LUWRT,*) 'SymAA(I) = ', ISym_AA(J,I)
!                           write(LUWRT,*) 'SymAB(I) = ', ISym_AB(J,I)
!                           write(LUWRT,*) 'No. of sub blocks
!     &                     ',NSubBlk_A(J,I)
!                           do K=1,NSubBlk_A(J,I)
!                              write(LUWRT,*) 'String start AA = '
!     &                        ,IAA_SM_STR_S(K,J,I)
!                              write(LUWRT,*) 'String end AA = '
!     &                        ,IAA_SM_STR_E(K,J,I)
!                              write(LUWRT,*) 'String start AB = '
!     &                        ,IAB_SM_STR_S(K,J,I)
!                              write(LUWRT,*) 'String end AB = '
!     &                        ,IAB_SM_STR_E(K,J,I)
!
!                           end do
!                        end do
!                     end do
                     NICA_ICB_BT = NBat_CA_CB(ICA_ICB_SM)

                     !Distributing creation elements in batches
                     call DST_BLOCKS_OVER_BATCHES(.true.,NICA_ICB_BT,
     &                     ICA_ICB_SM,NICA,NICB,
     &                     MaxLB,Min_Size,
     &                     NIA,NIB,ISSM,ICA_IA_SM,ICB_IB_SM,                
     &                     INum_Sym_C,ISym_CA,ISym_CB,ICA_SM_STR_S,
     &                     ICB_SM_STR_S,ICA_SM_STR_E,ICB_SM_STR_E,
     &                     NSubBlk_C,NStrings_C,
     &                     L_A_Block,L_B_Block,L_Sym_Block
#if defined (VAR_MPI2)
     &                     , IOFF_BLK_S,IACT_S
#endif
     &                     )

                     !Statistics on number of strings
                     Do I=1,NICA_ICB_BT
                     Num_C_str_stat = Num_C_Str_stat + NStrings_C(I)
                     End do
                     Ave_Num_C_str =
     &                dble(Num_C_str_stat)/dble(NICA_ICB_BT)
#if defined (VAR_MPI2)
                     Time2 = interface_mpi_wtime()
#else
                     call CPU_time(Time2)
#endif
                     Batch_time = Batch_time + Time2 - Time1

            if(.not.Batch_not_zero) cycle KB_SM
            if(IBatch_not_zero==0) cycle KB_SM

            LEN_KA_BAT = MAXLB
            LEN_KB_BAT = MAXLB

            !Batching resolution K up and K down strings
            if(LKA_SM < MAXLB) then
               LEN_KA_BAT = LKA_SM
               LEN_KB_BAT = MIN(LKB_SM,MAXLB*MAXLB/LKA_SM)
            end if

            if(LKB_SM < MAXLB) then
               LEN_KB_BAT = LKB_SM
               LEN_KA_BAT = MIN(LKA_SM,MAXLB*MAXLB/LKB_SM)
            end if

            NKA_BT = LKA_SM/LEN_KA_BAT
            if(NKA_BT*LEN_KA_BAT < LKA_SM) NKA_BT = NKA_BT + 1
            NKB_BT = LKB_SM/LEN_KB_BAT
            if(NKB_BT*LEN_KB_BAT < LKB_SM) NKB_BT = NKB_BT + 1

#if defined (VAR_MPI2)
            kabt_start = interface_mpi_wtime()
#endif
            do IKA_BT = 1, NKA_BT !K up batches
!            write(LUWRT,*) 'Now batch loops'
               IKA_B  = (IKA_BT-1)*LEN_KA_BAT + 1
               IKA_E  = MIN(LKA_SM,IKA_B + LEN_KA_BAT - 1)

               NKA_B  = IKA_E - IKA_B + 1
!               write(LUWRT,*) 'IKA_B, IKA_E, NKA_B, LKA_SM, KASM'
!               write(LUWRT,*) IKA_B, IKA_E, NKA_B, LKA_SM, KASM
               NKA_B0 = NKA_B

#if defined (VAR_MPI2)
            kbbt_start = interface_mpi_wtime()
#endif
               do IKB_BT = 1, NKB_BT !K down
! Finding beginning/end and dimension of K up/down batches

                  IKB_B  = (IKB_BT-1)*LEN_KB_BAT + 1
                  IKB_E  = MIN(LKB_SM,IKB_B +  LEN_KB_BAT - 1)
                  NKB_B  = IKB_E - IKB_B + 1
!               write(LUWRT,*) 'IKB_B, IKB_E, NKB_B, LKB_SM, KBSM'
!               write(LUWRT,*) IKB_B, IKB_E, NKB_B, LKB_SM, KBSM
                  NKB_B0 = NKB_B
! Loop over creation up/down symmetry
!                  write(LUWRT,*) 'Creation loop'
#if defined (VAR_MPI2)
            ca_cb_sm_start = interface_mpi_wtime()
#endif

!                    Annihilation batches

                     do IAA_IAB_BT = 1, NIAA_IAB_BT 
!                     write(LUWRT,*) 'Annihilation batch ',IAA_IAB_BT

#if defined (VAR_MPI2)
                     Time1 = interface_mpi_wtime()
#else
                     call CPU_time(Time1)
#endif               
                     !Removing redundant elements in batch
                     call Reduce_Batch(.false.,MAXLB,
     &                     IAAGP,LIAA_SM2,IAA_STR,
     &                     IABGP,LIAB_SM2,IAB_STR,
     &                     KJAD,XKJAD,KASM,IKA_B,IKA_E,
     &                     I3,XI3S,IB_AA,NJKAINTM,NAA_OP,
     &                     KJBD,XKJBD,KBSM,IKB_B,IKB_E,
     &                     I4,XI4S,IB_AB,NJKBINTM,NAB_OP,
     &                     INum_Sym_A(IAA_IAB_BT),ISym_AA(:,IAA_IAB_BT),
     &                     ISym_AB(:,IAA_IAB_BT),
     &                     IAA_SM_STR_S(:,:,IAA_IAB_BT),
     &                     IAB_SM_STR_S(:,:,IAA_IAB_BT),
     &                     IAA_SM_STR_E(:,:,IAA_IAB_BT),
     &                     IAB_SM_STR_E(:,:,IAA_IAB_BT),
     &                     NSubBlk_A(:,IAA_IAB_BT),
     &                     INum_Sym_A_red,
     &                     ISym_AA_red,       
     &                     ISym_AB_red,
     &                     IAA_SM_STR_S_red,IAB_SM_STR_S_red,       
     &                     IAA_SM_STR_E_red,IAB_SM_STR_E_red,       
     &                     N_SubBlk_A_red,N_Strings_A_red,
     &                     IZeroKJABMap)

#if defined (VAR_MPI2)
                     Time2 = interface_mpi_wtime()
#else
                     call CPU_time(Time2)
#endif
                     Batch_time = Batch_time + Time2 - Time1
                     if(IZeroKJABMap/=0) cycle !Annihilation batch

!                     if(IZeroKJABMap==0) then
!                     write(LUWRT,*) 'Diff. in no. strings',
!     &               NStrings_A(IAA_IAB_BT)-N_Strings_A_red
!                     write(LUWRT,*) 'IZeroKJABMap ', IZeroKJABMap
!                     else
!                        cycle !Annihilation batches
!                     end if
!                     write(LUWRT,*) 'Past Annihilation Reduce_Batch'

                        ICJ_OFF = 0 !Column Offset in CJRES_BAT
                        IKJA_OFF = 0 !Offset in KJAD
                        IKJB_OFF = 0 !Offset in KJBD
!                        if(INum_Sym_A(IAA_IAB_BT)>1) then
!                           write(LUWRT,*) 'Annihilation batch',
!     &                     IAA_IAB_BT
!                           write(LUWRT,*) 'More than one symmetry in C'
!                           write(LUWRT,*) 'Number of symmetries',
!     &                        INum_Sym_A(IAA_IAB_BT)
!                        end if

#if defined (VAR_MPI2)
                     Time1 = interface_mpi_wtime()
#else
                     call CPU_time(Time1)
#endif
                        do JSym_A = 1,INum_Sym_A_red
!                        LIAA_SM = 
!     &                  NIAA(INVELM(ISym_AA_red(JSym_A)))
!                        LIAB_SM = 
!     &                  NIAB(INVELM(ISym_AB_red(JSym_A)))
                           IAA_SM = ISym_AA_red(JSym_A)

                           IAB_SM = ISym_AB_red(JSym_A)
                           JASM = IDBGMULT(IAA_JA_SM,INVELM(IAA_SM))
                           JBSM = IDBGMULT(ICSM,INVELM(JASM))
                           ICBOFF = IB_C(JASM) !Offset in C vector
!                  if(JBSM/=IDBGMULT(IAB_JB_SM,INVELM(IAB_SM))) then
!!                     write(LUWRT,*) 'Rejected JASM = ',JASM
!                     cycle
!!                  else
!!                     write(LUWRT,*) 'NOT rejected JASM = ',JASM
!!                     write(LUWRT,*) 'NOT rejected JBSM = ',JBSM
!                  end if
                           
                      do ISubBlk_A = 1,N_SubBlk_A_red(JSym_A)

                           IAA_B = IAA_SM_STR_S_red(ISubBlk_A,JSym_A)
                           IAA_E = IAA_SM_STR_E_red(ISubBlk_A,JSym_A)
                           NAA_B = IAA_E - IAA_B + 1

                           IAB_B = IAB_SM_STR_S_red(ISubBlk_A,JSym_A)
                           IAB_E = IAB_SM_STR_E_red(ISubBlk_A,JSym_A)
                           NAB_B = IAB_E - IAB_B + 1


!                  print *,'JASM, JBSM ==>',JASM,JBSM,NJA(JASM)*NJB(JBSM)
!           print '(a,6i3)', 
!     &     ' calc sigma ==>  JASM, JBSM, KASM, KBSM', 
!     &                       JASM, JBSM, KASM, KBSM
!           print '(a,6i3)',
!     &     ' calc sigma ==>  IAA_SM, IAB_SM',
!     &      IAA_SM, IAB_SM

!                              write(6,*) 'Making CJRES'
                              call
     &                        C_TO_CKK(CB(ICBOFF),
     &                        CJRES_BAT(NKA_B*NKB_B*(ICJ_OFF)+1),1,
     &                          NJA(JASM),NJB(JBSM),
     &                          NKA_B,NKB_B,NAA_B,NAB_B,
     &                  KJAD(IKJA_OFF+1),XKJAD,KJBD(IKJB_OFF+1),XKJBD)
                           
!     &                           NKA_B*NKB_B,NAA_B*NAB_B)
                                  ICJ_OFF = ICJ_OFF +
     &                                     NAA_B*NAB_B
                                  IKJA_OFF = IKJA_OFF +
     &                                    NKA_B*NAA_B                                  
                                  IKJB_OFF = IKJB_OFF +
     &                                    NKB_B*NAB_B                                  
!                                  write(LUWRT,*) 'After C_TO_CKK'
                              
                           End do !ISubBlk_A
                        End do !JSym_A

#ifdef GNSIDE_debug
                        write(LUWRT,*) 'C vector is'
                        call 
     &      wrtmat(CJRES_BAT,NKA_B*NKB_B,ICJ_OFF,NKA_B*NKB_B,MAXLB**2)
#endif
                        
!                        write(LUWRT,*) 'C vector found'
                        CNORM = DNRM2(NKA_B*NKB_B*ICJ_OFF,CJRES_BAT,1)

#if defined (VAR_MPI2)
                     Time2 = interface_mpi_wtime()
#else
                     call CPU_time(Time2)
#endif

                        Cvec_time = Cvec_time + Time2 - Time1
                        if(CNORM==0.0D0) cycle !Annihilation batches
!                        write(LUWRT,*) 'Number of elements in C array:
!     &                  ',ICJ_OFF
!Creation batches
                     LOOP_CR_BT: do ICA_ICB_BT = 1, NICA_ICB_BT
!                     write(LUWRT,*) 'Creation batch ',ICA_ICB_BT
!                           write(LUWRT,*) 'Before creation reduction'

#if defined (VAR_MPI2)
                     Time1 = interface_mpi_wtime()
#else
                     call CPU_time(Time1)
#endif
                     !Removing redundant creation elements from batch
                     call Reduce_Batch(.true.,MAXLB,
     &                     ICAGP,LICA_SM2,ICA_STR,
     &                     ICBGP,LICB_SM2,ICB_STR,
     &                     KIAD,XKIAD,KASM,IKA_B,IKA_E,
     &                     I1,XI1S,IB_CA,NIKAINTM,NCA_OP,
     &                     KIBD,XKIBD,KBSM,IKB_B,IKB_E,
     &                     I2,XI2S,IB_CB,NIKBINTM,NCB_OP,
     &                     INum_Sym_C(ICA_ICB_BT),ISym_CA(:,ICA_ICB_BT),
     &                     ISym_CB(:,ICA_ICB_BT),
     &                     ICA_SM_STR_S(:,:,ICA_ICB_BT),
     &                     ICB_SM_STR_S(:,:,ICA_ICB_BT),
     &                     ICA_SM_STR_E(:,:,ICA_ICB_BT),
     &                     ICB_SM_STR_E(:,:,ICA_ICB_BT),
     &                     NSubBlk_C(:,ICA_ICB_BT),
     &                     INum_Sym_C_red,
     &                     ISym_CA_red,       
     &                     ISym_CB_red,
     &                     ICA_SM_STR_S_red,ICB_SM_STR_S_red,       
     &                     ICA_SM_STR_E_red,ICB_SM_STR_E_red,       
     &                     N_SubBlk_C_red,N_Strings_C_red,
     &                     IZeroKIABMap)


#if defined (VAR_MPI2)
                     Time2 = interface_mpi_wtime()
#else
                     call CPU_time(Time2)
#endif
                     Batch_time = Batch_time + Time2 - Time1
                      if(IZeroKIABMap/=0) cycle !Creation batch

!                     if(IZeroKIABMap==0) then
!                     write(LUWRT,*) 'Diff. in no. strings',
!     &               NStrings_C(ICA_ICB_BT)-N_Strings_C_red
!                     write(LUWRT,*) 'IZeroKIABMap ', IZeroKIABMap
!                     else
!                        cycle !Creation batches
!                     end if
!                     write(LUWRT,*) 'Past Creation Reduce_Batch'

                     !Now for the T matrix
!                     write(LUWRT,*) 'Inside creation batches'
                     if(ISD==2) then !Fetching sigma vector
                       ISI_OFFC = 0
                       IKIA_Off = 0
                       IKIB_Off = 0

#if defined (VAR_MPI2)
                     Time1 = interface_mpi_wtime()
#else
                     call CPU_time(Time1)
#endif

                     do Jsym_C = 1,INum_Sym_C_red
                        
                        ICA_SM = ISym_CA_red(JSym_C)
                        ICB_SM = ISym_CB_red(JSym_C)
                        IASM = IDBGMULT(ICA_SM,ICA_IA_SM_INVELM)
                        IBSM = IDBGMULT(ISSM,INVELM(IASM))
!               write(LUWRT,*) 'Symmetry IASM = ',IASM
!               write(LUWRT,*) 'With elements NIA = ',NIA(IASM)
!               write(LUWRT,*) 'Symmetry IBSM = ',IBSM
!               write(LUWRT,*) 'With elements NIB = ',NIB(IBSM)
!                              write(LUWRT,*) 'Annihilation batch',
!     &                        IAA_IAB_BT
!                              write(LUWRT,*) 'Creation batch',
!     &                        ICA_ICB_BT
#ifdef GNSIDE_debug
!Info about what part of the sigma vector elements are now added to
                        Do JSym_A = 1,INum_Sym_A_red
                           IAA_SM = ISym_AA_red(JSym_A)
                           IAB_SM = ISym_AB_red(JSym_A)
                           JASM = IDBGMULT(IAA_JA_SM,INVELM(IAA_SM))
                           JBSM = IDBGMULT(ICSM,INVELM(JASM))

!                  print *,'JASM, JBSM ==>',JASM,JBSM,NJA(JASM)*NJB(JBSM)
!           print '(a,6i3)', 
!     &     ' calc sigma ==> IASM, IBSM  JASM, JBSM, KASM, KBSM', 
!     &                      IASM, IBSM, JASM, JBSM, KASM, KBSM
!           print '(a,6i3)',
!     &     ' calc sigma ==> ICA_SM, ICB_SM, IAA_SM, IAB_SM',
!     &      ICA_SM, ICB_SM, IAA_SM, IAB_SM

                        end do
#endif
               
!               write(LUWRT,*) 'NKA_B,NKB_B',NKA_B,NKB_B

                        ISBOFF = IB_S(IASM) !Offset in C vector
!                              write(LUWRT,*) 'ISBOFF is ',ISBOFF
                     do ISubBlk_C = 1,N_SubBlk_C_red(JSym_C)

                        ICA_B = ICA_SM_STR_S_red(ISubBlk_C,JSym_C)
                        ICA_E = ICA_SM_STR_E_red(ISubBlk_C,JSym_C)
                        NCA_B = ICA_E - ICA_B + 1

                        ICB_B = ICB_SM_STR_S_red(ISubBlk_C,JSym_C)
                        ICB_E = ICB_SM_STR_E_red(ISubBlk_C,JSym_C)
!                           write(LUWRT,*) 'ICB_B, ICB_E set'
                        NCB_B = ICB_E - ICB_B + 1
#ifdef GNSIDE_debug
                     write(LUWRT,*) 'IKA_B, IKA_E',IKA_B,IKA_E
                     write(LUWRT,*) 'IKB_B, IKB_E',IKB_B,IKB_E
                     write(LUWRT,*) 'ICA_B, ICA_E ',ICA_B,ICA_E
                     write(LUWRT,*) 'ICB_B, ICB_E ',ICB_B,ICB_E
                     write(LUWRT,*) 'IAA_B, IAA_E ',IAA_B,IAA_E
                     write(LUWRT,*) 'IAB_B, IAB_E ',IAB_B,IAB_E
#endif


!                        write(LUWRT,*) 'Before sigma addition'
#ifdef GNSIDE_debug
                          write(LUWRT,*) 
     &                  'Extracting sigmavector with values:'
                          call 
     &     wrtmat(SB(ISBOFF),NIA(IASM),NIB(IBSM),NIA(IASM),NIB(IBSM))
#endif
C                                   


#ifdef GNSIDE_debug
                     write(LUWRT,*) 'NKA_B,NKB_B,NCA_B,NCB_B'
                     write(LUWRT,*) NKA_B,NKB_B,NCA_B,NCB_B

                     write(LUWRT,*) 'ISI_OFFC'
                     write(LUWRT,*) ISI_OFFC
#endif
!                           write(LUWRT,*) 'Sigma vector'
!                           call
!     &   wrtmat(SB(ISBOFF),NIA(IASM),NIB(IBSM),NIA(IASM),NIB(IASM))

                         !Copy Sigma vector part to SIRES_BAT

                         call C_TO_CKK(SB(ISBOFF),
!     &          SIRES,
     &          SIRES_BAT(NKA_B*NKB_B*(ISI_OFFC)+1),
     &                    1,NIA(IASM),NIB(IBSM),
     &                    NKA_B,NKB_B,NCA_B,
     &                    NCB_B,KIAD(IKIA_Off+1),XKIAD,KIBD(IKIB_Off+1),
     &                    XKIBD)
                                  ISI_OFFC = ISI_OFFC +
     &                                     NCA_B*NCB_B
                                  IKIA_OFF = IKIA_OFF +
     &                                    NKA_B*NCA_B                                  
                                  IKIB_OFF = IKIB_OFF +
     &                                    NKB_B*NCB_B                                  

#ifdef GNSIDE_debug
                          write(LUWRT,*) 'After sigma extraction'

                          write(LUWRT,*) 'Total SIRES_BAT after'
                          write(LUWRT,*) 'fetching from SB'
                          write(LUWRT,*) 'ITOFF, ISI_OFFC, ISBOFF'
                          write(LUWRT,*) ITOFF, ISI_OFFC, ISBOFF
                          call 
     &     wrtmat(SIRES_BAT,NKA_B*NKB_B,ISI_OFFC,NKA_B*NKB_B,MAXLB**2)
#endif
                        end do !Creation sub blocks
                     end do !Creation symmetry

#if defined (VAR_MPI2)
                     Time2 = interface_mpi_wtime()
#else
                     call CPU_time(Time2)
#endif
                        Sigma_time = Sigma_time + Time2 - Time1
!                        write(LUWRT,*) 'ISD=2'

!                        call
!     &   wrtmat(SIRES_BAT,NKA_B*NKB_B,N_Strings_C_red,
!     &         NKA_B*NKB_B,N_Strings_C_red)

                     end if !ISD==2 density run

                     IOFFC = 0

                     if(ISD==1) then !Fetch T elements

#if defined (VAR_MPI2)
                     Time1 = interface_mpi_wtime()
#else
                     call CPU_time(Time1)
#endif
                     Do JSym_A = 1,INum_Sym_A_red
                       IAA_SM = ISym_AA_red(JSym_A)
                       IAB_SM = ISym_AB_red(JSym_A)
                       IAA_SM_ADJ = INVELM(IAA_SM)
!                           IAB_SM_ADJ = INVELM(IAB_SM)
!                           JASM = IDBGMULT(IAA_JA_SM,INVELM(IAA_SM))
!                           JBSM = IDBGMULT(ICSM,INVELM(JASM))
!                  if(JBSM/=IDBGMULT(IAB_JB_SM,INVELM(IAB_SM))) cycle

!                              if(NJA(JASM)*NJB(JBSM)==0) cycle

                        LIAA_SM = 
     &                  NIAA(IAA_SM_ADJ)
                        LIAB_SM = 
     &                  NIAB(invelm(IAB_SM))

         SubBlk_A_Lo:  Do ISubBlk_A = 1,N_SubBlk_A_red(JSym_A)
!                     Num_Sym = INum_sym_C(ICA_ICB_BT)
                        IOFFR = 0 !Row offset in T_BAT
                  IAA_B = IAA_SM_STR_S_red(ISubBlk_A,JSym_A)
                  IAA_E = IAA_SM_STR_E_red(ISubBlk_A,JSym_A)
!                     write(LUWRT,*) 'IAA_B = ',IAA_B
!                     write(LUWRT,*) 'IAA_E = ',IAA_E
                  NAA_B = IAA_E - IAA_B + 1

                  IAB_B = IAB_SM_STR_S_red(ISubBlk_A,JSym_A)
                  IAB_E = IAB_SM_STR_E_red(ISubBlk_A,JSym_A)
                  NAB_B = IAB_E - IAB_B + 1

                  NCSUB = NAA_B * NAB_B !Number of columns in TBSUB
                  !Offsets for row and column in T
                  !matrix
                  ISI_OFFC = 0 !Offset in SIRES_BAT
!                 do Jsym_C = 1,INum_Sym_C(ICA_ICB_BT)
!                    ICA_SM = ISym_CA(JSym_C,ICA_ICB_BT)
!                    ICB_SM = ISym_CB(JSym_C,ICA_ICB_BT)
                  do Jsym_C = 1,INum_Sym_C_red
                    ICA_SM = ISym_CA_red(JSym_C)
                    ICB_SM = ISym_CB_red(JSym_C)
!                              IASM =
!     &                     IDBGMULT(ICA_SM,INVELM(ICA_IA_SM))
!                              IASM =
!     &                     IDBGMULT(ICA_SM,KASM)
!                              IBSM =
!     &                     IDBGMULT(ISSM,INVELM(IASM))

!                  if(IBSM/=IDBGMULT(ICB_SM,INVELM(ICB_IB_SM))) then
!                     write(LUWRT,*) 'Rejected IASM = ',IASM
!                     cycle
!                  else
!                     write(LUWRT,*) 'NOT rejected IASM = ',IASM
!                     write(LUWRT,*) 'NOT rejected IBSM = ',IBSM
!                  end if
!                        if(NIA(IASM)*NIB(IBSM)==0) cycle

                     LICA_SM = 
     &               NICA(ICA_SM)
                     LICB_SM = 
     &               NICB(ICB_SM)

             SubBlk_C_Lo: do ISubBlk_C = 1,N_SubBlk_C_red(JSym_C)

                     ICA_B = ICA_SM_STR_S_red(ISubBlk_C,JSym_C)
                     ICA_E = ICA_SM_STR_E_red(ISubBlk_C,JSym_C)
!                     write(LUWRT,*) 'ICA_B = ',ICA_B
!                     write(LUWRT,*) 'ICA_E = ',ICA_E
                     NCA_B = ICA_E - ICA_B + 1
                     ICB_B = ICB_SM_STR_S_red(ISubBlk_C,JSym_C)
                     ICB_E = ICB_SM_STR_E_red(ISubBlk_C,JSym_C)

!                        write(LUWRT,*) 'ICB_B, ICB_E set'
                     NCB_B = ICB_E - ICB_B + 1
!                     write(LUWRT,*) 'NCB_B ',NCB_B
!                     write(LUWRT,*) IKA_E - IKA_B + 1

                     ITOFF =
     &               IB_T(ICA_SM,ICB_SM,IAA_SM_ADJ)
!                     write(LUWRT,*)
!     &               'output of IB_T for current block', ITOFF
                     IDIAG = 0

                     IF(ITOFF.lt.0) THEN
                        ITOFF = -ITOFF
                        ITRNSP = 1
                     ELSE
                        ITRNSP = 0
                     END IF

!                     write(LUWRT,*) 'ITRNSP = ',ITRNSP
                        
                     if ((IRIS.eq.1.and.IRIC.eq.2).or.
     &                    (IRIS.eq.2.and.IRIC.eq.1)) then
                         if( SPLIT_IJKL) then
                          ITOFF = ITOFF + LEN_T_BUFF
                         end if
                     end if 
#ifdef GNSIDE_debug
                     write(LUWRT,*) 'ITOFF, LICA_SM, NCA_B, ICA_B'
                     write(LUWRT,*) ITOFF, LICA_SM, NCA_B, ICA_B
                     write(LUWRT,*) 'LICB_SM, NCB_B, ICB_B' 
                     write(LUWRT,*) LICB_SM, NCB_B, ICB_B
                     write(LUWRT,*) 'LIAA_SM, NAA_B, IAA_B'
                     write(LUWRT,*) LIAA_SM, NAA_B, IAA_B
                     write(LUWRT,*) 'LIAB_SM, NAB_B, IAB_B, NTEST'
                     write(LUWRT,*) LIAB_SM, NAB_B, IAB_B, NTEST
                     write(LUWRT,*) 'Extracting T matrix'
#endif
                     call TCC_SUBBLK(TB(ITOFF),
     &                             T_BUFF(ITOFF), T_SCR_CC(ITOFF),
     &                             TBSUB,1,LICA_SM,
     &                             NCA_B,ICA_B,
     &                             LICB_SM,NCB_B,ICB_B,
     &                             LIAA_SM,NAA_B,IAA_B,
     &                             LIAB_SM,NAB_B,IAB_B,
     &                             ITRNSP,IDIAG,NTEST)
                     !Number of rows in TBSUB
                     NRSUB = NCA_B * NCB_B


#ifdef GNSIDE_debug
                           write(LUWRT,*) 'TBSUB extracted, values:'
                           call wrtmat(TBSUB,NRSUB,NCSUB,NRSUB,NCSUB)
#endif
                           !Copy T block to T_BAT
                           call EXTR_OR_CP_MAT(T_BAT,
     &                                   MAXLB**2,
     &                                   MAXLB**2,0,TBSUB,
     &                                   NRSUB,NCSUB,0,
     &                                   IOFFR+1,IOFFC+1,2)
!                           write(LUWRT,*) 'IOFFR'
!                           write(LUWRT,*) 'IOFFC'
!                           write(LUWRT,*) IOFFR, IOFFC
!                           write(LUWRT,*) 'IOFFC*MAXLB**2+IOFFR*NCSUB'
!                           write(LUWRT,*) IOFFC*MAXLB**2+IOFFR*NCSUB
!                           write(LUWRT,*) 'NRSUB,NCSUB',NRSUB,NCSUB
#ifdef GNSIDE_debug
                           write(LUWRT,*) 'T_BAT:'
                           call
     &                     wrtmat(T_BAT(IOFFC*MAXLB**2
     &                     +IOFFR*NCSUB+1),NRSUB,NCSUB,
!     &                     NRSUB,NCSUB)
     &                     MAXLB**2,MAXLB**2)
#endif GNSIDE_debug
!                           write(LUWRT,*) 'IOFFR, NCA_B, NCB_B',
!     &                     IOFFR, NCA_B, NCB_B

                           IOFFR = IOFFR + NCA_B*NCB_B
!                           write(LUWRT,*) 'Now IOFFR = ',IOFFR

                       end do SubBlk_C_Lo
                       end do   
                           IOFFC = IOFFC + NAA_B*NAB_B
!                           write(LUWRT,*) 'IOFFC',IOFFC
!                           LAAB = IOFFC

                       end do SubBlk_A_Lo
                       end do

#if defined (VAR_MPI2)
                     Time2 = interface_mpi_wtime()
#else
                     call CPU_time(Time2)
#endif
                       T_time = T_time + Time2 - Time1

!                       else !density run, initialise T_BAT
!
!                          call
!     &                  dzero(T_BAT,N_Strings_C_red*N_Strings_A_red)
                       end if !ISD == 1


                       LCAB = N_Strings_C_red
                       LAAB = N_Strings_A_red
                       LKAB = NKA_B*NKB_B 
#ifdef GNSIDE_debug
                       write(LUWRT,*) 'IOFFR, IOFFC',IOFFR,IOFFC
                       write (LUWRT,*) 'MAXLB**2 = ',MAXLB**2
                       write(LUWRT,*) 'LCAB, LAAB',LCAB,LAAB
                       write(LUWRT,*) '      T matrix of batch:'

                       call
     &                 wrtmat(T_BAT,LCAB,LAAB,MAXLB**2,MAXLB**2)
#endif
!                       write(LUWRT,*) 'T_BAT found'

                       FACTORC = 0.0D0
                       FACTORAB = 1.0D0*SIGNXXX

                       call CPU_Time(Time1)
                       call CPU_TIME(T_INI)
#if defined (VAR_MPI2)
                     Time1 = interface_mpi_wtime()
    
#else
                     call CPU_time(Time1)
#endif
!Insert new matrix blocks into complete sigma matrix                          
#if defined (VAR_MPI2)
                       xxxsitime = interface_MPI_WTIME()
#endif


!                       write(LUWRT,*) 
!     &                  'Just before matrix multiplication'

                       if(ISD.EQ.1) THEN
                       !ISD == 1: Sigma vector:
                       !SIRES(Ka,Kb,Ica,Icb) =
                       !CJRES(Ka,Kb,Iaa,Iab)*T(Ica,Icb,Iaa,Iab)

                         !input
                         LDB = MAXLB**2
                         LDA = max(1,LKAB)
                         !output
                         LDC = max(1,LKAB)

#ifdef GNSIDE_debug
                         write(LUWRT,*) 'LKAB, LCAB, LAAB'
                         write(LUWRT,*) LKAB, LCAB, LAAB
                         write(LUWRT,*) 'FACTORAB, LDA, LDB'
                         write(LUWRT,*) FACTORAB, LDA, LDB
                         write(LUWRT,*) 'FACTORC, LDC'
                         write(LUWRT,*) FACTORC, LDC
                         write(LUWRT,*) 'C array'
                         call
     &    wrtmat(CJRES_BAT,LKAB,LAAB,LKAB,MAXLB**2)
                           write(LUWRT,*) 'T matrix'
                           call
     &    wrtmat(T_BAT,LCAB,LAAB,MAXLB**2,MAXLB**2)
#endif

                         !Matrix multiply CJRES_BAT and T_BAT
                         call DGEMM('N','T',LKAB,LCAB,LAAB,
     &                   FACTORAB,CJRES_BAT,LDA,T_BAT,
     &                   LDB,FACTORC,SIRES_BAT,LDC)

#ifdef GNSIDE_debug
                         write(LUWRT,*) 'Total S matrix is'
                         call
     &   wrtmat(SIRES_BAT,LKAB,LCAB,LKAB,MAXLB**2)
#endif

                       else !Density run
                       !ISD == 2: Density:
                       !T(Ica,Icb,Iaa,Iab)   =
                       !SIRES(Ka,Kb,Ica,Icb)*CJRES(Ka,Kb,Ica,Icb)
!                         write(LUWRT,*) 'Matrix multiplying'
                         !input
                      
                         LDA = MAX(1,LKAB)
                         LDB = MAX(1,LKAB)
                         !output
                         LDC = N_Strings_C_red
!                         LDC = MAXLB**2

                         !Matrix multiply SIRES_BAT and CJRES_BAT
                         call DGEMM('T','N',LCAB,LAAB,LKAB,
     &                              FACTORAB,SIRES_BAT,LDA,CJRES_BAT,
     &                              LDB,FACTORC,T_BAT,LDC)
!                          write(LUWRT,*) 'Den. T'
!                          call
!     & wrtmat(T_BAT,LCAB,LAAB,LDC,LDC)
!                          write(LUWRT,*) 'T_BAT calculated'
                       end if

!                       write(LUWRT,*) 'After matrix multiplication'
                       call CPU_TIME(T_END)
                       TMULT = TMULT + T_END - T_INI

#if defined (VAR_MPI2)
                     Time2 = interface_mpi_wtime()
    
#else
                     call CPU_time(Time2)
#endif
                       CalcMatTime = CalcMatTime + Time2 - Time1

!                       write(LUWRT,*) 'Time spent on matmult so far is'
!                       write(LUWRT,*) 'time = ',TMULT

#if defined (VAR_MPI2)
                       xcomputesi = xcomputesi - xxxsitime
     &                                       + interface_MPI_WTIME()
#endif

                     IF(ISD.EQ.1) THEN
                       ISI_OFFC = 0
                       IKIA_Off = 0
                       IKIB_Off = 0


#if defined (VAR_MPI2)
                     Time1 = interface_mpi_wtime()
    
#else
                     call CPU_time(Time1)
#endif
                     do Jsym_C = 1,INum_Sym_C_red
                        
                        ICA_SM = ISym_CA_red(JSym_C)
                        ICB_SM = ISym_CB_red(JSym_C)
                        IASM = IDBGMULT(ICA_SM,ICA_IA_SM_INVELM)
                        IBSM = IDBGMULT(ISSM,INVELM(IASM))

!               write(LUWRT,*) 'Symmetry IASM = ',IASM
!               write(LUWRT,*) 'With elements NIA = ',NIA(IASM)
!               write(LUWRT,*) 'Symmetry IBSM = ',IBSM
!               write(LUWRT,*) 'With elements NIB = ',NIB(IBSM)
!                              write(LUWRT,*) 'Annihilation batch',
!     &                        IAA_IAB_BT
!                              write(LUWRT,*) 'Creation batch',
!     &                        ICA_ICB_BT
#ifdef GNSIDE_debug
!Info about what part of the sigma vector elements are now added to
                        Do JSym_A = 1,INum_Sym_A_red
                           IAA_SM = ISym_AA_red(JSym_A)
                           IAB_SM = ISym_AB_red(JSym_A)
                           JASM = IDBGMULT(IAA_JA_SM,INVELM(IAA_SM))
                           JBSM = IDBGMULT(ICSM,INVELM(JASM))

                  print *,'JASM, JBSM ==>',JASM,JBSM,NJA(JASM)*NJB(JBSM)
           print '(a,6i3)', 
     &     ' calc sigma ==> IASM, IBSM  JASM, JBSM, KASM, KBSM', 
     &                      IASM, IBSM, JASM, JBSM, KASM, KBSM
           print '(a,6i3)',
     &     ' calc sigma ==> ICA_SM, ICB_SM, IAA_SM, IAB_SM',
     &      ICA_SM, ICB_SM, IAA_SM, IAB_SM

                        end do
#endif
               
!               write(LUWRT,*) 'NKA_B,NKB_B',NKA_B,NKB_B

                        ISBOFF = IB_S(IASM) !Offset in C vector
!                       write(LUWRT,*) 'ISBOFF is ',ISBOFF

                     do ISubBlk_C = 1,N_SubBlk_C_red(JSym_C)
!                         write(LUWRT,*) 'Jsym_C,ISubBlk_C'
!                         write(LUWRT,*) JSym_C,ISubBlk_C 
                       ICA_B = ICA_SM_STR_S_red(ISubBlk_C,JSym_C)
                       ICA_E = ICA_SM_STR_E_red(ISubBlk_C,JSym_C)
                       NCA_B = ICA_E - ICA_B + 1
                       ICB_B = ICB_SM_STR_S_red(ISubBlk_C,JSym_C)
                       ICB_E = ICB_SM_STR_E_red(ISubBlk_C,JSym_C)
!                             write(LUWRT,*) 'ICB_B, ICB_E set'
                       NCB_B = ICB_E - ICB_B + 1
#ifdef GNSIDE_debug
                       write(LUWRT,*) 'IKA_B, IKA_E',IKA_B,IKA_E
                       write(LUWRT,*) 'IKB_B, IKB_E',IKB_B,IKB_E
                       write(LUWRT,*) 'ICA_B, ICA_E ',ICA_B,ICA_E
                       write(LUWRT,*) 'ICB_B, ICB_E ',ICB_B,ICB_E
                       write(LUWRT,*) 'IAA_B, IAA_E ',IAA_B,IAA_E
                       write(LUWRT,*) 'IAB_B, IAB_E ',IAB_B,IAB_E
#endif

!                        write(LUWRT,*) 'Before sigma addition'
#ifdef GNSIDE_debug
                          write(LUWRT,*) 'Total sigma vector before'
                         write(LUWRT,*) 'addition:'
                          call 
     &     wrtmat(SB(ISBOFF),NIA(IASM),NIB(IBSM),NIA(IASM),NIB(IBSM))
#endif

C                                   
!                           write(LUWRT,*) 
!     &                  'There are K mappings for SIRES!'

#ifdef GNSIDE_debug
                           write(LUWRT,*) 'NKA_B,NKB_B,NCA_B,NCB_B'
                           write(LUWRT,*) NKA_B,NKB_B,NCA_B,NCB_B

                           write(LUWRT,*) 'ISI_OFFC'
                           write(LUWRT,*) ISI_OFFC
#endif

                         call C_TO_CKK(SB(ISBOFF),
     &          SIRES_BAT(NKA_B*NKB_B*(ISI_OFFC)+1),
     &                    2,NIA(IASM),NIB(IBSM),
     &                    NKA_B,NKB_B,NCA_B,
     &                    NCB_B,KIAD(IKIA_Off+1),XKIAD,KIBD(IKIB_Off+1),
     &                    XKIBD)
                                  ISI_OFFC = ISI_OFFC +
     &                                     NCA_B*NCB_B
                                  IKIA_OFF = IKIA_OFF +
     &                                    NKA_B*NCA_B                                  
                                  IKIB_OFF = IKIB_OFF +
     &                                    NKB_B*NCB_B                                  

#ifdef GNSIDE_debug
                          write(LUWRT,*) 'After sigma addition'

                          write(LUWRT,*) 'Total sigma vector after'
                          write(LUWRT,*) 'addition'
                          write(LUWRT,*) 'ITOFF, ISI_OFFC, ISBOFF'
                          write(LUWRT,*) ITOFF, ISI_OFFC, ISBOFF
                          call 
     &     wrtmat(SB(ISBOFF),NIA(IASM),NIB(IBSM),NIA(IASM),NIB(IBSM))
#endif

                        end do !Creation sub blocks
                     end do !Creation symmetry

#if defined (VAR_MPI2)
                     Time2 = interface_mpi_wtime()
    
#else
                     call CPU_time(Time2)
#endif
                        Sigma_time = Sigma_time + Time2 - Time1

                  else !Spreading out T to density block

#if defined (VAR_MPI2)
                    Time1 = interface_mpi_wtime()
    
#else
                    call CPU_time(Time1)
#endif
                    IOFFC = 0

                    Do JSym_A = 1,INum_Sym_A_red
                       IAA_SM = ISym_AA_red(JSym_A)
                       IAB_SM = ISym_AB_red(JSym_A)
                       IAA_SM_ADJ = INVELM(IAA_SM)
                       IAB_SM_ADJ = INVELM(IAB_SM)
                       JASM = IDBGMULT(IAA_JA_SM,INVELM(IAA_SM))
                       JBSM = IDBGMULT(ICSM,INVELM(JASM))

                       LIAA_SM = 
     &                 NIAA(IAA_SM_ADJ)
                       LIAB_SM = 
     &                 NIAB(IAB_SM_ADJ)

                       Do ISubBlk_A = 1,N_SubBlk_A_red(JSym_A)

                        IOFFR = 0 
                        IAA_B = IAA_SM_STR_S_red(ISubBlk_A,JSym_A)
                        IAA_E = IAA_SM_STR_E_red(ISubBlk_A,JSym_A)
!                       write(LUWRT,*) 'IAA_B = ',IAA_B
!                       write(LUWRT,*) 'IAA_E = ',IAA_E
                        NAA_B = IAA_E - IAA_B + 1

                        IAB_B = IAB_SM_STR_S_red(ISubBlk_A,JSym_A)
                        IAB_E = IAB_SM_STR_E_red(ISubBlk_A,JSym_A)
                        NAB_B = IAB_E - IAB_B + 1

                        NCSUB = NAA_B * NAB_B !Columns in TBSUB for extraction

                     do Jsym_C = 1,INum_Sym_C_red
                        ICA_SM = ISym_CA_red(JSym_C)
                        ICB_SM = ISym_CB_red(JSym_C)
                           IASM =
     &                  IDBGMULT(ICA_SM,ICA_IA_SM_INVELM)
                           IBSM =
     &                  IDBGMULT(ISSM,INVELM(IASM))

                        LICA_SM = 
     &                  NICA(ICA_SM)
                        LICB_SM = 
     &                  NICB(ICB_SM)

                      do ISubBlk_C = 1,N_SubBlk_C_red(JSym_C)

                        ICA_B = ICA_SM_STR_S_red(ISubBlk_C,JSym_C)
                        ICA_E = ICA_SM_STR_E_red(ISubBlk_C,JSym_C)
!                     write(LUWRT,*) 'ICA_B = ',ICA_B
!                     write(LUWRT,*) 'ICA_E = ',ICA_E
                        NCA_B = ICA_E - ICA_B + 1
                        ICB_B = ICB_SM_STR_S_red(ISubBlk_C,JSym_C)
                        ICB_E = ICB_SM_STR_E_red(ISubBlk_C,JSym_C)

!                           write(LUWRT,*) 'ICB_B, ICB_E set'
                        NCB_B = ICB_E - ICB_B + 1
!                        write(LUWRT,*) 'NCB_B ',NCB_B
!                        write(LUWRT,*) IKA_E - IKA_B + 1

                        ITOFF =
     &                  IB_T(ICA_SM,ICB_SM,IAA_SM_ADJ)
!                        write(LUWRT,*)
!     &                  'output of IB_T for current block', ITOFF
                        IDIAG = 0

                        IF(ITOFF.lt.0) THEN
                           ITOFF = -ITOFF
                           ITRNSP = 1
                        ELSE
                           ITRNSP = 0
                        END IF

                     if(ITRNSP==0) then

!                        write(LUWRT,*) 'ITRNSP = ',ITRNSP
                           
                           if ((IRIS.eq.1.and.IRIC.eq.2).or.
     &                         (IRIS.eq.2.and.IRIC.eq.1)) then
                              if( SPLIT_IJKL) then
                               ITOFF = ITOFF + LEN_T_BUFF
                              end if
                           end if 

                           NRSUB = NCA_B * NCB_B
                           call EXTR_OR_CP_MAT(T_BAT,
     &                                   N_Strings_C_red,
     &                                   N_strings_A_red,0,TBSUB,
     &                                   NRSUB,NCSUB,0,
     &                                   IOFFR+1,IOFFC+1,1)
!                           call EXTR_OR_CP_MAT(T_BAT,
!     &                                   MAXLB**2,
!     &                                   MAXLB**2,0,TBSUB,
!     &                                   NRSUB,NCSUB,0,
!     &                                   IOFFR+1,IOFFC+1,1)

#ifdef GNSIDE_debug
                          write(LUWRT,*) 'ITOFF, LICA_SM, NCA_B, ICA_B'
                          write(LUWRT,*) ITOFF, LICA_SM, NCA_B, ICA_B
                          write(LUWRT,*) 'LICB_SM, NCB_B, ICB_B' 
                          write(LUWRT,*) LICB_SM, NCB_B, ICB_B
                          write(LUWRT,*) 'LIAA_SM, NAA_B, IAA_B'
                          write(LUWRT,*) LIAA_SM, NAA_B, IAA_B
                          write(LUWRT,*) 'LIAB_SM, NAB_B, IAB_B, NTEST'
                          write(LUWRT,*) LIAB_SM, NAB_B, IAB_B, NTEST
                          write(LUWRT,*) 'Extracting T matrix'
#endif
!           print '(a,6i3)', 
!     &     ' calc sigma ==> IASM, IBSM  JASM, JBSM, KASM, KBSM', 
!     &                      IASM, IBSM, JASM, JBSM, KASM, KBSM
!           print '(a,6i3)',
!     &     ' calc sigma ==> ICA_SM, ICB_SM, IAA_SM, IAB_SM',
!     &      ICA_SM, ICB_SM, IAA_SM, IAB_SM
!                           write(LUWRT,*)
!     &               'Den. TB pre-addition'
!                           call wrtmat
!     &         (TB(ITOFF),LICA_SM*LICB_SM,LIAA_SM*LIAB_SM,
!     &            LICA_SM*LICB_SM,LIAA_SM,LIAB_SM)
                         call TCC_SUBBLK(TB(ITOFF),
     &                                 T_BUFF(ITOFF), T_SCR_CC(ITOFF),
     &                                 TBSUB,2,LICA_SM,
     &                                 NCA_B,ICA_B,
     &                                 LICB_SM,NCB_B,ICB_B,
     &                                 LIAA_SM,NAA_B,IAA_B,
     &                                 LIAB_SM,NAB_B,IAB_B,
     &                                 ITRNSP,IDIAG,NTEST)
!                           write(LUWRT,*)
!     &               'Den. TB POST-addition'
!                           call wrtmat
!     &         (TB(ITOFF),LICA_SM*LICB_SM,LIAA_SM*LIAB_SM,
!     &            LICA_SM*LICB_SM,LIAA_SM,LIAB_SM)
                            !Calculate row/column offsets in T_BAT

#ifdef GNSIDE_debug
                           write(LUWRT,*) 'TBSUB extracted, values:'
                           call wrtmat(TBSUB,NRSUB,NCSUB,NRSUB,NCSUB)
#endif
!                           write(LUWRT,*) 'IOFFR'
!                           write(LUWRT,*) 'IOFFC'
!                           write(LUWRT,*) IOFFR, IOFFC
!                           write(LUWRT,*) 'IOFFC*MAXLB**2+IOFFR*NCSUB'
!                           write(LUWRT,*) IOFFC*MAXLB**2+IOFFR*NCSUB
!                           write(LUWRT,*) 'NRSUB,NCSUB',NRSUB,NCSUB
#ifdef GNSIDE_debug
                           write(LUWRT,*) 'T_BAT:'
                           call
     &                     wrtmat(T_BAT(IOFFC*MAXLB**2
     &                     +IOFFR*NCSUB+1),NRSUB,NCSUB,
!     &                     NRSUB,NCSUB)
     &                     MAXLB**2,MAXLB**2)
#endif GNSIDE_debug
!                           write(LUWRT,*) 'IOFFR, NCA_B, NCB_B',
!     &                     IOFFR, NCA_B, NCB_B


                     end if !ITRNSP == 0

                           IOFFR = IOFFR + NCA_B*NCB_B
!                           write(LUWRT,*) 'Now IOFFR = ',IOFFR

                       end do
                       end do   
                           IOFFC = IOFFC + NAA_B*NAB_B
!                           write(LUWRT,*) 'IOFFC',IOFFC

                       end do
                       end do

#if defined (VAR_MPI2)
                     Time2 = interface_mpi_wtime()
    
#else
                     call CPU_time(Time2)
#endif
                       T_time = T_time + Time2 - Time1

                  end if !Sigmavector or density run, adding to SB or TB
!                        print *,'ISBOFF, length',
!    &                            ISBOFF,NIA(IASM)*NIB(IBSM)
                  end do LOOP_CR_BT
                  end do !Annihilation batches IAA_IAB_BT

#if defined (VAR_MPI2)
            ca_cb_sm_end = interface_mpi_wtime()
            ca_cb_sm_tot = ca_cb_sm_tot + ca_cb_sm_end - ca_cb_sm_start
#endif
               end do !KB batches
#if defined (VAR_MPI2)
            kbbt_end = interface_mpi_wtime()
            kbbt_tot = kbbt_tot + kbbt_end - kbbt_start
#endif
            end do !KA batches
#if defined (VAR_MPI2)
            kabt_end = interface_mpi_wtime()
            kabt_tot = kabt_tot + kabt_end - kabt_start
#endif
            End do CA_CB_SM_BT
         end do KB_SM
      end do  
!#if defined (VAR_MPI2)
!      I_BLK_S_SCR = I_BLK_S_SCR + 1
!#endif 
      end if ! if Ka and Kb are nontrivial strings
!#undef GNSIDE_debug      


      END SUBROUTINE   

      SUBROUTINE EXTR_OR_CP_MAT(ABIG,LRBIG,LCBIG,ISYMBIG,
     &                          ASMA,LRSMA,LCSMA,ISYMSMA,
     &                          IOFFR,IOFFC,IEC)
*
*
* Copy or extract a smaller matrix, ASMA, from/to a larger matrix, ABIG
*
* IEC = 1 => Extract from big to small matrix
* IEC = 2 => Extract from small to big matrix
*
*. Dimension of small matrix: LRSMA, LCSMA
*. Dimension of large matrix: LRBIG, LCBIG
*
* ISYMBIG = 1 => Big matrix is symmetric and only lower half is included
* ISYMSMA = 1 => Small matrix is symmetric and only lower half is included
*
* IOFFR, IOFFC: First row/column, where elements of small matrix should be added to /extracted from large matrix
*
*. Jeppe Olsen, July 19, 2013
*
*      INCLUDE 'implicit.inc'
      IMPLICIT REAL*8(A-H,O-Z)
*. Input or output
      DIMENSION ASMA(*),ABIG(*)
*
      NTEST = 000
      IF(NTEST.GE.100) THEN
        WRITE(6,*) ' Info from EXTR_OR_CP_MAT'
        WRITE(6,*) ' ========================'
        WRITE(6,*) 
        WRITE(6,*) ' LRBIG, LCBIG = ', LRBIG, LCBIG
        WRITE(6,*) ' LRSAM, LCSMA = ', LRSMA, LCSMA 
        WRITE(6,*) ' IOFFR, IOFFC = ', IOFFR, IOFFC
        WRITE(6,*) ' ISYMBIG, ISYMSMA = ', ISYMBIG,ISYMSMA
        WRITE(6,*) ' IEC = ', IEC
      END IF
      IF(NTEST.GE.1000) THEN
        WRITE(6,*) ' Input small matrix '
        IF(ISYMSMA.EQ.0) THEN
          CALL WRTMAT(ASMA,LRSMA, LCSMA, LRSMA, LCSMA)
        ELSE
          CALL PRSYM(ASMA, LRSMA)
        END IF
        WRITE(6,*) ' Input Large matrix '
        IF(ISYMBIG.EQ.0) THEN
          CALL WRTMAT(ABIG,LRBIG, LCBIG, LRBIG, LCBIG)
        ELSE
          CALL PRSYM(ABIG, LRBIG)
        END IF
*
      END IF
*
      DO JC_SMA = 1, LCSMA
        IF(ISYMSMA.EQ.0) THEN
          JRMIN = 1
        ELSE
          JRMIN = JC_SMA
        END IF
        DO JR_SMA = JRMIN, LRSMA
          JC_BIG = JC_SMA + IOFFC - 1
          JR_BIG = JR_SMA + IOFFR - 1
          IF(ISYMBIG.EQ.0.OR.(ISYMBIG.EQ.1.AND.JR_BIG.GE.JC_BIG)) THEN
            IF(ISYMSMA.EQ.0) THEN
             IADR_SMA = (JC_SMA-1)*LRSMA+JR_SMA
            ELSE
             IADR_SMA = JR_SMA*(JR_SMA-1)/2 + JC_SMA
            END IF
            IF(ISYMBIG.EQ.0) THEN
             IADR_BIG = (JC_BIG-1)*LRBIG+JR_BIG
            ELSE
             IADR_BIG = JR_BIG*(JR_BIG-1)/2 + JC_BIG
            END IF
            IF(IEC.EQ.1) THEN
             ASMA(IADR_SMA) = ABIG(IADR_BIG)
            ELSE
             ABIG(IADR_BIG) =  ASMA(IADR_SMA)
            END IF
          END IF
        END DO
      END DO
*
      IF(NTEST.GE.1000) THEN
        WRITE(6,*) ' Small and large matrix at return: '
        CALL WRTMAT(ASMA,LRSMA,LCSMA,LRSMA,LCSMA)
        WRITE(6,*)
        CALL WRTMAT(ABIG,LRBIG,LCBIG,LRBIG,LCBIG)
      END IF
*
      RETURN
      END

*******************************************************************
      SUBROUTINE Reduce_Batch(Creation,
     &                     
     &                           MAXLB,          
         !For GETSTR2
     &                           IAGP,LIA_SM2,IA_STR,
     &                           IBGP,LIB_SM2,IB_STR,
         !For K_TO_J_TOT         
     &                           KAD,XKAD,KASM,IKA_B,IKA_E,
     &                           IA,XIA,IB_OA,NKAINTM,NA_OP,
     &                           KBD,XKBD,KBSM,IKB_B,IKB_E, 
     &                           IB,XIB,IB_OB,NKBINTM,NB_OP,
         !Batch info
     &                           INum_Sym_in,ISym_A_in,ISym_B_in,
     &                           IA_SM_STR_S_in,IB_SM_STR_S_in,
     &                           IA_SM_STR_E_in,IB_SM_STR_E_in,
     &                           N_SubBlk_in,    
         !Additional output
     &                           INum_Sym_out,ISym_A_out,ISym_B_out,
     &                           IA_SM_STR_S_out,IB_SM_STR_S_out,
     &                           IA_SM_STR_E_out,IB_SM_STR_E_out,
     &                           N_SubBlk_out,N_Strings_out,    
     &                           IKZEROMAP)
         !Generates operator strings and use the information to find
         !mappings between K and J strings. Furthermore, it only
         !includes necessary operator strings so as to to compress the batch size.
         use symmetry_setup_krci
         implicit none
#include "mxpdim.inc"
#include "parluci.h"
#include "cgas.inc"
         !Input: All the batch lists of sub blocks (oh boy..)
         logical creation
         integer MAXLB
         integer IAGP(MXPNGAS),IBGP(MXPNGAS)
         integer LIA_SM2, LIB_SM2, IA_STR(*), IB_STR(*)
         integer KASM, KBSM, IKA_B, IKA_E, IKB_B, IKB_E
         integer IA(*), IB(*), IB_OA(MXNDGIRR,MXNDGIRR,MXNOP)
         integer IB_OB(MXNDGIRR,MXNDGIRR,MXNOP), NKAINTM(MXPOBS,MXNOP)
         integer NKBINTM(MXPOBS,MXNOP)
         integer NA_OP, NB_OP
         integer, intent(in) :: INum_Sym_in,ISym_A_in(NSMST)
         integer, intent(in) :: ISym_B_in(NSMST)
         integer, intent(in) :: IA_SM_STR_S_in(2,NSMST),
     &                          IB_SM_STR_S_in(2,NSMST)
         integer, intent(in) :: IA_SM_STR_E_in(2,NSMST),
     &                          IB_SM_STR_E_in(2,NSMST)
         integer, intent(in) :: N_SubBlk_in(NSMST)
         !Output: Array with K_TO_J mappings (if any), compressed batch
         !lists
         integer, intent(out) :: INum_Sym_out,ISym_A_out(NSMST)
         integer, intent(out) :: ISym_B_out(NSMST)
         integer, intent(out) :: IA_SM_STR_S_out(2,NSMST),
     &                           IB_SM_STR_S_out(2,NSMST)
         integer, intent(out) :: IA_SM_STR_E_out(2,NSMST),
     &                           IB_SM_STR_E_out(2,NSMST)
         integer, intent(out) :: N_SubBlk_out(NSMST), 
     &                           N_Strings_out
         integer IKZeroMap
         integer, intent(inout) :: KAD(MAXLB**4), KBD(MAXLB**4)
         real(8) XKAD(*), XKBD(*), XIA, XIB

         !Only used in this subroutine:
         integer IZEROKA, IZEROKB, KA_Off, KB_Off
         integer NSym_New, IA_SM, IB_SM, IUB, IUB_KJ
         integer IA_SM_ADJ, IB_SM_ADJ, NSub_New
         integer IA_B, IA_E, NA_B
         integer IB_B, IB_E, NB_B
         integer IBatch, ISym, ISubBlk
         integer I,J,K


!         do IBatch = 1, NBatch


      IKZeroMap = 0

      KA_off = 0
      KB_off = 0
      N_Strings_Out = 0
      Nsym_New = 0

      do ISym = 1, INum_Sym_in

       IA_SM = ISym_A_in(ISym)
       IB_SM = ISym_B_in(ISym)
       if(creation) then
        IUB = 1
        call getstr2_totsm_spgp_rel(IUB,IAGP,NGAS,IA_SM,
     &                             NA_OP,LIA_SM2,IA_STR)
        IUB = 2
        call getstr2_totsm_spgp_rel(IUB,IBGP,NGAS,IB_SM,
     &                              NB_OP,LIB_SM2,IB_STR)
       else !Annihilation batches
        IA_SM_ADJ = INVELM(IA_SM)
        IB_SM_ADJ = INVELM(IB_SM)

        IUB = 1
        call getstr2_totsm_spgp_rel(IUB,IAGP,NGAS,IA_SM_ADJ,
     &                             NA_OP,LIA_SM2,IA_STR)
        IUB = 2
        call getstr2_totsm_spgp_rel(IUB,IBGP,NGAS,IB_SM_ADJ,
     &                              NB_OP,LIB_SM2,IB_STR)
       end if

       NSub_New = 0

       do ISubBlk = 1,N_SubBlk_in(ISym)
        IUB_KJ = 1
        IA_B = IA_SM_STR_S_in(ISubBlk,ISym)
        IA_E = IA_SM_STR_E_in(ISubBlk,ISym)
        NA_B = IA_E - IA_B + 1
        call k_to_j_tot(KAD(1+KA_Off),XKAD,KASM,IKA_B,IKA_E,
     &                  IA_STR,NA_B,IA_B,IA_E,
     &                  IA,XIA,IB_OA,NKAINTM,NA_OP,
     &                  IZEROKA,IUB_KJ)
!        write(LUWRT,*) 'IZEROKA',IZEROKA

!        if(IZEROKA==0) then
        if(IZEROKA/=0) cycle !ISubBlk
         IUB_KJ = 2
         
         IB_B = IB_SM_STR_S_in(ISubBlk,ISym)
         IB_E = IB_SM_STR_E_in(ISubBlk,ISym)
         NB_B = IB_E - IB_B + 1

         call k_to_j_tot(KBD(1+KB_Off),XKBD,KBSM,IKB_B,IKB_E,
     &                   IB_STR,NB_B,IB_B,IB_E,
     &                   IB,XIB,IB_OB,NKBINTM,NB_OP,
     &                   IZEROKB,IUB_KJ)


!        write(LUWRT,*) 'IZEROKB',IZEROKB
!         if(IZEROKB==0) then
         if(IZEROKB/=0) cycle !ISubBlk
          NSub_New = NSub_New + 1 
          NSym_New = NSym_New + mod(NSub_New,2) 
!         write(LUWRT,*) 'KA matrix based on offset:'
!         call iwrtma(KAD(1+KA_Off),NA_B,IKA_E-IKA_B+1,
!     &               NA_B,IKA_E-IKA_B+1)
!         write(LUWRT,*) 'KB matrix based on offset:'
!         call iwrtma(KBD(1+KB_Off),NB_B,IKB_E-IKB_B+1,
!     &               NB_B,IKB_E-IKB_B+1)
         !Modulo since two sub blocks of  the same symmetry should not
         !contribute to no. of symmetries twice
          !K mapping offsets
          KA_Off = KA_Off + 
     &            (IKA_E - IKA_B + 1)*NA_B             
          KB_Off = KB_Off + 
     &            (IKB_E - IKB_B + 1)*NB_B             
          !Now setting up reduced batch
          N_Strings_Out = N_Strings_Out + NA_B*NB_B
          IA_SM_STR_S_out(NSub_New,NSym_New) = IA_B
          IA_SM_STR_E_out(NSub_New,NSym_New) = IA_E

          IB_SM_STR_S_out(NSub_New,NSym_New) = IB_B
          IB_SM_STR_E_out(NSub_New,NSym_New) = IB_E

          N_SubBlk_out(NSym_New) = NSub_New



!         end if

!        end if
       end do

       if(NSub_New == 0) cycle !ISym

       ISym_A_out(NSym_New) = IA_SM
       ISym_B_out(NSym_New) = IB_SM

      end do

      INum_Sym_Out = Nsym_New

      if(KB_Off == 0) IKZeroMap = 1

!      if(KB_Off == 0) then 
!         write(LUWRT,*) 'No mappings'
!       IKZeroMap = 1 !No mappings
!      else
!      write(LUWRT,*) 'Original Number of symmetries',INum_Sym_in
!      do I = 1,INum_Sym_in
!       write(LUWRT,*) 'IA_SM',ISym_A_in(I)
!       write(LUWRT,*) 'IB_SM',ISym_B_in(I)
!       write(LUWRT,*) 'Sub blocks:',N_SubBlk_in(I)
!       do J=1,N_SubBlk_in(I)
!        write(LUWRT,*) 'A start',IA_SM_STR_S_in(J,I)
!        write(LUWRT,*) 'A end',IA_SM_STR_E_in(J,I)
!        write(LUWRT,*) 'B start',IB_SM_STR_S_in(J,I)
!        write(LUWRT,*) 'B end',IB_SM_STR_E_in(J,I)
!       end do
!      end do
!         write(LUWRT,*) 'Reduced batch:'
!      write(LUWRT,*) 'New Number of symmetries',INum_Sym_out
!      write(LUWRT,*) 'Now no. of strings',N_Strings_Out
!
!      do I = 1,NSub_New
!      write(LUWRT,*) 'New set'
!       write(LUWRT,*) 'IA_SM',ISym_A_out(I)
!       write(LUWRT,*) 'IB_SM',ISym_B_out(I)
!       write(LUWRT,*) 'Sub blocks:',N_SubBlk_out(I)
!       do J=1,N_SubBlk_out(I)
!        write(LUWRT,*) 'A start',IA_SM_STR_S_out(J,I)
!        write(LUWRT,*) 'A end',IA_SM_STR_E_out(J,I)
!        write(LUWRT,*) 'B start',IB_SM_STR_S_out(J,I)
!        write(LUWRT,*) 'B end',IB_SM_STR_E_out(J,I)
!       end do
!      end do
!
!      end if

!      end do
         

      END SUBROUTINE
!*************************************************************************
      SUBROUTINE DST_BLOCKS_OVER_BATCHES(Creation,N_IA_IB_BT,IA_IB_SM,    
     &            NIA,NIB,MaxLB,Min_Size,
     &            NSC_Str_A,NSC_Str_B,ISC_sym,IOpSC_sym_A,IOpSC_sym_B,
     &            INum_Sym,ISym_A,ISym_B,IA_SM_STR_S,IB_SM_STR_S,
     &            IA_SM_STR_E, IB_SM_STR_E,N_SubBlk,
     &            N_Strings,
     &            L_A_Block,L_B_Block,L_Sym_Block
#if defined (VAR_MPI2)
     &            ,IOFF_BLK,IACT
#endif
     &            )
         !Distribute operator symmetry blocks over batches
         use symmetry_setup_krci
         implicit none
#include "parluci.h"
         !Input:
         !Number of batches N_IA_IB_BT (also WILL be OUTPUT) 
         !Total symmetry IA_IB_SM of OA * OB, which is either a creation
         !or annihilation operator
         !Total symmetry of sigma or c vector ISC_sym
         !Symmetry of Creation*sigma or Annihilation*c vector:
         !  IOpSC_sym_A and IopSC_sym_B
         !Number of symmetry strings NSMST
         !Number of strings within each symmetry of A and B: NIA and NIB
         !Number of sigma or c strings for each symmetry of A and B:
         !NSC_Str_A and NSC_Str_B
         logical Creation !Creation is true, annihilation false
         integer IA_IB_SM, N_IA_IB_BT, NIA(NSMST), NIB(NSMST)
         integer ISC_sym, NSC_Str_A(NSMST), NSC_Str_B(NSMST)
         integer IOpSC_sym_A, IOpSC_sym_B
         integer MaxLB,Min_Size

         !Variables only used in this routine
         integer IA_SM, IB_SM,I_A_Block_size,I_B_Block_size
         integer ISCA_SM, ISCB_SM, ISCB_compare !Symmetries of sigma/c strings
         integer LIA_SM, LIB_SM
         integer Leftover, ISym_Count, IA_IB_BT
         integer IBlock_Size, IA_Block_Size, IChunk_Size
         integer L_A_Block(NSMST), L_B_Block(NSMST) 
         integer L_Sym_Block(NSMST)
!         Integer, allocatable :: L_A_Block(:), L_B_Block(:) 
!         Integer, allocatable :: L_Sym_Block(:)
!         integer LUWRT
         !Output
         !Number of symmetries for batch INum_Sym,
         !Symmetry A and B: ISym_A and ISym_B
         !Start/End within Symmetry A, B:
         !IA_SM_STR_S/IA_SM_STR_E,IB_SM_STR_S/IB_SM_STR_E
         !N_SubBlk: How many sub blocks in batch of specific symmetry (1
         !or 2)
         !N_Strings: Number of strings in batch. Needed for matrix
         !dimensions
!         Integer INum_Sym(N_IA_IB_BT), ISym_A(NSMST,N_IA_IB_BT)
!         Integer ISym_B(NSMST,N_IA_IB_BT)
!         Integer IA_SM_STR_S(2,NSMST,N_IA_IB_BT), 
!     &           IB_SM_STR_S(2,NSMST,N_IA_IB_BT)
!         Integer IA_SM_STR_E(2,NSMST,N_IA_IB_BT), 
!     &           IB_SM_STR_E(2,NSMST,N_IA_IB_BT),
!     &           N_SubBlk(NSMST,N_IA_IB_BT)
!         Integer N_Strings(N_IA_IB_BT)
         integer INum_Sym(100), ISym_A(NSMST,100)
         integer ISym_B(NSMST,100)
         integer IA_SM_STR_S(2,NSMST,100), 
     &           IB_SM_STR_S(2,NSMST,100)
         integer IA_SM_STR_E(2,NSMST,100), 
     &           IB_SM_STR_E(2,NSMST,100),
     &           N_SubBlk(NSMST,100)
         integer N_Strings(100)
         integer I,J,K
#if defined (VAR_MPI2)
         integer, intent(in) :: IOFF_BLK, IACT(*)
         integer I_BLK_SCR
#endif

!#define Dst_Blk_Debug
#ifdef Dst_Blk_Debug
         write(LUWRT,*) '              Inside DST_BLOCKS_OVER_BATCHES'
         if(Creation) then
            write(LUWRT,*) '              Handling creation'
         else
            write(LUWRT,*) '              Handling annihilation'
         end if
         write(*,*) 'LUWRT = ',LUWRT
         write(LUWRT,*) 'Input variables:'
         write(LUWRT,*) 'NBATCH = ',N_IA_IB_BT
         write(LUWRT,*) 'IA_IB_SM = ',IA_IB_SM
         write(LUWRT,*) 'MaxLB = ',MaxLB
         write(LUWRT,*) 'Min_Size = ',Min_Size
#endif


!         Allocate(L_Sym_Block(NSMST))
!         Allocate(L_A_Block(NSMST))
!         Allocate(L_B_Block(NSMST))


!         write(LUWRT,*) 'Allocation ok'
!Initial conditions

         call izero(L_A_Block,NSMST)
         call izero(L_B_Block,NSMST)
         call izero(L_Sym_Block,NSMST)
         !The three arrays give the lengths of the blocks accounted



         do IA_IB_BT = 1, N_IA_IB_BT
            do IA_SM = 1, NSMST
               N_SubBlk(IA_SM,IA_IB_BT) = 1
            end do
         end do

!         write(LUWRT,*) 'Initial number of sub blocks set'
         IA_SM = 1
!        
         !Now: Where to put the symmetry blocks...

!#define Dst_Blk_Debug
         Batch_loop: do IA_IB_BT = 1, N_IA_IB_BT

!         write(LUWRT,*) 'Entering batch loop'
!         write(LUWRT,*) 'Batch number = ',IA_IB_BT
         Leftover = MaxLB**2
         ISym_Count = 0 !Count how many symmetries will be in batch
         !How many sub blocks of a particular symmetry in batch
         IA_SM_Loop: do while(IA_SM <= NSMST)

         
         IB_SM = IDBGMULT(IA_IB_SM,INVELM(IA_SM))
 
!         write(LUWRT,*) 'IA_SM = ',IA_SM
!         write(LUWRT,*) 'IB_SM = ',IB_SM
#if defined (VAR_MPI2)
         if(Creation) then
            ISCA_SM =
     &      IDBGMULT(IA_SM,INVELM(IOpSC_Sym_A))

            I_BLK_SCR = 0
            I_BLK_SCR = IOFF_BLK + ISCA_SM -1
            if(IACT(I_BLK_SCR).ne.MYPROC) then
!               write(LUWRT,*) 'Not my process'
!               write(LUWRT,*) 'IASM',ISCA_SM
               IA_SM = IA_SM + 1
               cycle IA_SM_Loop
            end if
            !Not this process

            LIA_SM = NIA(IA_SM)
            LIB_SM = NIB(IB_SM)

            ISCB_SM =
     &      IDBGMULT(ISC_sym,INVELM(ISCA_SM))

            ISCB_compare =
     &      IDBGMULT(IB_SM,INVELM(IopSC_Sym_B))

         else
            ISCA_SM =
     &      IDBGMULT(IOpSC_Sym_A,INVELM(IA_SM))
            I_BLK_SCR = 0
            I_BLK_SCR = IOFF_BLK + ISCA_SM - 1
            if(IACT(I_BLK_SCR).eq.0) then
!               write(LUWRT,*) 'No connection'
!               write(LUWRT,*) 'JASM',ISCA_SM
               IA_SM = IA_SM + 1
               cycle IA_SM_Loop
            end if !No c connections

            LIA_SM = NIA(INVELM(IA_SM))
            LIB_SM = NIB(INVELM(IB_SM)) 

            ISCB_SM = 
     &      IDBGMULT(ISC_sym,INVELM(ISCA_SM))

            ISCB_compare =
     &      IDBGMULT(IOpSC_Sym_B,INVELM(IB_SM)) 
         end if
#else
!Flag here for either creation/annihilation
         if(Creation) then
            LIA_SM = NIA(IA_SM)
            LIB_SM = NIB(IB_SM)

            ISCA_SM =
     &      IDBGMULT(IA_SM,INVELM(IOpSC_Sym_A))

            ISCB_SM =
     &      IDBGMULT(ISC_sym,INVELM(ISCA_SM))

            ISCB_compare =
     &      IDBGMULT(IB_SM,INVELM(IopSC_Sym_B))

         else
            LIA_SM = NIA(INVELM(IA_SM))
            LIB_SM = NIB(INVELM(IB_SM)) 

            ISCA_SM =
     &      IDBGMULT(IOpSC_Sym_A,INVELM(IA_SM))

            ISCB_SM = 
     &      IDBGMULT(ISC_sym,INVELM(ISCA_SM))

            ISCB_compare =
     &      IDBGMULT(IOpSC_Sym_B,INVELM(IB_SM)) 
         end if

         if( (ISCB_SM/=ISCB_compare)
     &      .or. 
#if defined (VAR_MPI2)
     &      (LIA_SM*LIB_SM==0)
#else
     &      (LIA_SM*LIB_SM*
     &      NSC_Str_A(ISCA_SM)*NSC_Str_B(ISCB_SM)==0)
#endif
     &      )then
            IA_SM = IA_SM + 1
            cycle IA_SM_Loop
         end if
#endif

#ifdef Dst_Blk_Debug
         if(LIA_SM*LIB_SM/=0) then
            write(LUWRT,*) 'Non-zero number of elements'
         write(LUWRT,*) 'IA_SM  = ', IA_SM 
         write(LUWRT,*) 'IB_SM  = ', IB_SM 
         write(LUWRT,*) 'LIA_SM = ', LIA_SM 
         write(LUWRT,*) 'LIB_SM = ', LIB_SM 
!         write(LUWRT,*) 'LIA_SM and LIB_SM found'
         end if
#endif

!         if(LIA_SM * LIB_SM <= 0) then
!!            write(LUWRT,*) 'No elements for IA_SM = ',IA_SM
!            IA_SM = IA_SM + 1
!            cycle IA_SM_Loop
!         else if(L_Sym_Block(IA_SM)+Leftover>=LIA_SM*LIB_SM) then
         if(L_Sym_Block(IA_SM)+Leftover>=LIA_SM*LIB_SM) then
            !Batch is almost full, but the leftover part of the block is 
            !so small that we might as well put it into the batch
            continue
         else if(Leftover-Min_size<=0) then
!#ifdef Dst_Blk_Debug
!            write(LUWRT,*) 'Not enough room at IA_SM = ',IA_SM
!            write(LUWRT,*) 'LIA_SM = ',LIA_SM
!            write(LUWRT,*) 'LIB_SM = ',LIB_SM
!#endif
         !Not enough room in batch -
         !moving on to the next
            N_Strings(IA_IB_BT) = MAXLB**2 - Leftover
!            write(LUWRT,*) 'MAXLB**2 - Leftover',MAXLB**2-Leftover
            cycle Batch_loop
         end if

         if(L_Sym_Block(IA_SM)==LIA_SM*LIB_SM) then 
         !Block has already been taken care of
            IA_SM = IA_SM + 1
            cycle IA_SM_Loop
         end if

         ISym_Count = ISym_Count + 1
!         write(LUWRT,*) 'Batch number = ',IA_IB_BT
!         write(LUWRT,*) 'Room to fill up batch!'

         ISym_A(ISym_Count,IA_IB_BT) = IA_SM
         ISym_B(ISym_Count,IA_IB_BT) = IB_SM

!         write(LUWRT,*) 'Leftover = ',Leftover
         if(Leftover-LIA_SM*LIB_SM+L_Sym_Block(IA_SM)<0) then
            !Only room for some of the block
!            write(LUWRT,*) 'Only room for some of the block'
            IA_SM_STR_S(1,ISym_Count,IA_IB_BT) =
     &         min(L_A_Block(IA_SM)+1,LIA_SM)

            !Edited 29/8/18
            IB_SM_STR_S(1,ISym_Count,IA_IB_BT) = 
     &         min(L_B_Block(IA_SM)+1,LIB_SM)

            IBlock_size = min(LIA_SM,LIB_SM,int(sqrt(real(Leftover))))

!            if(L_A_Block(IA_SM)>0) then
!!               write(LUWRT,*) 
!!     & 'Part of block column has already been batched'
!!               if(
!               IB_SM_STR_S(1,ISym_Count,IA_IB_BT) = 
!     &         min(LIB_SM,
!     &         IB_SM_STR_S(1,INum_Sym(IA_IB_BT - 1), IA_IB_BT - 1))
!
!               IA_SM_STR_E(1,ISym_Count,IA_IB_BT) = 
!     &         min(IA_SM_STR_S(1,ISym_Count,IA_IB_BT)+IBlock_size-1,
!     &         LIA_SM)
!
!               IB_SM_STR_E(1,ISym_Count,IA_IB_BT) = 
!     &         min(LIB_SM,
!     &         IB_SM_STR_E(1,INum_Sym(IA_IB_BT - 1), IA_IB_BT - 1)  )
!
!               L_A_Block(IA_SM) = IA_SM_STR_E(1,ISym_Count,IA_IB_BT)
!
            if(IBlock_size == LIB_SM) then 
!            if(IBlock_size == LIB_SM) then 
!               write(LUWRT,*) 'Stretching in A direction'
               !Need to stretch sub block in
               !A-direction
               if(L_A_Block(IA_SM)==0) then
            IB_SM_STR_S(1,ISym_Count,IA_IB_BT) = 
     &         min(L_B_Block(IA_SM)+1,LIB_SM)

               I_A_Block_size = Leftover/(LIB_SM-L_B_Block(IA_SM))

               IA_SM_STR_E(1,ISym_Count,IA_IB_BT) = 
     &         min(IA_SM_STR_S(1,ISym_Count,IA_IB_BT)-1
     &         +I_A_Block_size,LIA_SM)

               L_A_Block(IA_SM) = IA_SM_STR_E(1,ISym_Count,IA_IB_BT)
               IB_SM_STR_E(1,ISym_Count,IA_IB_BT) = LIB_SM

               else
               I_A_Block_size = Leftover/(LIB_SM-L_B_Block(IA_SM))

                IB_SM_STR_S(1,ISym_Count,IA_IB_BT) = 
     &          min(LIB_SM,
     &          IB_SM_STR_S(1,INum_Sym(IA_IB_BT - 1), IA_IB_BT - 1))

                IA_SM_STR_E(1,ISym_Count,IA_IB_BT) = 
     &          min(IA_SM_STR_S(1,ISym_Count,IA_IB_BT)+I_A_Block_size-1,
     &          LIA_SM)

                IB_SM_STR_E(1,ISym_Count,IA_IB_BT) = 
     &          min(LIB_SM,
     &          IB_SM_STR_E(1,INum_Sym(IA_IB_BT - 1), IA_IB_BT - 1)  )

                L_A_Block(IA_SM) = IA_SM_STR_E(1,ISym_Count,IA_IB_BT)

               end if
!               write(LUWRT,*) 'A stretching done'


            else if(L_A_Block(IA_SM)>0) then
!               write(LUWRT,*) 
!     & 'Part of block column has already been batched'
!               if(
               IB_SM_STR_S(1,ISym_Count,IA_IB_BT) = 
     &         min(LIB_SM,
     &         IB_SM_STR_S(1,INum_Sym(IA_IB_BT - 1), IA_IB_BT - 1))

               IA_SM_STR_E(1,ISym_Count,IA_IB_BT) = 
     &         min(IA_SM_STR_S(1,ISym_Count,IA_IB_BT)+IBlock_size-1,
     &         LIA_SM)

               IB_SM_STR_E(1,ISym_Count,IA_IB_BT) = 
     &         min(LIB_SM,
     &         IB_SM_STR_E(1,INum_Sym(IA_IB_BT - 1), IA_IB_BT - 1)  )

               L_A_Block(IA_SM) = IA_SM_STR_E(1,ISym_Count,IA_IB_BT)

            else if(IBlock_size == LIA_SM) then !Stretch in B

!               write(LUWRT,*) 'Stretching in B direction'
            IB_SM_STR_S(1,ISym_Count,IA_IB_BT) = 
     &         min(L_B_Block(IA_SM)+1,LIB_SM)

               I_B_Block_size = Leftover/(LIA_SM-L_A_Block(IA_SM))

               IA_SM_STR_E(1,ISym_Count,IA_IB_BT) = LIA_SM


               IB_SM_STR_E(1,ISym_Count,IA_IB_BT) = 
     &         min(IB_SM_STR_S(1,ISym_Count,IA_IB_BT)+I_B_Block_size-1,
     &         LIB_SM)
               L_B_Block(IA_SM) = IB_SM_STR_E(1,ISym_Count,IA_IB_BT) 
!               write(LUWRT,*) 'B stretching done'

            else
!               write(LUWRT,*) 'Need no stretching in either direction'
            IB_SM_STR_S(1,ISym_Count,IA_IB_BT) = 
     &         min(L_B_Block(IA_SM)+1,LIB_SM)

               IA_SM_STR_E(1,ISym_Count,IA_IB_BT) = 
     &         min(IA_SM_STR_S(1,ISym_Count,IA_IB_BT)+IBlock_size-1,
     &         LIA_SM)

               IB_SM_STR_E(1,ISym_Count,IA_IB_BT) = 
     &         min(IB_SM_STR_S(1,ISym_Count,IA_IB_BT)+IBlock_size-1,
     &         LIB_SM)

               L_A_Block(IA_SM) = IA_SM_STR_E(1,ISym_Count,IA_IB_BT)
            end if

#ifdef Dst_Blk_Debug
            write(LUWRT,*) 'For batch ',IA_IB_BT
            write(LUWRT,*) 'FIRST printout' 
            write(LUWRT,*) 'and symmetry IA_SM = ',IA_SM
            write(LUWRT,*) 'IA start',
     & IA_SM_STR_S(1,ISym_Count,IA_IB_BT)
            write(LUWRT,*) 'IA end',
     & IA_SM_STR_E(1,ISym_Count,IA_IB_BT)

            write(LUWRT,*) 'IB start',
     & IB_SM_STR_S(1,ISym_Count,IA_IB_BT)

            write(LUWRT,*) 'IB end',
     & IB_SM_STR_E(1,ISym_Count,IA_IB_BT)
#endif

            IChunk_size=
            !How much does the sub block fill up
     &      (IA_SM_STR_E(1,ISym_Count,IA_IB_BT) -
     &       IA_SM_STR_S(1,ISym_Count,IA_IB_BT) + 1) 
     &      * 
     &      (IB_SM_STR_E(1,ISym_Count,IA_IB_BT) -
     &      IB_SM_STR_S(1,ISym_Count,IA_IB_BT) + 1)

            Leftover = Leftover - IChunk_size

!           write(LUWRT,*) 'Leftover - chunk = ',Leftover 

           L_Sym_Block(IA_SM) = L_Sym_Block(IA_SM) + IChunk_size

!            write(LUWRT,*) 'Total accumulated symmetry block =',             
!     &         L_Sym_Block(IA_SM)
!            write(LUWRT,*) 'End of B is'
!            write(LUWRT,*) IB_SM_STR_E(1,ISym_Count,IA_IB_BT)
            if(L_A_Block(IA_SM)==LIA_SM) then 
            !Reset L_A_Block, shift L_B_Block
!            write(LUWRT,*) 'LIA_SM has been reached, and'
!            write(LUWRT,*) 'End of B is'
!            write(LUWRT,*) IB_SM_STR_E(1,ISym_Count,IA_IB_BT)
!            write(LUWRT,*) 'Shifting B block from'
!            write(LUWRT,*) L_B_Block(IA_SM)
               L_A_Block(IA_SM) = 0
               L_B_Block(IA_SM) = IB_SM_STR_E(1,ISym_Count,IA_IB_BT)
!               write(LUWRT,*) 'to'
!               write(LUWRT,*) L_B_Block(IA_SM)
!
!
            end if
            INum_sym(IA_IB_BT) = ISym_Count
            N_Strings(IA_IB_BT) = MAXLB**2 - Leftover
!            write(LUWRT,*) 'MAXLB**2 - Leftover',MAXLB**2-Leftover
!            write(LUWRT,*) 'In batch ', IA_IB_BT
!            write(LUWRT,*) 'There are ',ISym_Count,' symmetries'
            cycle Batch_Loop

         else 
!            write(LUWRT,*) 'Room for remainder of block!'

!           if((L_A_Block(IA_SM)==0).and.(L_B_Block(IA_SM)==0)) then
           if((L_A_Block(IA_SM)==0)) then
!              write(LUWRT,*) 'Room for WHOLE block!'
              IA_SM_STR_S(1,ISym_Count,IA_IB_BT) = 1
              IB_SM_STR_S(1,ISym_Count,IA_IB_BT) = L_B_Block(IA_SM) + 1

              IA_SM_STR_E(1,ISym_Count,IA_IB_BT) = LIA_SM
              IB_SM_STR_E(1,ISym_Count,IA_IB_BT) = LIB_SM
              
           else if(IA_SM_STR_E(N_SubBlk(ISym_A(INum_Sym(IA_IB_BT-1),
     &             IA_IB_BT-1),
     &             IA_IB_BT-1),
     &             INum_Sym(IA_IB_BT-1),IA_IB_BT-1) ==LIA_SM) then
!              write(LUWRT,*) 'End of A strings has been reached'
              IA_SM_STR_S(1,ISym_Count,IA_IB_BT) = LIA_SM
              IB_SM_STR_S(1,ISym_Count,IA_IB_BT) = L_B_Block(IA_SM) + 1
              IA_SM_STR_E(1,ISym_Count,IA_IB_BT) = LIA_SM
              IB_SM_STR_E(1,ISym_Count,IA_IB_BT) = LIB_SM
           else if(L_Sym_Block(IA_SM)>0) then
!              write(LUWRT,*) 'Some of the block has been covered'
              IA_SM_STR_S(1,ISym_Count,IA_IB_BT) = L_A_Block(IA_SM) + 1
              IB_SM_STR_S(1,ISym_Count,IA_IB_BT) = L_B_Block(IA_SM) + 1
              IA_SM_STR_E(1,ISym_Count,IA_IB_BT) = LIA_SM
              IB_SM_STR_E(1,ISym_Count,IA_IB_BT) = 
     & IB_SM_STR_E(N_SubBlk(ISym_B(INum_Sym(IA_IB_BT-1),IA_IB_BT-1)
     & ,IA_IB_BT-1)
     &         ,INum_Sym(IA_IB_BT-1),IA_IB_BT-1) 

              !Resetting L_A_Block(IA_SM)
              L_A_Block(IA_SM) = 0

           else
!             write(LUWRT,*) 'Room for leftover part of sub block!'
             !Room for last part, but need to split into two sub blocks
             IA_SM_STR_S(1,ISym_Count,IA_IB_BT) = L_A_Block(IA_SM) + 1
             IB_SM_STR_S(1,ISym_Count,IA_IB_BT) = L_B_Block(IA_SM) + 1
             IBlock_size = int(sqrt(real(Leftover)))
!             write(LUWRT,*) 'Block size is',IBlock_size
             IA_SM_STR_E(1,ISym_Count,IA_IB_BT) = 
!     &       min(IA_SM_STR_S(1,IA_IB_BT,ISym_Count)+IBlock_size,
     &       min(IA_SM_STR_S(1,ISym_Count,IA_IB_BT)+IBlock_size-1,
     &       LIA_SM)
             IB_SM_STR_E(1,ISym_Count,IA_IB_BT) = 
     &       min(IB_SM_STR_S(1,ISym_Count,IA_IB_BT)+IBlock_size-1,
     &       LIB_SM)
           end if

#ifdef Dst_Blk_Debug
            write(LUWRT,*) 'For batch ',IA_IB_BT
            write(LUWRT,*) 'SECOND printout'
            write(LUWRT,*) 'and symmetry IA_SM = ',IA_SM
            write(LUWRT,*) 'IA start',
     & IA_SM_STR_S(1,ISym_Count,IA_IB_BT)
            write(LUWRT,*) 'IA end',
     & IA_SM_STR_E(1,ISym_Count,IA_IB_BT)

            write(LUWRT,*) 'IB start',
     & IB_SM_STR_S(1,ISym_Count,IA_IB_BT)

            write(LUWRT,*) 'IB end',
     & IB_SM_STR_E(1,ISym_Count,IA_IB_BT)
#endif
            IChunk_size=
            !How much does the sub block fill up
     &      (IA_SM_STR_E(1,ISym_Count,IA_IB_BT) -
     &       IA_SM_STR_S(1,ISym_Count,IA_IB_BT) + 1) 
     &      * 
     &      (IB_SM_STR_E(1,ISym_Count,IA_IB_BT) -
     &      IB_SM_STR_S(1,ISym_Count,IA_IB_BT) + 1)

            Leftover = Leftover - IChunk_size
            L_Sym_Block(IA_SM) = L_Sym_Block(IA_SM) + IChunk_size
! Maybe this line               L_A_Block(IA_SM) = IA_SM_STR_E(1,IA_IB_BT,ISym_Count)
!            L_A_Block(IA_SM) = 

!            write(LUWRT,*) 'Total accumulated symmetry block =',             
!     &         L_Sym_Block(IA_SM)
            if(IA_SM_STR_E(1,ISym_Count,IA_IB_BT).lt.LIA_SM) then

!               write(LUWRT,*) '     Need two sub blocks due to A'
               IA_SM_STR_S(2,ISym_Count,IA_IB_BT) =
     &            IA_SM_STR_E(1,ISym_Count,IA_IB_BT) + 1

               IB_SM_STR_S(2,ISym_Count,IA_IB_BT) = 
     &            min(LIB_SM,L_B_Block(IA_SM) + 1)

               IA_SM_STR_E(2,ISym_Count,IA_IB_BT) = LIA_SM
               IB_SM_STR_E(2,ISym_Count,IA_IB_BT) = LIB_SM

!               write(LUWRT,*) 'THIRD printout'
               N_SubBlk(ISym_Count,IA_IB_BT) = 2

               IChunk_size=
               !How much does the sub block fill up
     &         (IA_SM_STR_E(2,ISym_Count,IA_IB_BT) -
     &          IA_SM_STR_S(2,ISym_Count,IA_IB_BT) + 1) 
     &         * 
     &         (IB_SM_STR_E(2,ISym_Count,IA_IB_BT) -
     &         IB_SM_STR_S(2,ISym_Count,IA_IB_BT) + 1)

               Leftover = Leftover - IChunk_size
               L_Sym_Block(IA_SM) = L_Sym_Block(IA_SM) + IChunk_size

#ifdef Dst_Blk_Debug
            write(LUWRT,*) 'Total accumulated symmetry block =',             
     &         L_Sym_Block(IA_SM)
               write(LUWRT,*) 'FOURTH printout'
            write(LUWRT,*) 'and symmetry IA_SM = ',IA_SM
            write(LUWRT,*) 'IA start',
     & IA_SM_STR_S(1,ISym_Count,IA_IB_BT)
            write(LUWRT,*) 'IA end',
     & IA_SM_STR_E(1,ISym_Count,IA_IB_BT)

            write(LUWRT,*) 'IB start',
     & IB_SM_STR_S(1,ISym_Count,IA_IB_BT)

            write(LUWRT,*) 'IB end',
     & IB_SM_STR_E(1,ISym_Count,IA_IB_BT)
#endif
            else if(IB_SM_STR_E(1,ISym_Count,IA_IB_BT).lt.LIB_SM) then 
!               write(LUWRT,*) '     Need two sub blocks due to B'
               IA_SM_STR_S(2,ISym_Count,IA_IB_BT) =
     &            min(LIA_SM,L_A_Block(IA_SM) + 1)

               IB_SM_STR_S(2,ISym_Count,IA_IB_BT) =
     &            IB_SM_STR_E(1,ISym_Count,IA_IB_BT) + 1

               IA_SM_STR_E(2,ISym_Count,IA_IB_BT) = LIA_SM
               IB_SM_STR_E(2,ISym_Count,IA_IB_BT) = LIB_SM


               N_SubBlk(ISym_Count,IA_IB_BT) = 2

               IChunk_size=
               !How much does the sub block fill up
     &         (IA_SM_STR_E(2,ISym_Count,IA_IB_BT) -
     &          IA_SM_STR_S(2,ISym_Count,IA_IB_BT) + 1) 
     &         * 
     &         (IB_SM_STR_E(2,ISym_Count,IA_IB_BT) -
     &         IB_SM_STR_S(2,ISym_Count,IA_IB_BT) + 1)

               Leftover = Leftover - IChunk_size
               L_Sym_Block(IA_SM) = L_Sym_Block(IA_SM) + IChunk_size
#ifdef Dst_Blk_Debug
            write(LUWRT,*) 'Total accumulated symmetry block =',             
     &         L_Sym_Block(IA_SM)

               write(LUWRT,*) 'FIFTH printout'
            write(LUWRT,*) 'and symmetry IA_SM = ',IA_SM
            write(LUWRT,*) 'IA start',
     & IA_SM_STR_S(1,ISym_Count,IA_IB_BT)
            write(LUWRT,*) 'IA end',
     & IA_SM_STR_E(1,ISym_Count,IA_IB_BT)

            write(LUWRT,*) 'IB start',
     & IB_SM_STR_S(1,ISym_Count,IA_IB_BT)

            write(LUWRT,*) 'IB end',
     & IB_SM_STR_E(1,ISym_Count,IA_IB_BT)
#endif
            end if
!            ISym_Count = ISym_Count + 1
            INum_sym(IA_IB_BT) = ISym_Count
!            IA_SM = IA_SM + 1
            !Hasn't reached end of B strings

!           write(LUWRT,*) 'Leftover - chunk = ',Leftover 
!            L_Sym_Block(IA_SM) = L_Sym_Block(IA_SM) + IChunk_size
            IA_SM = IA_SM + 1
!
!            L_B_Block(IA_SM) = IB_SM_STR_E(1,IA_IB_BT,ISym_Count)
!            L_A_Block(IA_SM) = 0
!
!            IA_SM_STR_S(2,IA_IB_BT,ISym_Count) = L_A_Block(IA_SM) + 1
!            IB_SM_STR_S(2,IA_IB_BT,ISym_Count) = L_B_Block(IA_SM) + 1
!            IA_SM_STR_E(2,IA_IB_BT,ISym_Count) = LIA_SM
!            IB_SM_STR_E(2,IA_IB_BT,ISym_Count) = LIB_SM

         end if
!         write(LUWRT,*) 'Almost out of SM loop'
!            write(LUWRT,*) 'and symmetry IA_SM = ',IA_SM
!            write(LUWRT,*) 'IA start',
!     & IA_SM_STR_S(1,IA_IB_BT,ISym_Count)
!            write(LUWRT,*) 'IA end',
!     & IA_SM_STR_E(1,IA_IB_BT,ISym_Count)
!
!            write(LUWRT,*) 'IB start',
!     & IB_SM_STR_S(1,IA_IB_BT,ISym_Count)
!
!            write(LUWRT,*) 'IB end',
!     & IB_SM_STR_E(1,IA_IB_BT,ISym_Count)
         end do IA_SM_Loop


         INum_sym(IA_IB_BT) = ISym_Count
         N_Strings(IA_IB_BT) = MAXLB**2 - Leftover
!         write(LUWRT,*) 'MAXLB**2 - Leftover',MAXLB**2-Leftover
!         write(LUWRT,*) 'Symmetry count = ',INum_sym(IA_IB_BT)

            IA_SM = IA_SM + 1
         if(IA_SM > NSMST) then 
            !Don't need as many batches as expected
            !reducing number of batches
            N_IA_IB_BT = IA_IB_BT
            exit Batch_Loop

         end if
         end do Batch_Loop

!#define Dst_Blk_Debug
#ifdef Dst_Blk_Debug
         write(LUWRT,*) 'Out of batch loops'
         write(LUWRT,*) 'FINAL printout'
!First block
         if(creation) then
            write(LUWRT,*) 'For creation:'
         else
            write(LUWRT,*) 'For annihilation:'
         end if
                     do I=1,N_IA_IB_BT
                        write(LUWRT,*) 'Batch number ',I
                        write(LUWRT,*) 'INum_Sym(I) = ',INum_Sym(I)
                        do J=1,INum_Sym(I)
                        if(creation) then
                           write(LUWRT,*) 'SymA(I), No. of str. ', 
     &                  ISym_A(J,I),NIA(ISym_A(J,I))
                           write(LUWRT,*) 'SymB(I), No. of str. ', 
     &                     ISym_B(J,I),NIB(ISym_B(J,I))
                        else
                           write(LUWRT,*) 'SymA(I), No. of str. ', 
     &               ISym_A(J,I),NIA(INVELM(ISym_A(J,I)))
                           write(LUWRT,*) 'SymB(I), No. of str. ', 
     &               ISym_B(J,I),NIB(INVELM(ISym_B(J,I)))
                        end if
                           write(LUWRT,*) 'No. of sub blocks
     &                     ',N_SubBlk(J,I)
                           do K=1,N_SubBlk(J,I)
                              write(LUWRT,*) 'String start AA = '
     &                        ,IA_SM_STR_S(K,J,I)
                              write(LUWRT,*) 'String end AA   = '
     &                        ,IA_SM_STR_E(K,J,I)
                              write(LUWRT,*) 'String start AB = '
     &                        ,IB_SM_STR_S(K,J,I)
                              write(LUWRT,*) 'String end AB   = '
     &                        ,IB_SM_STR_E(K,J,I)
                              if((IA_SM_STR_S(K,J,I)>IA_SM_STR_E(K,J,I))
     &                           .or.
     &                  (IB_SM_STR_S(K,J,I)>IB_SM_STR_E(K,J,I)))
     &                        then
                              write(6,*) 
     &         'ERROR - start is bigger than end!!!'
                              stop
                              end if

                           end do
                        end do
                     end do

                     if(creation) then
                        do I=1,NSMST
                           J = IDBGMULT(IA_IB_SM,INVELM(I))
                           LIA_SM = NIA(I)
                           LIB_SM = NIB(J)
                           if((L_Sym_Block(I)/=LIA_SM*LIB_SM)) then
                              write(LUWRT,*) 'ALARM'
                              write(LUWRT,*) 'For IA_SM = ',I
                              write(LUWRT,*) 'Not all strings covered'
!                              stop
                           end if
                        end do
                     else
                        do I=1,NSMST
                           J = IDBGMULT(IA_IB_SM,INVELM(I))
                           LIA_SM = NIA(INVELM(I))
                           LIB_SM = NIB(INVELM(J))
                           if(L_Sym_Block(I)/=LIA_SM*LIB_SM) then
                              write(LUWRT,*) 'ALARM'
                              write(LUWRT,*) 'For IA_SM = ',I
                              write(LUWRT,*) 'Not all strings covered'
!                              stop
                           end if
                           
                        end do
                     end if
#endif
!#undef Dst_Blk_Debug
!      deallocate(L_Sym_Block)
!      deallocate(L_A_Block)
!      deallocate(L_B_Block)

      END SUBROUTINE

!***********************************************************************
      SUBROUTINE IDIM_TCC_DBG(ITSOSO_TP,NTSOSO_TP,ISYM,
     &                        MX_ST_TSOSO,MX_ST_TSOSO_BLK,MX_TBLK,
     &                        MX_TBLK_AS,IFTTWO,
     &                        IFSFLT1,ILSFLT1,N1ELINT,IPRCC,
     &                        ica_grp,icb_grp,iaa_grp,iab_grp,
     &                        ndist_ca,ndist_cb,ndist_aa,ndist_ab)
*
* Dimension of T operators in spin-orbital basis
*
* Largest number of strings of given sym in T(ICA,ICB,IAA,IAB)
* i.e. largest block of ICA, ICB,IAA,IAB of given sym 
*
* Size of block required to hold above blocks
*
* Jeppe Olsen, Summer of 99
*
* Double group version
*
      use symmetry_setup_krci
#include "implicit.inc"
*. General input
#include "mxpdim.inc"
#include "cgas.inc"
#include "gasstr.inc"
#include "integrals_off.inc"
*. Specific input
      INTEGER ITSOSO_TP(4*NGAS,NTSOSO_TP)
*. Local scratch 
      INTEGER ICA_GRP(NGAS), ICB_GRP(NGAS)
      INTEGER IAA_GRP(NGAS), IAB_GRP(NGAS)
      INTEGER ndist_ca(*), ndist_cb(*), ndist_aa(*), ndist_ab(*)
*.Output : offset for each type
      INTEGER*8 LEN_SCR1, LEN_SCR2, LEN_SCR3, LEN_SCR4
      INTEGER*8 LEN_SCR5, LEN_SCR6, LEN_SCR7, LEN_SCR8
      INTEGER*8 LENGTH, LENGTH2, N2ELINT_I8
      INTEGER*8 MX_TBLK, MX_TBLK_AS, ITSS_TP_I8
*
      LEN_SCR1 = 0
      LEN_SCR2 = 0
      LEN_SCR3 = 0
      LEN_SCR4 = 0
      LEN_SCR5 = 0
      LEN_SCR6 = 0
      LEN_SCR7 = 0
      LEN_SCR8 = 0
      ITSS_TP_I8 = 0
*
      NTEST = 0000
      NTEST = MAX(NTEST,IPRCC)
*
      LENGTH = 0
      LENGTH2 = 0
      MX_ST_TSOSO = 0
      MX_ST_TSOSO_BLK = 0
      MX_TBLK = 0
      MX_SBSTR = 0
      MX_TBLK_AS = 0
      N1ELINT = 0
*
      DO ITSS_TP = 1, NTSOSO_TP
!#if defined LUCI_DEBUG
!      IF(NTEST.GE.100) WRITE(6,*) ' ITSS_TP = ', ITSS_TP 
!      WRITE(6,*) ' ITSS_TP = ', ITSS_TP 
!#endif
*. Occupation to group translation 
       CALL OCC_TO_GRP(ITSOSO_TP(1+0*NGAS,ITSS_TP),ICA_GRP,1)
       CALL OCC_TO_GRP(ITSOSO_TP(1+1*NGAS,ITSS_TP),ICB_GRP,1)
       CALL OCC_TO_GRP(ITSOSO_TP(1+2*NGAS,ITSS_TP),IAA_GRP,1)
       CALL OCC_TO_GRP(ITSOSO_TP(1+3*NGAS,ITSS_TP),IAB_GRP,1)
*
#if defined LUCI_DEBUG
       if (NTEST.ge.50) then
         write(6,*) ' Output from OCC_TO_GRP : '
         write(6,*) ' ICA_GRP : ',(ICA_GRP(I),I=1,NGAS,1)
         write(6,*) ' ICB_GRP : ',(ICB_GRP(I),I=1,NGAS,1)
         write(6,*) ' IAA_GRP : ',(IAA_GRP(I),I=1,NGAS,1)
         write(6,*) ' IAB_GRP : ',(IAB_GRP(I),I=1,NGAS,1)
       end if
#endif
*
       NEL_CA = IELSUM(ITSOSO_TP(1+0*NGAS,ITSS_TP),NGAS)
       NEL_CB = IELSUM(ITSOSO_TP(1+1*NGAS,ITSS_TP),NGAS)
       NEL_AA = IELSUM(ITSOSO_TP(1+2*NGAS,ITSS_TP),NGAS)
       NEL_AB = IELSUM(ITSOSO_TP(1+3*NGAS,ITSS_TP),NGAS)
*
       LEN_SCR8 = LENGTH + 1
       ITSS_TP_I8 = ITSS_TP
       IBTSOSO_TP(ITSS_TP_I8) = LEN_SCR8
       DO I_CR_SM = 1, NSMST
*. symmetry of annihilation strings
!       print *, 'I_CR_SM',I_CR_SM
        I_AN_SM = IDBGMULT(ISYM,INVELM(I_CR_SM))
*. symmetry of creation strings corresponding to annihilation strings ...
        I_AN_SM = IADJSYM(I_AN_SM)
!       print *, 'I_AN_SM',I_AN_SM
        DO I_CR_AL_SM = 1, NSMST
          DO II_AN_AL_SM = 1, NSMST
             I_AN_AL_SM = IADJSYM(II_AN_AL_SM)
*
             I_CR_BE_SM = IDBGMULT(INVELM(I_CR_AL_SM),I_CR_SM)
             I_AN_BE_SM = IDBGMULT(INVELM(I_AN_AL_SM),I_AN_SM)
*
             CALL NST_SPGRP_DBG(NGAS,ICA_GRP,I_CR_AL_SM,NSMST,
     &                          LEN_CA,NDIST_CA,1)
             CALL NST_SPGRP_DBG(NGAS,ICB_GRP,I_CR_BE_SM,NSMST,
     &                          LEN_CB,NDIST_CB,2)
             CALL NST_SPGRP_DBG(NGAS,IAA_GRP,I_AN_AL_SM,NSMST,
     &                          LEN_AA,NDIST_AA,1)
             CALL NST_SPGRP_DBG(NGAS,IAB_GRP,I_AN_BE_SM,NSMST,
     &                          LEN_AB,NDIST_AB,2)
*
#if defined LUCI_DEBUG
             IF(NTEST.GE.1000) THEN
              WRITE(6,'(A,4I5)') ' sym of CA CB AA AB',
     &         I_CR_AL_SM, I_CR_BE_SM, I_AN_AL_SM, I_AN_BE_SM
               WRITE(6,'(A,4I5)') ' LEN_CA, LEN_CB, LEN_AA, LEN_AB ',
     &                      LEN_CA, LEN_CB, LEN_AA, LEN_AB
              END IF
#endif
*
             LEN_SCR3 = LEN_CA
             LEN_SCR4 = LEN_CB
             LEN_SCR5 = LEN_AA
             LEN_SCR6 = LEN_AB
C
             LEN_SCR1 = LEN_SCR3 * LEN_SCR4 
             LEN_SCR2 = LEN_SCR5 * LEN_SCR6
             LEN_SCR7 = LEN_SCR1 * LEN_SCR2
             LENGTH  = LENGTH  + LEN_SCR7
             LENGTH2 = LENGTH2 + LEN_SCR7
C            count one-electron integrals
             IF((ITSS_TP.lt.IFTTWO).or.(ITSS_TP.ge.IFSFLT1
     &           .and.ITSS_TP.le.ILSFLT1)) N1ELINT = N1ELINT + LEN_SCR7
#if defined LUCI_DEBUG
             if (NTEST.ge.2000) then
               if(LEN_SCR7.gt.0)then
                 write(6,*) 'LENGTH ', LEN_SCR1 * LEN_SCR2
                 print *, ' tcc_dim...: I_CR_BE_SM ',I_CR_BE_SM
                 print *, ' tcc_dim...: I_CR_AL_SM ',I_CR_AL_SM
                 print *, ' tcc_dim...: I_AN_BE_SM ',I_AN_BE_SM
                 print *, ' tcc_dim...: I_AN_AL_SM ',I_AN_AL_SM
               end if
             end if
#endif
*
             MX_ST_TSOSO = 
     &       MAX(MX_ST_TSOSO,LEN_CA,LEN_CB,LEN_AA,LEN_AB)
             MX_ST_TSOSO_BLK = 
     &       MAX(MX_ST_TSOSO_BLK,LEN_CA*NEL_CA,LEN_CB*NEL_CB,
     &                           LEN_AA*NEL_CA,LEN_AB*NEL_CB)
             MX_TBLK  = MAX(MX_TBLK, LEN_SCR7)
          END DO
        END DO
       END DO
      MX_TBLK_AS = MAX( MX_TBLK_AS, LENGTH2 )
      END DO
C
      I_TOT_DIM_T = LENGTH
C
C     determine number of one-electron and two-electron integrals
      NINT_2E    = LENGTH - N1ELINT
      N2ELINT_I8 = LENGTH - N1ELINT
*
#if defined LUCI_DEBUG
      NTEST = 5
      IF(NTEST.GE.3) THEN
        WRITE(6,*) ' Number of 1e-integrals : ', N1ELINT
        WRITE(6,*) ' Number of 2e-integrals : ', NINT_2E
        WRITE(6,*) ' total number of integrals: ', NINT_2E + N1ELINT
        WRITE(6,*) ' Largest symmetry block of T ', MX_TBLK
        WRITE(6,*) ' Largest block of T ', MX_TBLK_AS
      END IF
*
      IF(NTEST.GE.5) THEN
        WRITE(6,*) 
     &  ' Largest number of strings of given sym and type ',
     &               MX_ST_TSOSO
        WRITE(6,*) 
     & ' Largest block of strings of given sym and type ',
     &               MX_ST_TSOSO_BLK
        WRITE(6,*) ' Offset for each block '
         DO II = 1, NTSOSO_TP
           WRITE(6,*) 'IBTSOSO_TP(',II,') is ',IBTSOSO_TP(II)
         END DO
      END IF
#endif
      END 
!***********************************************************************
      SUBROUTINE IDIM_TCC_DBG_opt(ITSOSO_TP,NTSOSO_TP,ISYM,
     &                            MX_ST_TSOSO,MX_ST_TSOSO_BLK,MX_TBLK,
     &                            MX_TBLK_AS,IFTTWO,
     &                            IFSFLT1,ILSFLT1,N1ELINT,NGAS,
     &                            IPRCC,
     &                            ica_grp,icb_grp,iaa_grp,iab_grp,
     &                            ndist_ca,ndist_cb,ndist_aa,ndist_ab)
!
! Dimension of T operators in spin-orbital basis
!
! Largest number of strings of given sym in T(ICA,ICB,IAA,IAB)
! i.e. largest block of ICA, ICB,IAA,IAB of given sym 
!
! Size of block required to hold above blocks
!
! Jeppe Olsen, Summer of 99
!
! Double group version
! -------------------------------------------------------------------
! new loop structure which should improve the performance but does it
! still work then?
! S. Knecht - Dec 2010
! -------------------------------------------------------------------
 
      use symmetry_setup_krci
#include "implicit.inc"
*. General input
#include "mxpdim.inc"
#include "integrals_off.inc"
*. Specific input
      INTEGER ITSOSO_TP(NGAS,4,NTSOSO_TP)
*. Local scratch 
      integer, intent(inout) :: ica_grp(ngas), icb_grp(ngas)
      integer, intent(inout) :: iaa_grp(ngas), iab_grp(ngas)
      integer, intent(inout) :: ndist_ca(*), ndist_cb(*) 
      integer, intent(inout) :: ndist_aa(*), ndist_ab(*)

*.Output : offset for each type
      INTEGER*8 LEN_SCR3, LEN_SCR4, LEN_SCR5, LEN_SCR6 
      INTEGER*8 LEN_SCR7, LEN_SCR8
      INTEGER*8 LENGTH, N2ELINT_I8
      INTEGER*8 MX_TBLK, MX_TBLK_AS

      LEN_SCR3   = 0
      LEN_SCR4   = 0
      LEN_SCR5   = 0
      LEN_SCR6   = 0
      LEN_SCR7   = 0
      LEN_SCR8   = 0
*
      NTEST = 0000
      NTEST = MAX(NTEST,IPRCC)

!     initialize
      LENGTH          = 0
      MX_ST_TSOSO     = 0
      MX_ST_TSOSO_BLK = 0
      MX_TBLK         = 0
      MX_TBLK_AS      = 0
      N1ELINT         = 0
*
      DO ITSS_TP = 1, NTSOSO_TP

        IBTSOSO_TP(ITSS_TP) = LENGTH + 1
!       print *, 'new offset for type ITSS_TP',LENGTH+1, ITSS_TP

*. Occupation to group translation 
        CALL OCC_TO_GRP(ITSOSO_TP(1,1,ITSS_TP),ICA_GRP,1)
        CALL OCC_TO_GRP(ITSOSO_TP(1,2,ITSS_TP),ICB_GRP,1)
        CALL OCC_TO_GRP(ITSOSO_TP(1,3,ITSS_TP),IAA_GRP,1)
        CALL OCC_TO_GRP(ITSOSO_TP(1,4,ITSS_TP),IAB_GRP,1)
*
!#define LUCI_DEBUG
#ifdef LUCI_DEBUG
        write(6,*) ' Output from OCC_TO_GRP (type): ',ITSS_TP
        write(6,*) ' ICA_GRP : ',(ICA_GRP(I),I=1,NGAS,1)
        write(6,*) ' ICB_GRP : ',(ICB_GRP(I),I=1,NGAS,1)
        write(6,*) ' IAA_GRP : ',(IAA_GRP(I),I=1,NGAS,1)
        write(6,*) ' IAB_GRP : ',(IAB_GRP(I),I=1,NGAS,1)
#endif
!#undef LUCI_DEBUG
*
        NEL_CA = IELSUM(ITSOSO_TP(1,1,ITSS_TP),NGAS)
        NEL_CB = IELSUM(ITSOSO_TP(1,2,ITSS_TP),NGAS)
        NEL_AA = IELSUM(ITSOSO_TP(1,3,ITSS_TP),NGAS)
        NEL_AB = IELSUM(ITSOSO_TP(1,4,ITSS_TP),NGAS)
!      
!       set loop limits according to an even/odd number of e:
        if(mod(NEL_CA+NEL_CB,2) .ne. 0)then
          ISMCSTA  = 1 + NIRR_DG/2
          ISMCEND  =     NIRR_DG
        else
          ISMCSTA  = 1
          ISMCEND  = NIRR_DG/2
        end if
        if(mod(NEL_CA,2) .ne. 0)then
          ISMCASTA = 1 + NIRR_DG/2
          ISMCAEND =     NIRR_DG
        else
          ISMCASTA = 1
          ISMCAEND = NIRR_DG/2
        end if

#ifdef LUCI_DEBUG
        print *, 'C  symmetry loop: ',ISMCSTA,ISMCEND
        print *, 'CA symmetry loop: ',ISMCASTA,ISMCAEND
#endif

        DO 101 I_CR_AL_SM = ISMCASTA, ISMCAEND

          call getstr2_totsm_spgp_rel(1,ICA_GRP,NGAS,I_CR_AL_SM,
     &                                NEL_CA,LEN_CA,NDIST_CA)
          if(LEN_CA.le.0) goto 101
          DO 202 I_AN_AL_SM = 1, NIRR_DG

            call getstr2_totsm_spgp_rel(1,IAA_GRP,NGAS,I_AN_AL_SM,
     &                                  NEL_AA,LEN_AA,NDIST_AA)
            if(LEN_AA.le.0) goto 202
            DO 303 I_CR_SM = ISMCSTA, ISMCEND

!             print *, ' next I_CR_SM ==>',I_CR_SM
*
              call getstr2_totsm_spgp_rel(2,ICB_GRP,NGAS,
     &             IDBGMULT(I_CR_SM,INVELM(I_CR_AL_SM)),
     &                                    NEL_CB,LEN_CB,
     &                                    NDIST_CB)
              call getstr2_totsm_spgp_rel(2,IAB_GRP,NGAS,
     &             IDBGMULT(IDBGMULT(I_CR_SM,IADJSYM(ISYM)),
     &                      INVELM(I_AN_AL_SM)),
     &                                    NEL_AB,LEN_AB,
     &                                    NDIST_AB)
 
              LEN_SCR3 = LEN_CA
              LEN_SCR4 = LEN_CB
              LEN_SCR5 = LEN_AA
              LEN_SCR6 = LEN_AB
C
              LEN_SCR7 = LEN_SCR3 * LEN_SCR4 * LEN_SCR5 * LEN_SCR6
              LENGTH   = LENGTH  + LEN_SCR7
C             count one-electron integrals
              IF((ITSS_TP.lt.IFTTWO).or.
     &           (ITSS_TP.ge.IFSFLT1.and.ITSS_TP.le.ILSFLT1))then
                N1ELINT = N1ELINT + LEN_SCR7
              end if
#ifdef LUCI_DEBUG
              if(LEN_SCR7.gt.0)then
                print *, ' tcc_dim...: I_CR_SM    ',I_CR_SM
              end if
#endif
*
              MX_ST_TSOSO = 
     &        MAX(MX_ST_TSOSO,LEN_CA,LEN_CB,LEN_AA,LEN_AB)
              MX_ST_TSOSO_BLK = 
     &        MAX(MX_ST_TSOSO_BLK,LEN_CA*NEL_CA,LEN_CB*NEL_CB,
     &                            LEN_AA*NEL_CA,LEN_AB*NEL_CB)
              MX_TBLK  = MAX(MX_TBLK, LEN_SCR7)
 303        continue
 202      continue ! loop over all II_AN_AL_SM
 101    continue ! loop over all II_CR_AL_SM

        MX_TBLK_AS = MAX( MX_TBLK_AS, LENGTH )
      end do ! loop over NTSOSO_TP
C
      I_TOT_DIM_T = LENGTH
!
!     determine number of two-electron integrals
      NINT_2E    = LENGTH - N1ELINT
      N2ELINT_I8 = NINT_2E
*
#ifdef LUCI_DEBUG
      IF(NTEST.GE.3) THEN
        NTEST = 5
        WRITE(6,*) ' Number of 1e-integrals     :', N1ELINT
        WRITE(6,*) ' Number of 2e-integrals     :', NINT_2E
        WRITE(6,*) ' total number of integrals  :', NINT_2E + N1ELINT
        WRITE(6,*) ' Largest symmetry block of T:', MX_TBLK
        WRITE(6,*) ' Largest block of T         :', MX_TBLK_AS
      END IF
*
      IF(NTEST.GE.5) THEN
        WRITE(6,*) 
     &  ' Largest number of strings of given sym and type ',
     &               MX_ST_TSOSO
        WRITE(6,*) 
     & ' Largest block of strings of given sym and type ',
     &               MX_ST_TSOSO_BLK
        WRITE(6,*) ' Offset for each block '
         DO II = 1, NTSOSO_TP
           WRITE(6,*) 'IBTSOSO_TP(',II,') is ',IBTSOSO_TP(II)
         END DO
      END IF
#endif

      END 
***********************************************************************

      FUNCTION ITDIANUM(ICA,ICB,IAA,IAB,NC,NA)
*
* Find adress of element T(ICA,ICB,IAA,IAB) in diagonal 
* block
* It is assumed that (ICA,IAA) .ge. (ICB,IAB) has been checked outside
*
* Jeppe Olsen, July 2000, HNIE
*
#include "implicit.inc"
*. T(1,1,Iab,Iab)
      I11IABIAB = ((IAB-1)*NA - IAB*(IAB-1)/2)*NC*NC+
     &             (IAB-1)*NC*(NC+1)/2
*. T(1,1,Iaa,Iab)
      IF(IAA.GT.IAB) THEN
       I11IAAIAB =  I11IABIAB + NC*(NC+1)/2 + (IAA-IAB-1)*NC*NC
      ELSE
       I11IAAIAB =  I11IABIAB 
      END IF
*. T(Ica,Icb,Iaa,Iab)
      IF(IAA.GT.IAB) THEN
       IADR = I11IAAIAB  + (ICB-1)*NC + ICA
      ELSE
       IADR = I11IAAIAB  + (ICB-1)*NC + ICA - ICB*(ICB-1)/2
      END IF
*
      ITDIANUM = IADR
*
      NTEST = 000
#if defined LUCI_DEBUG
      IF(NTEST.GE.100) THEN
        WRITE(6,*) ' Address of diagonal T-element : '
        WRITE(6,*) ' ICA, ICB, IAA, IAB, NC,NA, IADR = ',
     &               ICA, ICB, IAA, IAB, NC,NA, IADR
      END IF
#endif
*
      END
***********************************************************************

      SUBROUTINE LEN_GENOP_STR_MAP(NGENOP,IGENOP,NSPGRP,ISPGRP,NOBPT,
     &                             NGAS,MAXLEN)
*
* A set of general operators, IGENOP, and a set of supergroups, ISPGRP, 
* are defined. Obtain max.length of mappings from resolution strings 
* to istrings. 
*
* The resolution strings KSTR are assumed to be inserted between the 
* creation and annihilation operators 
*
*   <ISPGRP!ICREA!KSTR> <KSTR!IANNI!ISPGRP'>
* So the mappings from KSTR to ISTR are always creation mappings 
*
* Jeppe Olsen, July 2000 ( At summerschool, HNIE)
*
#include "implicit.inc"
#include "ipoist8.inc"
#include "mxpdim.inc"
*
*. Specific input
      INTEGER IGENOP(2*NGAS,*), ISPGRP(MXPNGAS,*), NOBPT(NGAS)
*. Local scratch
      INTEGER KSPGRP(MXPNGAS), IGENOP_EXP(MXPLCCOP)
*
      MAXLEN = 0
      IONE = 1
      IMONE = -1
      DO ICA = 1, 2
C?     print*,'ICA ',ICA
      DO JSPGRP = 1, NSPGRP
C?     print*,'JSPGRP ',JSPGRP
*. ICREA/IANNI(dag)*!KSTR> = !ISTR>
       DO JGENOP = 1, NGENOP
C?      print*,'JGENOP ',JGENOP
*. Occupation of KSPGRP
         IF(ICA.EQ.1) THEN
           CALL IVCSUM(KSPGRP,ISPGRP(1,JSPGRP),IGENOP(1,JGENOP),
     &                 IONE,IMONE,NGAS)
         ELSE
           CALL IVCSUM(KSPGRP,ISPGRP(1,JSPGRP),IGENOP(NGAS+1,JGENOP),
     &                 IONE,IMONE,NGAS)
         END IF
*. Is KSPGRP a correct supergroup( all occ larger than zero) 
         I_AM_OKAY = 1
         DO IGAS = 1, NGAS
           IF(KSPGRP(IGAS).LT.0) I_AM_OKAY = 0
         END DO
         IF(I_AM_OKAY.EQ.1) THEN
*. IGENOP in expanded form
C  REF_OP(IOPGAS,IOP,NOP,NGAS,IWAY)
          LEN = 0
          IF(ICA.EQ.1) THEN
            CALL REF_OP(IGENOP(1,JGENOP),IGENOP_EXP,NOP,
     &                  NGAS,1,MXPLCCOP)
          ELSE
            CALL REF_OP(IGENOP(NGAS+1,JGENOP),IGENOP_EXP,NOP,
     &                  NGAS,1,MXPLCCOP)
          END IF
          DO IOP = 1, NOP
C?         print*,'IOP ',IOP
            IOPTP = IGENOP_EXP(IOP)
*. Number of Kstrings
C                  NST_FOR_OCC(NELEC_PER_GAS,NORB_PER_GAS,NGAS)
            NSTR = NST_FOR_OCC(KSPGRP,NOBPT,NGAS)
            NORB = NOBPT(IOPTP)
            LEN = LEN + NSTR*NORB 
!      if(LEN.gt.100000000) print*,'NSTR,NORB ',NSTR,NORB
*. Update KSPGRP 
            KSPGRP(IOPTP) = KSPGRP(IOPTP) + 1
          END DO
          MAXLEN = MAX(MAXLEN,LEN)
         END IF
       END DO
      END DO
      END DO
*
#if defined LUCI_DEBUG
      WRITE(6,*) ' Max length of KSTR => ISTR map = ', MAXLEN
#endif
*
      RETURN
      END
***********************************************************************

      FUNCTION LEN_TT_BLOCK(ISM,NIA,NIB)
*
* Length of TT block with total sym ISM
*
* Jeppe Olsen, May 99 in Aarhus
* Modified for relativistic case, Timo Fleig, June 2001
*
      use symmetry_setup_krci
#include "implicit.inc"
*. Specific input
      INTEGER NIA(*), NIB(*)
*
      LEN = 0
      DO IASM = 1, NSMST
        IBSM = IDBGMULT(INVELM(IASM),ISM)
        LEN = LEN + NIA(IASM)*NIB(IBSM)
      END DO
*
      LEN_TT_BLOCK = LEN
*
#if defined LUCI_DEBUG
      WRITE(6,*) ' LEN_TT_BLOCK = ', LEN_TT_BLOCK 
#endif
*
      END
***********************************************************************

      FUNCTION LEN_TT_BLOCK_PAR(ISM,NIA,NIB,INCLUDE_LIST,IOFF1,
     &                          IVERS)
*
* Length of TT block with total sym ISM
*
* Jeppe Olsen, May 99 in Aarhus
* Modified for relativistic case, Timo Fleig, June 2001
* Modified for parallel runs, Stefan Knecht, May 2007
*
* IOFF1: absolute address value
* IVERS: 0: c-block version; 1: s-block version
*
      use symmetry_setup_krci
#include "implicit.inc"
*. Specific input
      INTEGER NIA(*), NIB(*), IOFF1, IOFF2, INCLUDE_LIST(*)
*. General input
#include "parluci.h"
*
      LEN   = 0
      IOFF2 = 0
      IOFF2 = IOFF1
CSK      WRITE(LUWRT,*) ' IOFF1 and IOFF2 are now',IOFF1,IOFF2
CSK      WRITE(LUWRT,*) ' IVERS is ',IVERS
CSK      WRITE(LUWRT,*) ' NSMST is ',NSMST
      
      IF( IVERS .eq. 0 ) THEN
        DO IASM = 1, NSMST
          IF( INCLUDE_LIST(IOFF2) .eq. 0 ) GOTO 100
          IBSM = IDBGMULT(INVELM(IASM),ISM)
          LEN = LEN + NIA(IASM)*NIB(IBSM)
 100      CONTINUE
          IOFF2 = IOFF2 + 1
        END DO
      ELSE
        DO IASM = 1, NSMST
          IF( INCLUDE_LIST(IOFF2) .ne. MYPROC ) GOTO 200
          IBSM = IDBGMULT(INVELM(IASM),ISM)
CSK          WRITE(LUWRT,*) ' IASM, IBSM',IASM,IBSM
          LEN = LEN + NIA(IASM)*NIB(IBSM)
 200      CONTINUE
          IOFF2 = IOFF2 + 1
        END DO
      END IF
*
      LEN_TT_BLOCK_PAR = LEN
*
      NTEST = 000
#if defined LUCI_DEBUG
      IF(NTEST.GE.100) THEN
        WRITE(LUWRT,*) ' LEN_TT_BLOCK_PAR = ', LEN_TT_BLOCK_PAR
      END IF
#endif
*
      END
***********************************************************************

      SUBROUTINE MAP_EXSTR(IOP,NOP,IREFOC,IX,SSX,NK,IBX,ISMDST,IAB)

* Information for mapping |Kstr> = IOP |Irefoc>
*
* Mapping for each creation/annihilation operator is given
*
*     Jeppe Olsen, Summer of 99
*     Timo Fleig, summer of 2001, mod. for rel. case
*                 IAB added for alpha (unbarred) and beta (barred)
*                 ISMDST added Aug. 2003
*
      use mospinor_info
      use symmetry_setup_krci
#include "implicit.inc"
#include "ipoist8.inc"
#include "mxpdim.inc"
#include "cgas.inc"
#include "ctcc.inc"
#include "parluci.h"
*. Input
      INTEGER IOP(NGAS),IREFOC(NGAS)
*. Output
      INTEGER IX(*),IBX(MXNDGIRR,MXNDGIRR,NOP)
      INTEGER NK(MXNDGIRR,NOP)
      DIMENSION SSX(*)
*. Local Scratch
      INTEGER KOC(MXPNGAS),KGRP(MXPNGAS)
      INTEGER ISMDST(*)
      integer, allocatable :: NOBPTSx(:,:)
*. IBX(ISM,JSM,JOP) : Start of map in JX for orbitals of symmetry ISM,
*.                    input strings of symmetry JSM for operator JOP
*. Notice at each level N the mapping is from !K(N)> to !K(N-1)> 
*  where !K(0)> is input type and !K(NOP)> is output type
*
C     MAP_EXSTR(IOP,NOP,IREFOC,IX,SSX,NK,IB,SCLFAC)
*
!#define LUCI_DEBUG
#ifdef LUCI_DEBUG
      WRITE(6,*) ' MAP_EXSTR speaking' 
      WRITE(6,*) ' =================='
      WRITE(6,*) ' Reference occupation '
      CALL IWRTMA(IREFOC,1,NGAS,1,NGAS) 
      WRITE(6,*) ' NOP = ', NOP
      WRITE(6,*) ' Operator string'
      CALL IWRTMA(IOP,1,NOP,1,NOP)
#endif
!#undef LUCI_DEBUG
*
      CALL ICOPY(NGAS,IREFOC,1,KOC,1)
      CALL OCC_TO_GRP(KOC,KGRP,1)
      call izero(NK,MXNDGIRR*NOP)
      call izero(IBX,MXNDGIRR*MXNDGIRR*NOP)

!     allocate scratch space for internal gas/# of spinor 2d-array
      allocate(NOBPTSx(max_num_gaspaces,nsmob/2))
      if(iab.eq.1)then
        do j = 1, nsmob/2
          do i = 1, max_num_gaspaces
            NOBPTSx(i,j) = NOBPTS(i,j+nsmob/2)
          end do
        end do
      else ! barred spinors
        do j = 1, nsmob/2
          do i = 1, max_num_gaspaces
            NOBPTSx(i,j) = NOBPTS2(i,j+nsmob/2)
          end do
        end do
      end if

      IOFF = 1 ! initialize offset

      DO JOP = NOP,1,-1

        JGAS = IOP(JOP)
COLD
CTF Depending on the evaluation "direction" of the coupling coefficient,
CTF the symmetry handling changes: If |K> is on the right, the inverse
CTF element is correct (INVELM(JSMOB)), if |J> is on the right, the
CTF element is NOT inversed!
CTF
!
!       stefan: in relativistic runs this loop might be restricted to
!       spinor symmetries -->  NSMOB/2 + 1, NSMOB
!       for spinfree LUCIAREL runs this needs to be considered!
!       sk - march 2011
!       DO JSMOB = 1, NSMOB
!       print *, 'warning: restricted loop in map_ex...'
        DO JSMOB = NSMOB/2 + 1, NSMOB
!         loop restriction yields approx. 50% speed-up 
!         for linsym where NSMOB/2 == 64 and NSMST == 128
!         stefan - april 2011
!         if(NOBPTSx(JGAS,JSMOB).gt.0)then
          if(NOBPTSx(JGAS,JSMOB-NSMOB/2).gt.0)then 
            DO JSMSPGP = 1, NSMST

!             print *, 'JSMOB,JGAS,NGAS',JSMOB,JGAS,NGAS
              CALL ADAST_GAS_REL(JSMOB,JGAS,NGAS,KGRP,JSMSPGP,
     &                           IX(IOFF),xdummy,NKSTR,IEND,
     &                           IFRST,KFRST,KACT,1.0d0,2,ISMDST,IAB)
C             ADAST_GAS_REL(IOBSM,IOBTP,NIGRP,IGRP,ISPGPSM,
C    &                      I1,XI1S,NKSTR,IEND,
C    &                      IFRST,KFRST,KACT,SCLFAC,IAC,ISMDST,IAB)

!             Symmmetry of |Kgrp>    = a(JSMOB)  |JSMSPGP>
!             =            |JSMSPGP> = a+(JSMOB) |Kgrp>
!             -----------------------------------------------------
              KSMSPGP                = IDBGMULT(INVELM(JSMOB),JSMSPGP)
              IBX(JSMOB,KSMSPGP,JOP) = IOFF
              NK(KSMSPGP,JOP)        = NKSTR

!             IOFF = IOFF + NOBPTSx(JGAS,JSMOB)*NKSTR
              IOFF = IOFF + NOBPTSx(JGAS,JSMOB-NSMOB/2)*NKSTR
!      print '(a,5i4)', 'IOFF, JSMOB, NKSTR, JSMSPGP, IX(IOFF)',
!    &                   IOFF, JSMOB, NKSTR, JSMSPGP, IX(IOFF)
              IF(IOFF-1.GT. MAXLEN_I1) THEN
                WRITE(6,*) ' MAP... MAXLEN_I1 too small '
                WRITE(6,*) ' IOFF and MAXLEN_I1 = ', IOFF, MAXLEN_I1
                call quit('error in MAP_EXSTR: MAXLEN_I1 too small.')
              end if
            end do ! loop over string symmetries ==> JSMSPGP
          else
            do i = 1, nsmst
              ibx(jsmob,i,jop) = ioff
            end do
          end if
        end do ! loop over spinor symmetries ==> jsmob

!       Updated Kgroup  
!       Info on !K(JOP)> 
        KOC(JGAS) = KOC(JGAS) - 1
        CALL OCC_TO_GRP(KOC,KGRP,1)
 
      end do ! inverse loop over operators JOP 

!#define LUCI_DEBUG
#ifdef LUCI_DEBUG
      WRITE(6,*) ' Output from MAP_EXSTR '
      WRITE(6,*) ' Mappings from a+/a !K(J)> to !K(J-1)> '
*
      ioff2 = 1
      DO JOP = 1, NOP
         WRITE(6,*) 
     &   ' Operator ', JOP, ' is creation     operator of type',
     &    2
!      DO JSM = 1,NSMOB
       DO JSM = NSMOB/2+1,NSMOB
         DO KNSM = NSMST, NSMST
           KSMSPGP = IDBGMULT(INVELM(JSM),KNSM)
           WRITE(6,*) ' Sym of operator and !K(N)> ',
     &                  JSM, KSMSPGP 
           LK = NK(KSMSPGP,JOP)
           if(LK.gt.0)then
             WRITE(6,*) ' Number of strings !K(N)> ',LK
             LJ = NOBPTSx(IOP(JOP),JSM-NSMOB/2)
             DO JJ = 1, LJ
              WRITE(6,*) ' Info for orbital ', JJ
              WRITE(6,*) ' Excited strings and sign '
              IOFF2 = IOFF2 + (JJ-1)*LK
              print '(a,5i4)', ' JOP,JSM KSMSPGP LK, offset ',
     &                           JOP,JSM,KSMSPGP,LK,IOFF2
              CALL IWRTMA(IX(IOFF2),1,LK,1,LK)        
             END DO
           end if
         END DO
       END DO
      END DO
#endif
!#undef LUCI_DEBUG

!     release scratch memory
      deallocate(NOBPTSx)
*
      END 
***********************************************************************

      integer*8 function nelm_cc(ITP,NXTP,NT_SCRATCH)
* Find number of elements in a given excitation class.
*
*
#include "implicit.inc"
#include "mxpdim.inc"
#include "integrals_off.inc"
*
      INTEGER*8 NT_SCRATCH
*
      if (ITP.lt.NXTP) then
        NELM_CC = IBTSOSO_TP(ITP+1) - IBTSOSO_TP(ITP)
      else if (ITP.eq.NXTP) then
        NELM_CC = NT_SCRATCH - IBTSOSO_TP(ITP) + 1
      else
        write(6,*) 'Requested excitation type ',ITP
        write(6,*) 'exceeds total number of types ',NXTP
        CALL QUIT('QUITTING in integer*8 function nelm_cc.')
      end if
*
      end
***********************************************************************

      FUNCTION NST_FOR_OCC(NELEC_PER_GAS,NORB_PER_GAS,NGAS)
*
* A supergroup is defined by NELEC_PER_GAS. Find the 
* Total number of strings of this supergroup
*
* Jeppe Olsen, July 2000 (HNIE)
*
#include "implicit.inc"
*
      INTEGER NELEC_PER_GAS(*),NORB_PER_GAS(*)
*
      NSTR = 1
      DO IGAS = 1, NGAS
       IF(NELEC_PER_GAS(IGAS).NE.0) THEN
        NSTR = NSTR*IBION(NORB_PER_GAS(IGAS),NELEC_PER_GAS(IGAS))
       END IF
      END DO
*
      NST_FOR_OCC = NSTR
*
      NTEST = 000
#if defined LUCI_DEBUG
      IF(NTEST.GE.100) THEN
        WRITE(6,*) ' Number of electrons and orbitals per gasspace '
        CALL IWRTMA(NELEC_PER_GAS,1,NGAS,1,NGAS)
        CALL IWRTMA(NORB_PER_GAS,1,NGAS,1,NGAS)
        WRITE(6,*) ' Number of strings = ', NSTR
      END IF
#endif
*
      END
***********************************************************************

      SUBROUTINE OCC_TO_GRP(IOCC,IGRP,IWAY)
*. Translate between occupation and group labels of supergroup
*
* IWAY = 1 => OCC to group
*      = 2 => Group to occ
*
* Number of strings in supergroup with given symmetry and number of 
* electrons in each space
*
* Jeppe Olsen, March 1999
*
#include "implicit.inc"
#include "ipoist8.inc"
*. General input
#include "mxpdim.inc"
#include "cgas.inc"
#include "gasstr.inc"
*. Local scratch
C     INTEGER JGRP(MXPNGAS)
*. Specific input/output
      INTEGER IOCC(NGAS),IGRP(NGAS)
*
*
      IF(IWAY.EQ.1) THEN 
*. Occupation => Group number 
        DO IOBTP = 1, NGAS
          JJGRP = 0
          DO KGRP = IBGPSTR(IOBTP), IBGPSTR(IOBTP) + NGPSTR(IOBTP)-1
            IF(NELFGP(KGRP).EQ.IOCC(IOBTP)) JJGRP = KGRP
          END DO
          IGRP(IOBTP) = JJGRP
*
#if defined LUCI_DEBUG
          NTEST = 10
          IF(NTEST.ge.10) THEN
           WRITE(6,*) ' Group not included in list '
           WRITE(6,*) ' Input occupations : '
           CALL IWRTMA(IOCC,1,NGAS,1,NGAS)
           write(6,*) 'Current orbital type :',IOBTP
           write(6,*) 'IBGPSTR array :'
           call iwrtma(IBGPSTR,1,NGAS,1,NGAS)
           write(6,*) 'NGPSTR array :'
           call iwrtma(NGPSTR,1,NGAS,1,NGAS)
           write(6,*) 'Group range ',
     &                 IBGPSTR(IOBTP), IBGPSTR(IOBTP) + NGPSTR(IOBTP)-1
           write(6,*) 'List of electron occupations: '
           do K=IBGPSTR(IOBTP), IBGPSTR(IOBTP) + NGPSTR(IOBTP)-1
             write(6,*) 'NELFGP(',K,') =', NELFGP(K)
           end do
          END IF
#endif
          if (JJGRP.eq.0) 
     &       CALL QUIT(' *** ERROR in OCC_TO_GRP: Group not included 
     &                   in list ***')
        END DO
*
      ELSE
*. Group => Occupation 
        DO IOBTP = 1, NGAS
          IOCC(IOBTP) = NELFGP(IGRP(IOBTP))
        END DO
      END IF
*
#if defined LUCI_DEBUG
      WRITE(6,*) ' Occupation and corresponding group array '
      CALL IWRTMA(IOCC,1,NGAS,1,NGAS)
      CALL IWRTMA(IGRP,1,NGAS,1,NGAS) 
#endif

*
      END 
***********************************************************************

      SUBROUTINE REF_OP(IOPGAS,IOP,NOP,NGAS,IWAY,MXNOP)
* An operatorstring may be specifed as
*
* IOPGAS : Number of operators per GASspace
* IOP    : GASpace of each operator
*
* Transform between these two form
*
* Iway = 1 : IOPGAS => IOP
* Iway = 2 : IOP    => IOPGAS
*
* Jeppe Olsen, Summer of 99
*
#include "implicit.inc"
*. Input/Output
      INTEGER IOPGAS(NGAS),IOP(MXNOP)
*
      IF(IWAY.EQ.1) THEN
        JOP = 0
        DO JGAS = 1, NGAS
          LJGAS = IOPGAS(JGAS)
          DO JJOP = 1, LJGAS
            JOP = JOP + 1
            IOP(JOP) = JGAS
          END DO
        END DO
        NOP = JOP
        if (NOP.gt.MXNOP) then
          write(6,*) 'NOP too large in REF_OP. NOP =',NOP
          write(6,*) 'Increase MXNOP or find bug !!'
        end if
      ELSE
        DO JGAS = 0, NGAS
          JOP = 0
          DO JJOP = 1, NOP
            IF(IOP(JJOP).EQ.JGAS) JOP = JOP +1 
          END DO
          IOPGAS(JGAS) = JOP
        END DO
      END IF
*
!#define LUCI_DEBUG
#ifdef LUCI_DEBUG
      IF(IWAY.EQ.1) THEN
       WRITE(6,*) ' IOPGAS => IOP '
      ELSE
       WRITE(6,*) ' IOP => IOPGAS '
      END IF
      WRITE(6,*) ' IOPGAS and IOP: dim(ngas), dim(nop)',ngas,nop
      CALL IWRTMA(IOPGAS,1,NGAS,1,NGAS)
      CALL IWRTMA(IOP,1,NOP,1,NOP)
#endif
!#undef LUCI_DEBUG
 
      END
***********************************************************************

      SUBROUTINE SET_HOP_DBG(IHTYPE,NO_TTWO,ISYM_T,IPRNT)
*
*     Construct orbital excitation types for different choices
*     of Hamiltonian operator, double group version
*
*
*     IHTYPE = 1 : Include only Delta MK = 0 terms
*     IHTYPE = 2 : Include Delta MK = 0 for two-electron part
*                  and complete one-electron part
*     IHTYPE = 3 : Include all terms for general relativistic Hamiltonian
*
*     NO_TTWO .gt. 0 : do not include two-electron terms
*
*     added INTEGER*8 adaption: S. Knecht - Nov. 2007
*
      use memory_allocator
      use mospinor_info
#include "implicit.inc"
#include "ipoist8.inc"
*  
#include "dgroup.h"
#include "mxpdim.inc"
#include "wrkspc.inc"
#include "cgas.inc"
#include "cprnt.inc"
C
C         OUTPUT
C
#include "ctcc.inc"
#include "integrals_off.inc"
#include "parluci.h"
C
C     specific input in order to handle large integral arrays
C     even on 32-bit systems
      INTEGER*8 MX_TBLK, MX_TBLK_AS
!     T excitation types
      integer, allocatable :: spobex_temp(:)
!     string groups
      integer, allocatable :: ca_group(:)
      integer, allocatable :: cb_group(:)
      integer, allocatable :: aa_group(:)
      integer, allocatable :: ab_group(:)
!     symmetry distribution of string groups
      integer, allocatable :: ca_symdist(:)
      integer, allocatable :: cb_symdist(:)
      integer, allocatable :: aa_symdist(:)
      integer, allocatable :: ab_symdist(:)
!     define an initial max. number of symmetry distribution of string groups
      integer, parameter   :: max_symdist_string_groups = 500 000
      
C
C     number of spin-orbital excitation operators in H
      call alloc(spobex_temp,4*NGAS)
      IFLAG = 1
      CALL GET_HX_RELA(IFLAG,IHTYPE,NO_TTWO,NOBPT,NHX,
     &                 IFTONE,IFTTWO,ILTTWO,IFSFLT1,ILSFLT1,
     &                 spobex_temp,
     &                 DUMMY,DUMMY,DUMMY,I2DIATP,DUMMY,DUMMY,DUMMY,
     &                 IPRNT)
      NSPOBEX_TP = NHX
C
C     actual spin-orbital excitations
C
C     all spinorbital excitations are by default active
      call memmar(KLSOBEX,4*NGAS*NSPOBEX_TP,'ADDS  ',1,'SPOBEX')
      call memmar(KLIHIND,     4*NSPOBEX_TP,'ADDS  ',1,'IHINDX')
      call memmar(KSIGNNHX,      NSPOBEX_TP,'ADDS  ',2,'SIGNDX')
      call memmar(KLABEXTP,    4*NSPOBEX_TP,'ADDS  ',1,'LABXTP')
      call memmar(KLOP_REO,    4*NSPOBEX_TP,'ADDS  ',1,'OP_REO')
      call memmar(KSIOPREO,      NSPOBEX_TP,'ADDS  ',2,'SIOPRE')
      IFLAG = 0
      CALL GET_HX_RELA(IFLAG,IHTYPE,NO_TTWO,NOBPT,NHX,
     &                 IFTONE,IFTTWO,ILTTWO,IFSFLT1,ILSFLT1,
     &                 spobex_temp,
     &                 WORK(KLSOBEX),WORK(KLIHIND),WORK(KSIGNNHX),
     &                 I2DIATP,WORK(KLABEXTP),WORK(KLOP_REO),
     &                 WORK(KSIOPREO),IPRNT)
      call dealloc(spobex_temp)
C
      IF( NSPOBEX_TP .gt. MXINT_TP ) THEN
        WRITE(LUWRT,*) ' STOP in subroutine SET_HOP_DBG !!!'
        WRITE(LUWRT,*) ' Number of SO-integral types       '
        WRITE(LUWRT,*) ' larger than MXINT_TP: ', NSPOBEX_TP, MXINT_TP
        WRITE(LUWRT,*) ' increase MXINT_TP (mxpdim.inc): to',
     &                   NSPOBEX_TP
        CALL QUIT(' Quitting in subroutine SET_HOP_DBG')
      END IF
C
      call izero8(ibtsoso_tp,nspobex_tp)
C
      call alloc(ca_group,ngas)
      call alloc(cb_group,ngas)
      call alloc(aa_group,ngas)
      call alloc(ab_group,ngas)
      call alloc(ca_symdist,max_symdist_string_groups)
      call alloc(cb_symdist,max_symdist_string_groups)
      call alloc(aa_symdist,max_symdist_string_groups)
      call alloc(ab_symdist,max_symdist_string_groups)

      CALL IDIM_TCC_DBG_opt(WORK(KLSOBEX),NSPOBEX_TP,ISYM_T,MX_ST_TSOSO,
     &                      MX_ST_TSOSO_BLK,MX_TBLK,MX_TBLK_AS,
     &                      IFTTWO,IFSFLT1,ILSFLT1,
     &                      N1ELINT,NGAS,IPRNT,
     &                      ca_group,cb_group,aa_group,ab_group,
     &                      ca_symdist,cb_symdist,aa_symdist,ab_symdist)
      call dealloc(ab_symdist)
      call dealloc(aa_symdist)
      call dealloc(cb_symdist)
      call dealloc(ca_symdist)
      call dealloc(ab_group)
      call dealloc(aa_group)
      call dealloc(cb_group)
      call dealloc(ca_group)
C
C     output -- transfer information to common block
      LEN_T_VEC          = I_TOT_DIM_T
      NALLINT            = LEN_T_VEC * MIN(NZ,2)
      N2ELINT            = NINT_2E
      MX_TBLK_MX         = MX_TBLK
      MX_ST_TSOSO_MX     = MX_ST_TSOSO
      if(MX_ST_TSOSO_BLK.gt.max_symdist_string_groups)then
        print '(a,a,i8)', ' *** error in set_hop_dbg: possible memory'//
     &               ' corruption occured.',
     &               '     raise the parameter'//
     &               ' max_symdist_string_groups to at least ==>',
     &                 MX_ST_TSOSO_BLK
      end if

      MX_ST_TSOSO_BLK_MX = MX_ST_TSOSO_BLK
C
C     print section
      IF(IPRNT .gt. 2000)THEN
        WRITE(LUWRT,'(/A )')'  *** OUTPUT FROM SET_HOP_DBG *** ' 
        WRITE(LUWRT,'( A/)')'      _______________________     ' 
        WRITE(LUWRT,'(A,I20)')'  symmetry of T op. :',ISYM_T
        WRITE(LUWRT,'(A,I20)')'  LEN_T_VEC         :',LEN_T_VEC 
        WRITE(LUWRT,'(A,I20)')'  N2ELINT           :',N2ELINT
        WRITE(LUWRT,'(A,I20)')'  MX_TBLK_MX        :',MX_TBLK_MX
        WRITE(LUWRT,'(A,I20)')'  MX_ST_TSOSO_MX    :',MX_ST_TSOSO_MX
        WRITE(LUWRT,'(A,I20)')'  MX_ST_TSOSO_BLK_MX:',MX_ST_TSOSO_BLK_MX
      END IF
C
      END
***********************************************************************

      SUBROUTINE SIGDEN_CTRL(C,HC,LUC,LUHC,T,T_BUFF,ISIGDEN
#if defined (VAR_MPI2)
     &                   ,LUCLIST,LUHCLIST,IBLOCKL_C,NPARBLOCK_C,
     &                    IGROUPLIST,IPROCLIST,RCCTOS,
     &                    IT_TTPL,IT_TTOL
     &                   ,IBLOCKL_S,NPARBLOCK_S
#endif
     &                   )
*
* Outer routine for sigma vector generation
* in SIGDEN formalism
*
* Modified mv7 routine 
*  Timo Fleig, Halloween 2001  =:-()
*
      use interface_to_mpi
#include "implicit.inc"
* some stuff relevant for parallel runs
#if defined (VAR_MPI2)
      INTEGER   ISTAT(df_MPI_STATUS_SIZE)     
      INTEGER RCCTOS(*)
#endif
#include "infpar.h"
#include "parluci.h"
#include "krciprop.h"
*
#include "ipoist8.inc"
#include "mxpdim.inc"
*
* ======
*.Output
* ======
*
#include "wrkspc.inc"
#include "cstate.inc"
#include "cands.inc"
#include "ctcc.inc"
*
      CALL QENTER('SIGDC')
      IDUM = 0
      CALL MEMMAR(KXDUM,IDUM,'MARK  ',IDUM,'SIGDC ')
C
C     arrays for partitioning of sigma + information for C vector 
C     *_MS2_* arrays are in CSTATE
C
C     DOSIGPROP controls output for NBLK_MS2_C; I_SET_L2BLOCK as ICSM 
C     carrier to z_blkfo_rel. note the minus sign!
      ICSM_SCR = 0
      IF( DOSIGPROP ) ICSM_SCR =  - ICSM
      call z_blkfo_rel(IDC,NMS2VAL,1,ISSM,
     &                 KLSLBT,KLSLEBT,KLSI1BT,KLSIBT,KXX_BLTP,
     &                 NBATCH,NBLOCK,NBLK_MS2,IBLK_MS2,
     &                 NBAT_MS2,IBAT_MS2,NBLK_MS2_C,DOSIGPROP,ICSM_SCR,
#if defined (VAR_MPI2)
     &                 2,NPARBLOCK_S
#else
     &                 0,IDUMMY
#endif
     &                 )
C
#if defined (VAR_MPI2)
C
C     ISCLFAC_GROUP array for c-blocks: 
C     = 0: block is not active
C     > 0: block is active
C
      CALL MEMMAR(KSCALLOC,NUM_BLOCKS2,'ADDL  ',1,'ICLLOC')
C
#endif
C
      call sigden_rel(C,HC,NBATCH,WORK(KLSLBT),WORK(KLSLEBT),
     &                WORK(KLSI1BT),WORK(KLSIBT),LUC,LUHC,T,T_BUFF,
     &                ISIGDEN
#if defined (VAR_MPI2)
     &               ,LUCLIST,LUHCLIST,IBLOCKL_C,NPARBLOCK_C,
     &                IGROUPLIST,IPROCLIST,RCCTOS,WORK(KSCALLOC),
     &                IT_TTPL,IT_TTOL
     &               ,IBLOCKL_S,NPARBLOCK_S
#endif
     &                 )
C
      CALL MEMMAR(KXDUM,IDUM,'FLUSM ',IDUM,'SIGDC ')
      CALL QEXIT('SIGDC')
C
      END
C&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&
      SUBROUTINE SIGDEN_REL(C,HC,NBATS,LBATS,LEBATS,I1BATS,IBATS,
     &                      LLUC,LLUHC,T,T_BUFF,ISIGDEN
#if defined (VAR_MPI2)
     &                     ,LUCLIST,LUHCLIST,IBLOCKL_C,NPARBLOCK_C,
     &                      IGROUPLIST,IPROCLIST,RCCTOS,ISCLFAC_GROUP,
     &                      IT_TTPL,IT_TTOL
     &                     ,IBLOCKL_S,NPARBLOCK_S
#endif
     &                 )
C***********************************************************************
C
C     outer routine for sigma (ISIGDEN==1) and density (ISIGDEN==2) 
C     calculation for a general relativistic CI/CC code
C
C     for sigma T is the input set of integrals (CI) / cluster
C     amplitutes (CC)
C     for density T is the output set of density matrix elements
C
C     Jeppe Olsen, Summer of 99, March 2001
C 
C     Modifications for vector storage and sigma loops
C     Timo Fleig, Halloween 2001
C
C     revision and (parallel) generalization: Stefan Knecht - Oct 2008
C
C***********************************************************************
      use symmetry_setup_krci
      use mospinor_info
      use interface_to_mpi
      IMPLICIT REAL*8(A-H,O-Z)
#include "ipoist8.inc"
#include "mxpdim.inc"
*
* =====
*.Input
* =====
#include "cands.inc"
#include "cicisp.inc"
#include "strbas.inc"
#include "cstate.inc"
#include "strinp.inc"
#include "stinf.inc"
#include "wrkspc.inc"
#include "crun.inc"
#include "gasstr.inc"
#include "cgas.inc"
#include "cprnt.inc"
#include "ctcc.inc"
#include "clunit.inc"
#if defined (VAR_MPI2)
#include "infpar.h"
      INTEGER   ISTAT(df_MPI_STATUS_SIZE)
      DIMENSION LUCLIST(*), IBLOCKL_C(*), NPARBLOCK_C(*), IGROUPLIST(*)
      DIMENSION IPROCLIST(*), IBLOCKL_S(*), NPARBLOCK_S(*)
      INTEGER   RCCTOS(*)
      DIMENSION ISCLFAC_GROUP(*), LUHCLIST(*)
      INTEGER(KIND=df_MPI_OFFSET_KIND) IOFFSET_SCRATCH
      INTEGER(KIND=df_MPI_OFFSET_KIND) IOFF_SCR1, IOFF_SCR2
      INTEGER(KIND=df_MPI_OFFSET_KIND) IOFF_SCR1_C, IOFF_SCR2_C
      CHARACTER WALLTID2*12,WALLTID3*12
#endif /* if def VAR_MPI2 */
#include "parluci.h"
#include "krciprop.h"
#include "files_r.inc"
*
#include "dgroup.h"
      LOGICAL SBLK_READS2

      CHARACTER SECTID*12,WALLTID*12
*
*     batches of sigma
      DIMENSION LBATS(*),LEBATS(*),I1BATS(*),IBATS(8,*)
      DIMENSION HC(*),C(*)
*     scratch
      INTEGER IONE, INT_IOFF1, INT_IOFF2
      INTEGER INT_IOFF1_C, INT_IOFF2_C
      !Statistics
      integer Num_Det_MS2(NMS2VAL)
      real(8) Timing_MS2(NMS2VAL)
*
      IONE        = 1
      INT_IOFF1   = 0
      INT_IOFF2   = 0
      ISI_CALC_BL = 0
      IBI_MULT_BL = 0
      xreadtimebi = 0.0D0
      xcomputesi  = 0.0D0

      Num_A_str_stat = 0
      Num_C_str_stat = 0
      Ave_Num_A_str = 0.0d0
      Ave_Num_C_str = 0.0d0

      Batch_time = 0.0D0
      Cvec_time = 0.0D0
      T_time = 0.0D0
      Sigma_time = 0.0D0
      CalcMatTime = 0.0D0
      gnside_time = 0.0D0
      start_gnside = 0.0D0
      kabt_start = 0.0D0
      kabt_end = 0.0D0
      kabt_tot = 0.0D0
      kbbt_start = 0.0D0
      kbbt_end = 0.0D0
      kbbt_tot = 0.0D0
      ca_cb_sm_start = 0.0D0
      ca_cb_sm_end = 0.0D0
      ca_cb_sm_tot = 0.0D0
      ca_b_sm_end = 0.0D0
      ca_b_sm_start = 0.0D0
      ca_b_sm_tot = 0.0D0
      aa_b_sm_end = 0.0D0
      aa_b_sm_start = 0.0D0
      aa_b_sm_tot = 0.0D0
#if defined (VAR_MPI2)
      IOFF_SCR1 = 0
      IOFF_SCR2 = 0
      mem_cp_time = 0.0D0
#endif
*
      CALL QENTER('SIGDE')
      IDUM = 0
      call memmar(KDUM,IDUM,'MARK  ',IDUM,'SIGDEN')
*
!     NTESTL = 0000
      NTESTL = 5000 ! debug
      if (ISIGDEN.eq.1) then
        NTEST = max(NTESTL,IPRSIG)
      else if (ISIGDEN.eq.2) then
        NTEST = max(NTESTL,IPRDEN)
      else
        write(LUWRT,*) ' Illegal value for ISIGDEN: ',ISIGDEN
        call quit('*** ERROR in SIGDEN_REL ***')
      end if
*
#ifdef LUCI_DEBUG
      IF(NTEST.GE.50) THEN 
        write(LUWRT,*)
        write(LUWRT,*)
        write(LUWRT,*) '++++++++++++++++++++++++++++++++++++++'
        write(LUWRT,*) '++++++++++++++++++++++++++++++++++++++'
        WRITE(LUWRT,*) '       SIGDEN_REL in action           '
        write(LUWRT,*) '++++++++++++++++++++++++++++++++++++++'
        write(LUWRT,*) '++++++++++++++++++++++++++++++++++++++'
        WRITE(LUWRT,*) '          ICSM, ISSM = ', ICSM, ISSM
      END IF
#endif
*
*     file LUSC37 is not needed in a MPI run
*
#if !defined (VAR_MPI2)
      Open(Unit=LUSC37,File=NLUSC37_MPI(1:LUSC344_MPIL),
     &     Status='UNKNOWN',Form='UNFORMATTED')
#endif
*
      LBLK = -1
*
*     LUCIAREL is a relativistic CI program. 
*     However, for quaternion real groups, we use real
*     algebra.
      if (NZ.eq.1) then
        IRILP = 1
      else
        IRILP = 2
      end if
*
*=====================================================
#if defined (VAR_MPI2)
*
*     make an update of list ISCLFAC_GROUP using LUCLIST...
      BLOCKTIME = 0.0D0
      CALL UPDATE_LUC_LIST(ISCLFAC_GROUP,LUCLIST,RCCTOS,C,
     &                     NPARBLOCK_C,IBLOCKL_C,IGROUPLIST,
     &                     IPROCLIST,IRILP,BLOCKTIME)
*
*     debug printing
      NPTESTVAR = 00
      IF( NPTESTVAR .ge. 20 ) THEN
      IOFFSET_SCRATCH = 0
      WRITE(LUWRT,*) 'left vector = C-vector'
      DO I_COMPLEX = 1, IRILP
        IF( I_COMPLEX .eq. 1 ) THEN
          WRITE(LUWRT,*) ' real part'
        ELSE
          WRITE(LUWRT,*) ' imaginary part'
        END IF
        DO IBLK = 1, NUM_BLOCKS
*
          LENGTH_BLK = IBLOCKL_C(IBLK)
          IF(ISCLFAC_GROUP(((I_COMPLEX-1)*NUM_BLOCKS)+IBLK).ne.0)THEN
          call interface_mpi_FILE_READ_AT_r(LLUC,IOFFSET_SCRATCH,C,
     &                                    LENGTH_BLK,ISTAT)
            WRITE(LUWRT,'(A,1X,I12,1X,A,1X,I6,1X,I6)') 'Read-in at',
     &            IOFFSET_SCRATCH,'for block', 
     &            (I_COMPLEX - 1 ) * NUM_BLOCKS  + IBLK,
     &            LENGTH_BLK
            CALL WRTMATMN(C,1,LENGTH_BLK,1,LENGTH_BLK,LUWRT)
          END IF
          IOFFSET_SCRATCH = IOFFSET_SCRATCH + LENGTH_BLK
*
*
          END DO
        END DO
      END IF
      NPTESTVAR = 00
      IOFFSET_SCRATCH = 0
*
*=====================================================
#else
*=====================================================

!#define LUCI_DEBUG
#ifdef LUCI_DEBUG
      if (NTEST.ge.1000) then
        write(LUWRT,*) '--------------------------------------'
        write(LUWRT,*) ' Printing vectors in SIGDEN_REL.      '
        write(LUWRT,*) '--------------------------------------'
        write(LUWRT,*) '  Right vector: '
        call wrtvcdc(C,LLUC,1,IRILP,-1)
        if (ISIGDEN.eq.2) then
          write(LUWRT,*) '  Left vector: '
          call wrtvcdc(HC,LLUHC,1,IRILP,-1)
        end if
      end if
#endif
*
      CALL REWINE(LLUC,-1)
      CALL REWINE(LLUHC,-1)
*
#endif /* if def VAR_MPI2 */
*=====================================================
*
*     loop over vectors of sigma and C : MK2 space
      DO IRIS = 1,IRILP,1
#if defined (VAR_MPI2)
*       initialize writing (ISIGDEN == 1) resp. reading (ISIGDEN == 2)
        IOFF_SCR1 = 0
        IOFF_SCR2 = 0
        IOFF_SCR1 = MY_LU2_OFF
     &            + MY_VEC2_IOFF * ( JVEC_SF )
     &            + MY_VEC1_IOFF * ( IRIS -1 )
        INT_IOFF1  = 0
        INT_IOFF2  = 0
*
        INT_IOFF1  = 1 + MY_ACT_BLK2 * ( JVEC_SF )
     &                 + MY_ACT_BLK1 * ( IRIS -1 )
*
        NUM_BLK_ACT_S   = 0
        IOFFSET_SCRATCH = 0
*
#endif /* if def VAR_MPI2 */
*
#ifdef LUCI_DEBUG
        if (NTEST.ge.50) then
          write(LUWRT,*)
          write(LUWRT,*) '-----------------------'
          write(LUWRT,*) ' SIGMA LOOP , IRIS = ',IRIS
          write(LUWRT,*) '-----------------------'
        end if
#endif
*
*       count the 'active' sigma blocks
        NUM_SBLK_ACT_BT = 0
*
        JBATABS = 0
        DO IMK2_S = 1, NMS2VAL
          MK2_S = MS2VAL(IMK2_S)
#ifdef LUCI_DEBUG
          if (NTEST.ge.50) then
            write(LUWRT,*) '- - - - - - - - - - - -'
            write(LUWRT,*) ' MK2_S LOOP , MK2_S = ',MK2_S
            write(LUWRT,*) '- - - - - - - - - - - -'
          end if
#endif
*
          IASTP = IST_FOR_DT(1,IMK2_S)
          IBSTP = IST_FOR_DT(2,IMK2_S)
          NOCTPA_S = NOCTYP(IASTP)
          NOCTPB_S = NOCTYP(IBSTP)
*
*         arrays giving allowed type combinations (of alpha and beta)
          call memmar(KSIOIO,NOCTPA_S*NOCTPB_S,'ADDL  ',1,'SIOIO ')
          CALL IAIBCM_REL(ISSPC,IASTP,IBSTP,WORK(KSIOIO))
*
*         arrays giving block type
          KSVST = 1
          call memmar(KSBLTP,NSMST,'ADDL  ',1,'SBLTP ')
          CALL ZBLTP_REL(ISMOST(1,ISSM),NSMST,WORK(KSBLTP))


*
* Loop over batches of sigma for this MK2_S projection value
C          LEN_MK2S_ANDREAS = 0
C          call CPU_TIME(TIME1MK2S)

          do JBATS = 1,NBAT_MS2(IMK2_S)
*
            JBATABS = JBATABS + 1
*
#if defined (VAR_MPI2)
*
*           start various timings...
            starttime  = interface_MPI_WTIME()
            sbatchtime = 0.0D0
            writetime  = 0.0D0
            KBATSEND = I1BATS(JBATABS) + LBATS(JBATABS)
*
*           set new offsets for reading from ILU2
            IF( ISIGDEN .eq. 2 )THEN
              IOFF_SCR1 = IOFF_SCR1 + IOFFSET_SCRATCH
              INT_IOFF1 = INT_IOFF1 + NUM_BLK_ACT_S 
            END IF
            ICOMPUTE = 0
            LS = 0
            NUM_BLK_ACT_S   = 0
            IOFFSET_SCRATCH = 0
*
*           check whether a cpu needs to call sigden_rel2
            DO ISBLK = I1BATS(JBATABS),KBATSEND-1,1
              IF( NPARBLOCK_S(ISBLK) .eq. MYPROC ) THEN 
                ICOMPUTE = 1
                NUM_BLK_ACT_S = NUM_BLK_ACT_S + 1
                IOFFSET_SCRATCH = IOFFSET_SCRATCH + IBLOCKL_S(ISBLK)
              END IF
            END DO
            IF( ICOMPUTE .eq. 0 ) THEN
              starttimer = interface_MPI_WTIME()
              GOTO 60
            ENDIF
#endif /* if def VAR_MPI2 */
C
            LS = LEBATS(JBATABS)


C            LEN_MK2S_ANDREAS = LEN_MK2S_ANDREAS + LS
            CALL DZERO(HC,LS)


            if (ISIGDEN.eq.1) then
#ifdef LUCI_DEBUG
              if (NTEST.ge.500) then
                 WRITE(LUWRT,*)
                 WRITE(LUWRT,*)
     &           ' =============================================='
                 WRITE(LUWRT,*)
     &           ' Start of construction of Sigma batch ', JBATABS
                 write(LUWRT,'(2X,A,I3)') ' for MK2_S value ',MK2_S
                 WRITE(LUWRT,*) 
     &           ' =============================================='
                 WRITE(LUWRT,*)
              end if
#endif
            else 
C             ... sigma blocks read from disk in density run?
C             this is important since we might skip complete s blocks 
C             because of MK2_DIFF > 4.
              SBLK_READS2 = .FALSE.
            end if
C
#if !defined (VAR_MPI2)
            call REWINE(LLUC,-1)
            if(LS==0) goto 60 !Skip calculation for this MK2S
#endif

!            if(LS==0) goto 60 !Skip calculation for this MK2S
            DO IRIC = 1,IRILP,1
#if defined LUCI_DEBUG
            if (NTEST.ge.50) then
              write(LUWRT,*)
              write(LUWRT,*) '-----------------------'
              write(LUWRT,*) ' C     LOOP , IRIC = ',IRIC
              write(LUWRT,*) '-----------------------'
            end if
#endif
#if defined (VAR_MPI2)
*             initialize reading
              IOFF_SCR1_C = 0
              IOFF_SCR2_C = L_COMBI
              IOFF_SCR1_C = IOFF_SCR2_C * ( IRIC -1 )
              IOFF_SCR2_C = 0
*
              INT_IOFF1_C = 0
              INT_IOFF2_C = 0
*
              INT_IOFF1_C = 1 + MY_ACT_BLK_ALL * ( IRIC -1 )
              NUM_BLK = 0
*
#else
              IF(IRIC.EQ.2) THEN
*               skip EOV mark between real and imaginary part
                CALL IFRMDS(IONEM,1,-1,LLUC)
              END IF
#endif /* if def VAR_MPI2 */
*
              DO IMK2_C = 1, NMS2VAL
                MK2_C = MS2VAL(IMK2_C)
#ifdef LUCI_DEBUG
                if (NTEST.ge.50) then
                  write(LUWRT,*) '- - - - - - - - - - - -'
                  write(LUWRT,*) ' MK2_C LOOP , MK2_C = ',MK2_C
                  write(LUWRT,*) '- - - - - - - - - - - -'
                end if
#endif
                MK2_DIFF = ABS(MK2_C - MK2_S)
                max_MK2_DIFF =  4  ! max delta delta MK
#ifdef LUCI_DEBUG
                IF(NTEST .ge. 50)THEN
                  write(LUWRT,*) 'MK2_DIFF =',MK2_DIFF
                  IF(MK2_DIFF .gt. max_MK2_DIFF) THEN
                    write(LUWRT,*) 'MK2 skip, MK2_DIFF =',MK2_DIFF
                  END IF
                END IF
#endif
*               ... for any two-electron operator.
*                   For one-electron operators max_MK2_DIFF = 1 or 0
*                   (or zero, if NZ .lt. 4 and operator is not j- or
*                   k-imaginary) /HJAAJ Aug 2008. TODO TODO to define
*                   max_MK2_DIFF
*
                IACTP = IST_FOR_DT(1,IMK2_C)
                IBCTP = IST_FOR_DT(2,IMK2_C)
                NBL_C = NBLK_MS2(IMK2_C)
C               C and sigma may have different symmetry in general
                IF( DOSIGPROP ) NBL_C = NBLK_MS2_C(IMK2_C)
#if defined (VAR_MPI2)
*               set new offset
                IOFF_SCR1_C = IOFF_SCR1_C + IOFF_SCR2_C
                INT_IOFF1_C = INT_IOFF1_C + INT_IOFF2_C
#else
                IF (MK2_DIFF .LE. max_MK2_DIFF) THEN
C                 copy blocks with given MK2_C to LUSC37
                  CALL REWINE(LUSC37,-1)
                  CALL COPNBLKD(LLUC,LUSC37,C,NBL_C,0,LBLK)
C                 end of vector mark
                  CALL ITODS(-1,1,-1,LUSC37)
                ELSE
C                 skip blocks with given MK2_C
                  CALL COPNBLKD(LLUC,-1,C,NBL_C,0,LBLK)
                END IF

#endif /* if def VAR_MPI2 */
                IF (MK2_DIFF .LE. max_MK2_DIFF)
     &          call sigden_rel2(C,HC,JBATABS,LBATS,LEBATS,I1BATS,
     &                           IBATS,LUSC37,LLUHC,T,T_BUFF,
     &                           ISIGDEN,IASTP,IBSTP,IRIS,IRIC,
     &                           IMK2_C,IPRDEN,SBLK_READS2
#if defined (VAR_MPI2)
     &                          ,LUCLIST,IOFF_SCR1_C,INT_IOFF1_C,
     &                           ISCLFAC_GROUP,NPARBLOCK_C,IBLOCKL_C,
     &                           LUHCLIST,IOFF_SCR1,INT_IOFF1,LLUC,
     &                           IT_TTPL,IT_TTOL
     &                          ,IBLOCKL_S,NPARBLOCK_S
#endif
     &                           )
#if defined (VAR_MPI2)
*               keep track of correct offset
                IOFF_SCR2_C = 0
                DO ICBLK = 1, NBL_C
                  IOFF_SCR2_C = IOFF_SCR2_C
     &                        + IBLOCKL_C( NUM_BLK + ICBLK )
                END DO
                NUM_BLK = NUM_BLK + NBL_C
                INT_IOFF2_C = NBL_C
#endif /* if def VAR_MPI2 */
              END DO ! IMK2_C
            END DO ! IRIC
*
 60       CONTINUE
            if(ISIGDEN.eq.1) then
#ifdef LUCI_DEBUG
              if(NTEST.ge.100) then
                WRITE(LUWRT,'(/A)') ' ******************'
                WRITE(LUWRT,'( A)') ' *  final sbatch  *'
                WRITE(LUWRT,'(A/)') ' ******************'
                CALL WRTMATMN(HC,1,LEBATS(JBATABS),1,
     &                         LEBATS(JBATABS),LUWRT)
              end if
#endif
              KBATSEND = I1BATS(JBATABS) + LBATS(JBATABS)
#if defined (VAR_MPI2)
              starttimer = interface_MPI_WTIME()
              IF( ICOMPUTE .eq. 0 ) GOTO 70
#endif /* if def VAR_MPI2 */
              do ISBLK = I1BATS(JBATABS),KBATSEND-1,1
#if defined (VAR_MPI2)
*               check if block is needed
                IF( NPARBLOCK_S(ISBLK) .ne. MYPROC ) GOTO 65
*
*               new offset
*
                IOFF_SCR1 = IOFF_SCR1 + IOFF_SCR2
                INT_IOFF1 = INT_IOFF1 + INT_IOFF2
*
                IOFF = IBATS(6,ISBLK)
                LEN_T = IBATS(8,ISBLK)
*               check norm of the block
                XXX = 0.0D0
                XXX = DDOT(LEN_T,HC(IOFF),1,HC(IOFF),1)
                IF( XXX .ne. 0.0D0 ) THEN
C                 mark block as nonzero
                  LUHCLIST(INT_IOFF1) = IONE
C                 transfer block to disc
!                 WRITE(LUWRT,*) 'I transfer to file block ISBLK',
!    &                            ISBLK
!                 CALL WRTMATMN(HC(IOFF),1,LEN_T,1,LEN_T,LUWRT)
!                 WRITE(LUWRT,*) 'offset,length, IRIS',
!    &                            IOFF_SCR1,LEN_T,IRIS
                  call interface_mpi_FILE_WRITE_AT(LLUHC,IOFF_SCR1,
     &                                   HC(IOFF),LEN_T,
     &                                   ISTAT)
                  ISI_CALC_BL = ISI_CALC_BL + 1
                END IF
*               keep track of correct offset
                IOFF_SCR2 = LEN_T
                INT_IOFF2 = 1
 65             CONTINUE
#else
                IOFF = IBATS(6,ISBLK)
                LEN_T = IBATS(8,ISBLK)
                call itods(LEN_T,1,-1,LLUHC)
                call todsc(HC(IOFF),LEN_T,-1,LLUHC)
                ISI_CALC_BL = ISI_CALC_BL + 1
#endif /* if def VAR_MPI2 */
              END DO
 70           CONTINUE
#if defined (VAR_MPI2)
              IF( ICOMPUTE .ne. 0 ) THEN
                writetime  = writetime  + interface_MPI_WTIME() 
     &                     - starttimer
                sbatchtime = sbatchtime + interface_MPI_WTIME() 
     &                     - starttime
CSK too much information?                WALLTID  = SECTID(writetime)
                WALLTID2 = SECTID(sbatchtime)
CSK too much information?                 WRITE(LUWRT,50000) WALLTID
!               IF( .NOT. DOSIGPROP ) WRITE(LUWRT,60001) WALLTID2
CSK                WRITE(LUWRT,60000) WALLTID2, JBATABS
              END IF
#endif /* if def VAR_MPI2 */
            END IF
C           ^ ISIGDEN == 1
C
#if !defined (VAR_MPI2)
C           skip sigma blocks on disk
            IF( ISIGDEN .eq. 2 .and. .NOT. SBLK_READS2 )THEN
               ISKIP_S2_BLOCKS = 0
               do ISBLK = I1BATS(JBATABS),
     &                    I1BATS(JBATABS) + LBATS(JBATABS)-1
                  ISKIP_S2_BLOCKS = ISKIP_S2_BLOCKS + 1
               end do 
               CALL COPNBLKD(LLUHC,-1,C,ISKIP_S2_BLOCKS,0,LBLK)
            END IF
#endif /* if !def VAR_MPI2 */
          END DO
*         ^ End loop over S batches of given MK2_S value
C          call CPU_TIME(TIME2MK2S)
C          WALLTID = SECTID(TIME2MK2S-TIME1MK2S)
C          write(LUWRT,*) 'MK2_S, No. of determinants, time',
C     &    MK2_S, LEN_MK2S_ANDREAS, WALLTID
        END DO
*       ^ End of loop over IMK2_S

*
#if !defined (VAR_MPI2)
        if (ISIGDEN.eq.1) then
* Write end of vector mark between real and imaginary part.
          call itods(-1,1,-1,LLUHC)
        else if (ISIGDEN.eq.2) then
* Skip end of vector mark between real and imaginary part.
          call ifrmds(IONEM,1,-1,LLUHC)
        end if
#endif /* if !def VAR_MPI2 */
*
      END DO
*     ^ End of loop over IRIS
      call memmar(KDUM ,IDUM,'FLUSM ',2,'SIGDEN')
*
      CALL QEXIT('SIGDE')
#if !defined (VAR_MPI2)
*     close scratch unit for Right vector

      close(unit=LUSC37,status='DELETE')
!        WALLTID = SECTID(Batch_time)
!        WRITE(LUWRT,'(2X,A,1X,A)')
!     &  ' Time for batching       : ', WALLTID
!        WALLTID = SECTID(Cvec_time)
!        WRITE(LUWRT,'(2X,A,1X,A)')
!     &  ' Time for C RI vector       : ', WALLTID
!        WALLTID = SECTID(T_time)
!        WRITE(LUWRT,'(2X,A,1X,A)')
!     &  ' Time for T matrix       : ', WALLTID
!        WALLTID = SECTID(Sigma_time)
!        WRITE(LUWRT,'(2X,A,1X,A)')
!     &  ' Time for Sigma addition       : ', WALLTID
!        WALLTID = SECTID(CalcMatTime)
!        WRITE(LUWRT,'(2X,A,1X,A)')
!     &  ' Time for matrix multiplication       : ', WALLTID
!        WALLTID = SECTID(gnside_time)
!        WRITE(LUWRT,'(2X,A,1X,A)')
!     &  ' Time for gnside       : ', WALLTID
!        write(LUWRT,*) 'Number of annihilation strings', Num_A_str_stat
!        write(LUWRT,*) 'Number of creation strings', Num_C_str_stat
!        write(LUWRT,*) 'Annihilation strings per batch,summed',
!     &               Ave_Num_A_str
!        write(LUWRT,*) 'Creation strings per batch, summed',
!     &               Ave_Num_C_str
*
#else
*
!        WALLTID = SECTID(Start_gnside)
!        WRITE(LUWRT,'(2X,A,1X,A)')
!     &  ' Time spent in start of gnside       : ', WALLTID
!        WALLTID = SECTID(kabt_tot)
!        WRITE(LUWRT,'(2X,A,1X,A)')
!     &  ' Time spent in KA batches       : ', WALLTID
!        WALLTID = SECTID(kbbt_tot)
!        WRITE(LUWRT,'(2X,A,1X,A)')
!     &  ' Time spent in KB batches       : ', WALLTID
!        WALLTID = SECTID(ca_cb_sm_tot)
!        WRITE(LUWRT,'(2X,A,1X,A)')
!     &  ' Time spent in ca_cb_sm loops       : ', WALLTID
!        WALLTID = SECTID(ca_b_sm_tot)
!        WRITE(LUWRT,'(2X,A,1X,A)')
!     &  ' Time spent in ca_b_sm loops       : ', WALLTID
!        WALLTID = SECTID(aa_b_sm_tot)
!        WRITE(LUWRT,'(2X,A,1X,A)')
!     &  ' Time spent in aa_b_sm loops       : ', WALLTID
!        WALLTID = SECTID(Batch_time)
!        WRITE(LUWRT,'(2X,A,1X,A)')
!     &  ' Time for batching       : ', WALLTID
!        WALLTID = SECTID(Cvec_time)
!        WRITE(LUWRT,'(2X,A,1X,A)')
!     &  ' Time for C RI vector       : ', WALLTID
!        WALLTID = SECTID(T_time)
!        WRITE(LUWRT,'(2X,A,1X,A)')
!     &  ' Time for T matrix       : ', WALLTID
!        WALLTID = SECTID(Sigma_time)
!        WRITE(LUWRT,'(2X,A,1X,A)')
!     &  ' Time for Sigma addition       : ', WALLTID
!        WALLTID = SECTID(CalcMatTime)
!        WRITE(LUWRT,'(2X,A,1X,A)')
!     &  ' Time for matrix multiplication       : ', WALLTID
!        WALLTID = SECTID(gnside_time)
!        WRITE(LUWRT,'(2X,A,1X,A)')
!     &  ' Time for gnside       : ', WALLTID
!        write(LUWRT,*) 'Number of annihilation strings', Num_A_str_stat
!        write(LUWRT,*) 'Number of creation strings', Num_C_str_stat
!        write(LUWRT,*) 'Annihilation strings per batch,summed',
!     &               Ave_Num_A_str
!        write(LUWRT,*) 'Creation strings per batch, summed',
!     &               Ave_Num_C_str
      WALLTID3 = SECTID(BLOCKTIME)
!     IF( .NOT. DOSIGPROP ) WRITE(LUWRT,80000) WALLTID3
      IF( SHARED_M .and. ISIGDEN .eq. 1 )THEN
        WALLTID3 = SECTID(mem_cp_time)
        WRITE(LUWRT,90000) WALLTID3
      END IF
C
      IF( TIMING .and. (.NOT. DOSIGPROP)) THEN
C
C       print statistics
C
        WRITE(LUWRT,'(/A)')
     &  '               H x b_i contraction run statistics  '
        WRITE(LUWRT,'(A/)')
     &  '              ____________________________________ '
        WRITE(LUWRT,'(2X,A,1X,I9)')
     &  ' number of s_i blocks calculated          : ',ISI_CALC_BL
        WRITE(LUWRT,'(2X,A,1X,I9)')
     &  ' total number of b_i read from disk       : ',IBI_MULT_BL
        WALLTID = SECTID(xreadtimebi)
        WRITE(LUWRT,'(2X,A,1X,A)')
     &  ' read time for b_i blocks from disk       : ', WALLTID
        WALLTID = SECTID(xcomputesi)
        WRITE(LUWRT,'(2X,A,1X,A/)')
     &  ' matrix x vector multiplication time      : ', WALLTID
C
      END IF
C


*
50000 FORMAT(' >>>  WALL TIME FOR WRITING SB TO DISK           :
     & ',A)
60000 FORMAT(' >>>  WALL TIME IN TOTAL FOR CURRENT S-BATCH     :
     & ',A,I4)
60001 FORMAT(' >>>  WALL TIME IN TOTAL FOR CURRENT S-BATCH     :
     & ',A)
80000 FORMAT(' >>>  WALL TIME FOR C-COEFFICIENT EXCHANGE       :
     & ',A)
90000 FORMAT(' >>>  WALL TIME FOR OBTAINING T-ELEMENTS         :
     & ',A)
*
#endif /* if !def VAR_MPI2 */
*
!#undef LUCI_DEBUG
      END
***********************************************************************

      SUBROUTINE SIGDEN_REL2(CB,SB,JBATABS,LBATS,LEBATS,I1BATS,IBATS,
     &                       LUC,LUHC,T,T_BUFF,ISIGDEN,IASTP,IBSTP,
     &                       IRIS,IRIC,IMK2_C,IPRNT,SBLK_READS2
#if defined (VAR_MPI2)
     &                      ,LUCLIST,IOFF_SCR1_C,INT_IOFF1_C,
     &                       ISCLFAC_GROUP,NPARBLOCK_C,IBLOCKL_C,
     &                       LUHCLIST,IOFF_SCR1,INT_IOFF1,LLUC,
     &                       IT_TTPL,IT_TTOL
     &                      ,IBLOCKL_S,NPARBLOCK_S
#endif
     &                       )
*
* First inner routine for general CC sigma/densi
*
* Complete S and C vectors
*
* Jeppe Olsen   Relativistic version, Winter of 2001
*
* =====
* Input
* =====
*
      use symmetry_setup_krci
      use interface_to_mpi
#include "implicit.inc"
#if defined (VAR_MPI2)
#include "infpar.h"
      INTEGER   ISTAT(df_MPI_STATUS_SIZE), NPARBLOCK_C(*)
      DIMENSION LUCLIST(*), ISCLFAC_GROUP(*), IBLOCKL_C(*)
      DIMENSION LUHCLIST(*), IBLOCKL_S(*), NPARBLOCK_S(*) 
      INTEGER(KIND=df_MPI_OFFSET_KIND) IOFF_SCR1, IOFF_SCR2 
      INTEGER(KIND=df_MPI_OFFSET_KIND) IOFF_SCR_EXPL
      INTEGER INT_IOFF1, INT_IOFF2, INT_IOFF3, INT_IOFF_EXPL
#endif
#include "parluci.h"
#include "ipoist8.inc"
#include "mxpdim.inc"
#include "gasstr.inc"
#include "cstate.inc"
#include "wrkspc.inc"
#include "strbas.inc"
*. Batches of sigma
      INTEGER LBATS(*),LEBATS(*),I1BATS(*),IBATS(8,*)
*.Scratch
      DIMENSION SB(*),CB(*)
      dimension T(*)
      LOGICAL SBLK_READS2
*
      NTESTL = 000
      NTEST = MAX(NTESTL,IPRNT)
*
#ifdef LUCI_DEBUG
      IF(NTEST.GE.100) THEN
        WRITE(LUWRT,*) ' ================='
        WRITE(LUWRT,*) ' SIGDEN2 speaking :'
        WRITE(LUWRT,*) ' ================='
      END IF
#endif
#if defined (VAR_MPI2)
*     initialize scratch variables      
      IOFF_SCR2     = 0
      INT_IOFF3     = 0
      INT_IOFF_EXPL = 0
      IOFF_SCR_EXPL = 0
      ICOUNT_ACT    = 0
#endif
*
*      ISIGDEN = 2 : Read in batch of blocks of lhs vector
*      unique blocks are read in
*
#if defined (VAR_MPI2)
      INT_IOFF2 = 0
      INT_IOFF3 = I1BATS(JBATABS)
CSK      WRITE(LUWRT,*) 'NEW INT_IOFF3 in SIGDEN2 FOR JBATABS',INT_IOFF3,
CSK     &                JBATABS
      INT_IOFF_EXPL = INT_IOFF1
      IOFF_SCR_EXPL = IOFF_SCR1
#endif
*
      IF (ISIGDEN .eq. 2 )THEN
csk     if (IRIC .eq. 1 .and. IMK2_C .eq. 1 )then
        IF ( .NOT. SBLK_READS2 )THEN
C
          DO 100 ISBLK = I1BATS(JBATABS),
     &                   I1BATS(JBATABS)+LBATS(JBATABS)-1
#if defined (VAR_MPI2)
            IF( NPARBLOCK_S( ISBLK ) .ne. MYPROC ) GOTO 100
C           ... active CPU-block found
            ICOUNT_ACT = ICOUNT_ACT + 1
#endif
            ISATP = IBATS(1,ISBLK)
            ISBTP = IBATS(2,ISBLK)
            ISASM = IBATS(3,ISBLK)
            ISBSM = IBATS(4,ISBLK)
            ISOFF = IBATS(5,ISBLK)
            LEN2  = IBATS(7,ISBLK)
#if defined (VAR_MPI2)
C           CPU-block - test if non-zero
            IF( LUHCLIST( INT_IOFF_EXPL + ICOUNT_ACT - 1 ).eq.0) GOTO 80
            CALL GSTTBLD_PAR2(SB(ISOFF),LUHC,IOFF_SCR_EXPL,LEN2)
#else
            CALL GSTTBLD2(SB(ISOFF),LUHC)
#endif
*
            IF (LEN2 .gt. 0 .and. NTEST .ge. 100) THEN
              WRITE(LUWRT,'(/A,2I6)') 
     &        '  lhs vector block:',ISBLK, ISOFF
              CALL WRTMATMN(SB(ISOFF),1,LEN2,1,LEN2,LUWRT)
            END IF

  80        CONTINUE
#if defined (VAR_MPI2)
            IOFF_SCR2 = LEN2
            IOFF_SCR_EXPL = IOFF_SCR_EXPL + IOFF_SCR2
#endif
 100      CONTINUE
*         ^ end of loop over S-blocks in batch
          SBLK_READS2 = .TRUE.
        END IF
*       ^ only perform read if new S batch requested
      END IF
*     ^ only for density evaluation
*
*     obtain sigma/density for batch of blocks
!      call CPU_TIME(gnside1)
      CALL SIGDEN_REL3(LBATS(JBATABS),IBATS(1,I1BATS(JBATABS)),1,
     &                 CB,SB,LUC,T,T_BUFF,ISIGDEN,IRIS,IRIC
#if defined (VAR_MPI2)
     &                ,LUCLIST,IOFF_SCR1_C,INT_IOFF1_C,
     &                 ISCLFAC_GROUP,NPARBLOCK_C,IBLOCKL_C,
     &                 LUHCLIST,INT_IOFF3,LLUC,
     &                 IT_TTPL,IT_TTOL
     &                ,IBLOCKL_S,NPARBLOCK_S
#endif
     &                 )
!      call CPU_TIME(gnside2)
!      gnside_time = gnside_time + gnside2 - gnside1
  
*
      END
***********************************************************************

      SUBROUTINE SIGDEN_REL3(NBLOCK,IBLOCK,IBOFF,CB,HCB,LUC,T,T_BUFF,
     &                       ISIGDEN,IRIS,IRIC
#if defined (VAR_MPI2)
     &                      ,LUCLIST,IOFF_SCR1_C,INT_IOFF1_C,
     &                       ISCLFAC_GROUP,NPARBLOCK_C,IBLOCKL_C,
     &                       LUHCLIST,INT_IOFF3,LLUC,
     &                       IT_TTPL,IT_TTOL
     &                      ,IBLOCKL_S,NPARBLOCK_S
#endif
     &                       )
*
* Generate a set of sigma blocks, 
* The NBLOCK specified in IBLOCK starting from IBOFF,
* be more specific.
*
* The blocks are delivered in HCB
*
*============================================
* Proper allocation of resolution quantities
*    Timo Fleig, March 25, 2003
* Revised, more efficient.
*    Timo Fleig, March 31, 2003
*============================================
*
      use symmetry_setup_krci
      use mospinor_info
      use interface_to_mpi
!     will later contain useful string information... - placeholder for the time being
      use string_info
      IMPLICIT REAL*8(A-H,O-Z)
#include "ipoist8.inc"
#include "mxpdim.inc"
*
* =====
*.Input
* =====
*
*. Sigma blocks require
      INTEGER IBLOCK(8,*)
*
#include "cands.inc"
#include "cicisp.inc"
#include "strbas.inc"
#include "cstate.inc"
#include "strinp.inc"
#include "stinf.inc"
#include "wrkspc.inc"
#include "crun.inc"
#include "gasstr.inc"
#include "cgas.inc"
#include "cprnt.inc"
#include "oper.inc"
#include "ctcc.inc"
      COMMON/CMXCJ/MXCJ
*
C     integer array may become very long
      INTEGER*8 INTSCR
C
#if defined (VAR_MPI)
#include "infpar.h"
      INTEGER   ISTAT(df_MPI_STATUS_SIZE)
#endif
#include "cintfo.inc"
#include "parluci.h"
#if defined (VAR_MPI2)
#include "krmc_shmem.h"
#include "mxdim_mpi2.h"
      POINTER (MY_T_SCR_PTR, T_SCR_CC(IDUMMY_BUFF_SZ))
#endif
      DIMENSION CB(*), HCB(*)
      real(8), allocatable :: CJRES_BAT(:), SIRES_BAT(:), T_BAT(:)
      integer, allocatable :: INum_Sym_A(:),ISym_AA(:,:),ISym_AB(:,:)
      integer, allocatable :: IAA_SM_STR_S(:,:,:), IAB_SM_STR_S(:,:,:)
      integer, allocatable :: IAA_SM_STR_E(:,:,:), IAB_SM_STR_E(:,:,:)
      integer, allocatable :: NSubBlk_A(:,:), NStrings_A(:)
      integer, allocatable :: INum_Sym_C(:),ISym_CA(:,:),ISym_CB(:,:)
      integer, allocatable :: ICA_SM_STR_S(:,:,:), ICB_SM_STR_S(:,:,:)
      integer, allocatable :: ICA_SM_STR_E(:,:,:), ICB_SM_STR_E(:,:,:)
      integer, allocatable :: NSubBlk_C(:,:), NStrings_C(:)
      Integer, allocatable :: L_A_Block(:), L_B_Block(:)
      Integer, allocatable :: L_Sym_Block(:)
C
C     set memory mark for local scratch

      IDUM = 0
      call memmar(KDUM,IDUM,'MARK  ',IDUM,'SIGD3X')
C
C     offsets for alpha and beta supergroups
      NOCTPA_C = NOCTYP(IACTP)
      NOCTPB_C = NOCTYP(IBCTP)
C
      NAEL_C = NELEC(IACTP)
      NBEL_C = NELEC(IBCTP)
C
C     arrays for storing NEL consecutive annihilations/creations
C     (resolution matrices)
C     number of alpha/beta excitation types
      CALL SPOBEX_TO_ABOBEX(WORK(KLSOBEX),NSPOBEX_TP,NGAS,
     &                      1,NAOBEX_TP,NBOBEX_TP,IDUMMY,IDUMMY)
C     and the alpha-and beta-excitations (integer arrays...)
      LENA = 2*NGAS*NAOBEX_TP
      LENB = 2*NGAS*NBOBEX_TP
      call memmar(KLAOBEX,LENA,'ADDL  ',1,'IAOBEX')
      call memmar(KLBOBEX,LENB,'ADDL  ',1,'IAOBEX')
      CALL SPOBEX_TO_ABOBEX(WORK(KLSOBEX),NSPOBEX_TP,NGAS,
     &                      0,NAOBEX_TP,NBOBEX_TP,
     &                      WORK(KLAOBEX),WORK(KLBOBEX))
*
*     for alpha excitations, C and S vector (might be flipped around!)
      IOCTPA_C = IBSPGPFTP(IACTP)
      CALL LEN_GENOP_STR_MAP(NAOBEX_TP,WORK(KLAOBEX),NOCTPA_C,
     &                       NELFSPGP(1,IOCTPA_C),NOBPT,NGAS,
     &                       MAXLENAC)
      IOCTPA_S = IBSPGPFTP(IASTP)
      NOCTPA_S = NOCTYP(IASTP)
      CALL LEN_GENOP_STR_MAP(NAOBEX_TP,WORK(KLAOBEX),NOCTPA_S,
     &                       NELFSPGP(1,IOCTPA_S),NOBPT,NGAS,
     &                       MAXLENAS)
*
*     for beta excitations
      IOCTPB_C = IBSPGPFTP(IBCTP)
      CALL LEN_GENOP_STR_MAP(NBOBEX_TP,WORK(KLBOBEX),NOCTPB_C,
     &                       NELFSPGP(1,IOCTPB_C),NOBPT,NGAS,
     &                       MAXLENBC)
      IOCTPB_S = IBSPGPFTP(IBSTP)
      NOCTPB_S = NOCTYP(IBSTP)
      CALL LEN_GENOP_STR_MAP(NBOBEX_TP,WORK(KLBOBEX),NOCTPB_S,
     &                       NELFSPGP(1,IOCTPB_S),NOBPT,NGAS,
     &                       MAXLENBS)
C
C     release pure local scratch
      IDUM = 0
      call memmar(KDUM,IDUM,'FLUSM ',IDUM,'SIGD3X')
C
      MAXLEN_I1 = MAX(MAXLENAC,MAXLENBC,MAXLENAS,MAXLENBS)
!     print *,'SIGDEN3... MAXLEN_I1 is',MAXLEN_I1
      LSCR3             = MAXLEN_I1
      res_string_ix_len = MAXLEN_I1
      do i = 1, 4
        res_string_ix_off(i) = 1 + (i-1) * res_string_ix_len *2
      end do
C
C     non-local scratch - used in called subroutines
      IDUM = 0
      call memmar(KDUM,IDUM,'MARK  ',IDUM,'SIGD3Y')
C
      call memmar(KI1  ,LSCR3,'ADDL  ',1,'I1    ')
      call memmar(KXI1S,0    ,'ADDL  ',2,'XI1S  ')
C
      call memmar(KI2  ,LSCR3,'ADDL  ',1,'I2    ')
      call memmar(KXI2S,0    ,'ADDL  ',2,'XI2S  ')
C
      call memmar(KI3  ,LSCR3,'ADDL  ',1,'I3    ')
      call memmar(KXI3S,0    ,'ADDL  ',2,'XI3S  ')
C
      call memmar(KI4  ,LSCR3,'ADDL  ',1,'I4    ')
      call memmar(KXI4S,0    ,'ADDL  ',2,'XI4S  ')
C
      call izero(work(KI1), LSCR3)
      call izero(work(KI2), LSCR3)
      call izero(work(KI3), LSCR3)
      call izero(work(KI4), LSCR3)
C
C     T-elements
      INTSCR = MXINKA**4
      INTSCR = MIN(INTSCR,MX_TBLK_MX)
!      write(LUWRT,*) 'MXINKA = ',MXINKA
!      write(LUWRT,*) 'MXINKA**4 = ',MXINKA**4
!      write(LUWRT,*) 'MX_TBLK_MX = ',MX_TBLK_MX
!      write(LUWRT,*) 'INTSCR = ',INTSCR
!      write(LUWRT,*) 'MX_ST_TSOSO_BLK_MX = ',MX_ST_TSOSO_BLK_MX
      CALL MEMMAR_I8(KINSCR,INTSCR,'ADDL  ',2,'INSCR ')
C
C     arrays for storing occupations of T-operators
      call memmar(KTOCC1,MX_ST_TSOSO_BLK_MX,'ADDL  ',1,'TOCC1 ')
      call memmar(KTOCC2,MX_ST_TSOSO_BLK_MX,'ADDL  ',1,'TOCC2 ')
      call memmar(KTOCC3,MX_ST_TSOSO_BLK_MX,'ADDL  ',1,'TOCC3 ')
      call memmar(KTOCC4,MX_ST_TSOSO_BLK_MX,'ADDL  ',1,'TOCC4 ')
C
C     arrays for storing NEL consecutive annihilations/creations
      LSCR4 = MXINKA*MXINKA*MXINKA*MXINKA 

      call memmar(KI1G  ,LSCR4,'ADDL  ',1,'I1G   ')
      call memmar(KXI1G,     0,'ADDL  ',2,'XIG   ')
C
      call memmar(KI2G  ,LSCR4,'ADDL  ',1,'I2G   ')
      call memmar(KXI2G,     0,'ADDL  ',2,'XI2G  ')
C
      call memmar(KI3G  ,LSCR4,'ADDL  ',1,'I3G   ')
      call memmar(KXI3G,     0,'ADDL  ',2,'XI3G  ')
C
      call memmar(KI4G  ,LSCR4,'ADDL  ',1,'I4G   ')
      call memmar(KXI4G,     0,'ADDL  ',2,'XI4G  ')
C
      call memmar(KI1GE  ,LSCR4,'ADDL  ',1,'I1GE  ')
      
      call memmar(KXI1GE,     0,'ADDL  ',2,'XIGE  ')
C
      call memmar(KI2GE  ,LSCR4,'ADDL  ',1,'I2GE  ')
      call memmar(KXI2GE,     0,'ADDL  ',2,'XI2GE ')
C
      call memmar(KI3GE  ,LSCR4,'ADDL  ',1,'I3GE  ')
      call memmar(KXI3GE,     0,'ADDL  ',2,'XI3GE ')
C
      call memmar(KI4GE  ,LSCR4,'ADDL  ',1,'I4GE  ')
      call memmar(KXI4GE,     0,'ADDL  ',2,'XI4GE ')
C     TTS arrays for partitioning of vector 
      NTTS = MXNTTS
      call memmar(KLLBT ,NTTS  ,'ADDL  ',1,'LBTC  ')
      call memmar(KLLEBT,NTTS  ,'ADDL  ',1,'LECTC ')
      call memmar(KLI1BT,2*NTTS,'ADDL  ',1,'I1BTC ')
      call memmar(KLIBT ,8*NTTS,'ADDL  ',1,'IBTC  ')
C
C     arrays giving allowed type combinations
      call memmar(KCIOIO,NOCTPA_C*NOCTPB_C,'ADDL  ',1,'CIOIO ')
      CALL IAIBCM_REL(ICSPC,IACTP,IBCTP,WORK(KCIOIO))
C
C     arrays giving block type
      call memmar(KCBLTP,NSMST,'ADDL  ',1,'CBLTP ')
      CALL ZBLTP_REL(ISMOST(1,ICSM),NSMST,WORK(KCBLTP))
C     use all symmetryblocks of given TT
      ITTSS_ORD = 2
C
C     local scratch arrays for blocks of C and sigma
      L0BLOCK = MXSOOB
      LSCR1 = MAX(L0BLOCK,LBLOCK)
#if defined (VAR_MPI2)
C
C     set proper C-block offset...
      ISTART_BLOCK = INT_IOFF1_C - 1
      IDEBUGPRNT = 00
      CALL PART_CIV_PAR3(IDC,WORK(KCBLTP),WORK(KNSTSO(IACTP)),
     &     WORK(KNSTSO2(IBCTP)),NOCTPA_C,NOCTPB_C,NSMST,LSCR1,
     &     WORK(KCIOIO),ISMOST(1,ICSM),NCBATCH,WORK(KLLBT),
     &     WORK(KLLEBT),WORK(KLI1BT),WORK(KLIBT),0,ITTSS_ORD,
     &     ISCLFAC_GROUP,ISTART_BLOCK,0,IDEBUGPRNT)
C           use this line as line 2 for testing more batches ...
C     &     WORK(KNSTSO2(IBCTP)),NOCTPA_C,NOCTPB_C,NSMST,L0BLOCK,
#else
      CALL PART_CIV2_SPC(IDC,WORK(KCBLTP),WORK(KNSTSO(IACTP)),
     &     WORK(KNSTSO2(IBCTP)),NOCTPA_C,NOCTPB_C,NSMST,LSCR1,
     &     WORK(KCIOIO),ISMOST(1,ICSM),NCBATCH,WORK(KLLBT),
     &     WORK(KLLEBT),WORK(KLI1BT),WORK(KLIBT),0,ITTSS_ORD)
#endif
C
      CALL MEMMAR(KLISMDST,MAX_NSYMDIST+1,  'ADDL  ',1,'ISMDST')
C
      LSIRES = MXINKA**4
      LCJRES = LCJRES_SAVE
C
C     allocation of resolution matrices: sigma + C
      call memmar(KSIRES,LSIRES,'ADDL  ',2,'KSIRES')
      call memmar(KCJRES,LCJRES,'ADDL  ',2,'KCJRES')

!     allocation for string length handling of unbarred (alpha)/ barred
!     (beta) creation / annihilation strings
      call memmar(KNICA    ,MXNDGIRR              ,'ADDL  ',1,'KNICA ')
      call memmar(KNICB    ,MXNDGIRR              ,'ADDL  ',1,'KNICB ')
      call memmar(KNIAA    ,MXNDGIRR              ,'ADDL  ',1,'KNIAA ')
      call memmar(KNIAB    ,MXNDGIRR              ,'ADDL  ',1,'KNIAB ')
      call memmar(KNKA     ,MXNDGIRR              ,'ADDL  ',1,'KNKA  ')
      call memmar(KNKB     ,MXNDGIRR              ,'ADDL  ',1,'KNKB  ')

!     allocation for string length handling of unbarred (alpha)/ barred
!     (beta) creation / annihilation strings
      call memmar(KIB_CA   ,MXNDGIRR**2 * MXNOP   ,'ADDL  ',1,'KIB_CA')
      call memmar(KIB_CB   ,MXNDGIRR**2 * MXNOP   ,'ADDL  ',1,'KIB_CB')
      call memmar(KIB_AA   ,MXNDGIRR**2 * MXNOP   ,'ADDL  ',1,'KIB_AA')
      call memmar(KIB_AB   ,MXNDGIRR**2 * MXNOP   ,'ADDL  ',1,'KIB_AB')
      call memmar(KIB_T    ,MXNDGIRR**2 * MXNDGIRR,'ADDL  ',1,'KIB_T ')
      call memmar(KNIKAINTM,MXPOBS      * MXNOP   ,'ADDL  ',1,'KNIKA ')
      call memmar(KNIKBINTM,MXPOBS      * MXNOP   ,'ADDL  ',1,'KNIKB ')
      call memmar(KNJKAINTM,MXPOBS      * MXNOP   ,'ADDL  ',1,'KNJKA ')
      call memmar(KNJKBINTM,MXPOBS      * MXNOP   ,'ADDL  ',1,'KNJKB ')

!     Allocation for batch arrays, such as:
!     Sigma/C and T arrays
!     Annihilation and creation batches
!     Scratch arrays for construction of operator batches
      allocate(CJRES_BAT(MXINKA**4))
      allocate(SIRES_BAT(MXINKA**4))
      allocate(T_BAT(MXINKA**4))
!      write(LUWRT,*) 'Allocating Annihilation arrays'
      allocate(INum_Sym_A(100))
      allocate(ISym_AA(NSMST,100))
      allocate(ISym_AB(NSMST,100))
      !There can be up to two sub blocks of a certain
      !symmetry, so:
      allocate(IAA_SM_STR_S(2,NSMST,100))
      allocate(IAB_SM_STR_S(2,NSMST,100))
      allocate(IAA_SM_STR_E(2,NSMST,100))
      allocate(IAB_SM_STR_E(2,NSMST,100))
      allocate(NSubBlk_A(NSMST,100))
      allocate(NStrings_A(100))

!      write(LUWRT,*) 'Allocating Creation arrays'
      allocate(INum_Sym_C(100))
      allocate(ISym_CA(NSMST,100))
      allocate(ISym_CB(NSMST,100))
      allocate(ICA_SM_STR_S(2,NSMST,100))
      allocate(ICB_SM_STR_S(2,NSMST,100))
      allocate(ICA_SM_STR_E(2,NSMST,100))
      allocate(ICB_SM_STR_E(2,NSMST,100))
      allocate(NSubBlk_C(NSMST,100))
      allocate(NStrings_C(100))
      allocate(L_Sym_Block(NSMST))
      allocate(L_A_Block(NSMST))
      allocate(L_B_Block(NSMST))


C
C     set offset for T_BUFF array
      LEN_T_BUFF_NZ = LEN_T_VEC
#if defined (VAR_MPI2)
C
C     dynamic allocation for scratch T block - MPI info if non-zero
      IF( IT_SHL .ge. 0 ) CALL GET_MEM_T_SCR_CC(0)
#endif
C

      CALL SIGDEN_REL4(NBLOCK,IBLOCK(1,IBOFF),CB,HCB,
     &                 WORK(KNSTSO(IASTP)),WORK(KNSTSO2(IBSTP)),
     &                 WORK(KNSTSO(IACTP)),WORK(KNSTSO2(IBCTP)),
     &                 IASTP,IBSTP,IACTP,IBCTP,MXINKA,WORK(KINSCR),
     &                 WORK(KI1),WORK(KXI1S),WORK(KI2),WORK(KXI2S),
     &                 WORK(KI3),WORK(KXI3S),WORK(KI4),WORK(KXI4S),
     &                 IPRSIG,IPRDEN,LUC,WORK(KCJRES),WORK(KSIRES),
     &                 WORK(KLLBT),WORK(KLLEBT),WORK(KLI1BT),
     &                 WORK(KLIBT),ISSM,ICSM,ISIGDEN,NCBATCH,T,T_BUFF,
     &                 IDIAG,IRIS,IRIC,WORK(KLSOBEX),
     &                 WORK(KTOCC1),WORK(KTOCC2),WORK(KTOCC3),
     &                 WORK(KTOCC4),WORK(KI1G),WORK(KXI1G),WORK(KI2G),
     &                 WORK(KXI2G),WORK(KI3G),WORK(KXI3G),WORK(KI4G),
     &                 WORK(KXI4G),WORK(KI1GE),WORK(KXI1GE),WORK(KI2GE),
     &                 WORK(KXI2GE),WORK(KI3GE),WORK(KXI3GE),
     &                 WORK(KI4GE),WORK(KXI4GE),WORK(KSIGNNHX),
     &                 WORK(KLISMDST),
     &                 WORK(KNICA),WORK(KNICB),WORK(KNIAA),WORK(KNIAB),
     &                 WORK(KNKA),WORK(KNKB),
     &                 WORK(KIB_CA),WORK(KIB_CB),WORK(KIB_AA),
     &                 WORK(KIB_AB),WORK(KIB_T),WORK(KNIKAINTM),
     &                 WORK(KNIKBINTM),WORK(KNJKAINTM),WORK(KNJKBINTM),
     &                 L_Sym_Block,L_A_Block,L_B_Block,INum_Sym_A,
     &                 ISym_AA,ISym_AB,IAA_SM_STR_S,IAB_SM_STR_S,
     &                 IAA_SM_STR_E,IAB_SM_STR_E,NSubBlk_A,NStrings_A,
     &                 INum_Sym_C,ISym_CA,ISym_CB,ICA_SM_STR_S,
     &                 ICB_SM_STR_S,ICA_SM_STR_E,ICB_SM_STR_E,NSubBlk_C,
     &                 NStrings_C,CJRES_BAT,SIRES_BAT,T_BAT
#if defined (VAR_MPI2)
     &                ,LUCLIST,IOFF_SCR1_C,INT_IOFF1_C,
     &                 ISCLFAC_GROUP,NPARBLOCK_C,IBLOCKL_C,
     &                 LUHCLIST,INT_IOFF3,ISTART_BLK,LLUC,T_SCR_CC,
     &                 IT_TTPL,IT_TTOL
     &                ,IBLOCKL_S,NPARBLOCK_S
#endif
     &     )
C
      deallocate(L_Sym_Block)
      deallocate(L_A_Block)
      deallocate(L_B_Block)
      deallocate(INum_Sym_A)
      deallocate(ISym_AA)
      deallocate(ISym_AB)
      deallocate(IAA_SM_STR_S)
      deallocate(IAB_SM_STR_S)
      deallocate(IAA_SM_STR_E)
      deallocate(IAB_SM_STR_E)
      deallocate(NSubBlk_A)
      deallocate(NStrings_A)
      deallocate(INum_Sym_C)
      deallocate(ISym_CA)
      deallocate(ISym_CB)
      deallocate(ICA_SM_STR_S)
      deallocate(ICB_SM_STR_S)
      deallocate(ICA_SM_STR_E)
      deallocate(ICB_SM_STR_E)
      deallocate(NSubBlk_C)
      deallocate(NStrings_C)
      deallocate(CJRES_BAT)
      deallocate(SIRES_BAT)
      deallocate(T_BAT)
C     eliminate local memory
      IDUM = 0

!      call memmar(KDUM ,IDUM,'CHECK ',2,'SIGD3Y')
      call memmar(KDUM ,IDUM,'FLUSM ',2,'SIGD3Y')

C
#if defined (VAR_MPI2)
      IF( IT_SHL .ge. 0 ) CALL REL_MEM_T_SCR(T_SCR_CC)
#endif
      END
***********************************************************************

      SUBROUTINE SIGDEN_REL4(NSBLOCK,ISBLOCK,CB,SB,
     &                       NSSOA_S,NSSOB_S,NSSOA_C,NSSOB_C,
     &                       IASTP,IBSTP,IACTP,IBCTP,MAXK,
     &                       XINT,
     &                       I1,XI1S,I2,XI2S,I3,XI3S,I4,XI4S,
     &                       IPRS,IPRD,LUC,CJRES,SIRES,
     &                       LCBLOCK,LECBLOCK,I1CBLOCK,ICBLOCK,
     &                       ISSM,ICSM,ISIGDEN,NCBATCH,
     &                       T,T_BUFF,
     &                       IDIAG,IRIS,IRIC,ITSPOBEX_TP,
     &                       ITOCC1,ITOCC2,ITOCC3,ITOCC4,
     &                       I1G,XI1G,I2G,XI2G,I3G,XI3G,I4G,XI4G,
     &                       I1GE,XI1GE,I2GE,XI2GE,I3GE,XI3GE,
     &                       I4GE,XI4GE,SIGN_NHX,ISMDST,
     &                       NICA,NICB,NIAA,NIAB,NKA,NKB,
     &                       IB_CA,IB_CB,IB_AA,IB_AB,IB_T,
     &                       NIKAINTM,NIKBINTM,NJKAINTM,NJKBINTM,
     &                 L_Sym_Block,L_A_Block,L_B_Block,INum_Sym_A,
     &                 ISym_AA,ISym_AB,IAA_SM_STR_S,IAB_SM_STR_S,
     &                 IAA_SM_STR_E,IAB_SM_STR_E,NSubBlk_A,NStrings_A,
     &                 INum_Sym_C,ISym_CA,ISym_CB,ICA_SM_STR_S,
     &                 ICB_SM_STR_S,ICA_SM_STR_E,ICB_SM_STR_E,NSubBlk_C,
     &                 NStrings_C,CJRES_BAT,SIRES_BAT,T_BAT
#if defined (VAR_MPI2)
     &                      ,LUCLIST,IOFF_SCR1_C,INT_IOFF1_C,
     &                       ISCLFAC_GROUP,NPARBLOCK_C,IBLOCKL_C,
     &                       LUHCLIST,INT_IOFF3,ISTART_BLK,LLUC,
     &                       T_SCR_CC,IT_TTPL,IT_TTOL,IBLOCKL_S,
     &                       NPARBLOCK_S
#endif
     &           )
*
*
* Jeppe Olsen, Summer of 1999
*              July 2000, Combinations of T-amplitudes and 
*                         determinants introduced
*              September 2000, ISPOBEX_FRZ added
*
* Timo Fleig, 2001/2002
*                  Modifications for relativistic CI
*             Aug. 2002
*                  Real/Imag. factor fixed for S_r (Jeppe + Timo)
*             Aug. 2003
*                  ISMDST added 
*                                 
* Stefan Knecht, May - June 2007,
*                   parallel adaption
*
* =====
* Input
* =====
*
* NSBLOCK : Number of BLOCKS included
* ISBLOCK : Blocks included 
*
* NSSOA : Number of strings per type and symmetry for alpha strings
* NSSOB : Number of strings per type and symmetry for beta strings
*
* MAXIJ : Largest allowed number of orbital pairs treated simultaneously
* MAXK  : Largest number of N-2,N-1 strings treated simultaneously
* MAXI  : Max number of N strings treated simultaneously
*
* LC : Length of scratch array for C
* LS : Length of scratch array for S
* XINT : Scratch array for integrals
* CSCR : Scratch array for C vector
* SSCR : Scratch array for S vector
*
*
* CJRES,SIRES : Space for above matrices
* The C and S vectors are accessed through routines that
* either fetches/disposes symmetry blocks or
* Symmetry-occupation-occupation blocks
*
      use symmetry_setup_krci
      use mospinor_info
      use interface_to_mpi
      IMPLICIT REAL*8(A-H,O-Z)
#include "ipoist8.inc"
*
#if defined (VAR_MPI2)
#include "infpar.h"
      INTEGER   ISTAT(df_MPI_STATUS_SIZE), NPARBLOCK_S(*), IBLOCKL_S(*)
      DIMENSION LUCLIST(*), ISCLFAC_GROUP(*), LUHCLIST(*)
      DIMENSION NPARBLOCK_C(*), IBLOCKL_C(*), IT_TTPL(*)
      INTEGER(KIND=df_MPI_OFFSET_KIND) IOFF_SCR_C, IOFF_SCR_C_EXPL
      INTEGER(KIND=df_MPI_OFFSET_KIND) IOFF_SCR1_C, IOFF_SAVE
      INTEGER(KIND=df_MPI_OFFSET_KIND) IT_TTOL(*)
      INTEGER(KIND=df_MPI_ADDRESS_KIND) ICPL_I8, ITB_I8
#endif
#include "parluci.h"
C     general input
#include "mxpdim.inc"
#include "gasstr.inc"
#include "wrkspc.inc"
#include "cgas.inc"
#include "cstate.inc"
#include "strbas.inc"
#include "integrals_off.inc"
#include "ctcc.inc"
C     memory window
#include "krmc_shmem.h"
!         FOR debug!!!
#include "dgroup.h"
C     specific input
      INTEGER ISBLOCK(8,*)
      INTEGER LCBLOCK(*),I1CBLOCK(*),ICBLOCK(8,*),LECBLOCK(*)
C     general input
      INTEGER NSSOA_S(NSMST,*),NSSOB_S(NSMST,*)
      INTEGER NSSOA_C(NSMST,*),NSSOB_C(NSMST,*)
      DIMENSION SIGN_NHX(NSPOBEX_TP)
C     scratch
      DIMENSION SB(*),CB(*)
      DIMENSION XINT(*)

      DIMENSION I1(*),I2(*),I3(*),I4(*)

      DIMENSION XI1S(*),XI2S(*),XI3S(*)
      DIMENSION ISMDST(*)
C
      DIMENSION CJRES(*),SIRES(*)
C
C     T-coefficients
C
      DIMENSION T(*), T_BUFF(*)
#if defined (VAR_MPI2)
      DIMENSION T_SCR_CC(*)
#endif

      dimension ITSPOBEX_TP(4*NGAS,*)
      INTEGER ICPL
      INTEGER*8 ITB, ITB_BUFF, ITB_BUFF_ADD, nelm_cc
      logical New_GNSIDE
C

      ONEM = -1.0D0
      IZERO = 0
      IST_C_BLK_CT = 0
      ICPL         = 0
      ICPL_I8      = 0
      ITB_I8       = 0
C     process id
      ID_ACCUM     = -1 
      ID_GET       = -1 
C
      NTESTL = 000
      NTEST = MAX(NTESTL,max(IPRS,IPRD))
C
#if defined LUCI_DEBUG
      IF(NTEST.GE.800) THEN
        WRITE(LUWRT,*) ' ================'
        WRITE(LUWRT,*) ' SIGDEN4 speaking :'
        WRITE(LUWRT,*) ' ================'
        WRITE(LUWRT,*)  
        WRITE(LUWRT,*) ' Number of sigma blocks to be calculated ',
     &  NSBLOCK
        WRITE(LUWRT,*) ' TTSS and IOFF for each ACTIVE sigma block'
          DO IBLOCK = 1, NSBLOCK
            IF(ISBLOCK(1,IBLOCK).GT.0) 
     &      WRITE(LUWRT,'(10X,I6,4I3,I8)') 
     &      IBLOCK,(ISBLOCK(II,IBLOCK),II=1,5)
          END DO
      END IF
#endif
*
#if !defined (VAR_MPI2)
#ifdef LUCI_DEBUG
      NTEST = 000
      IF(NTEST.GE.500) THEN
        WRITE(LUWRT,*) ' Initial C vector '
        CALL WRTVCD(CB,LUC,1,-1)
      END IF
      NTEST = 0
#endif
*     rewind C file
      REWIND LUC
#else
      IOFF_SCR_C = 0
      IOFF_SCR_C_EXPL = 0
      IOFF_SCR_C_EXPL = IOFF_SCR1_C
      IOFF_SAVE = IOFF_SCR1_C
      start_timer = 0.0D0
CSK      WRITE(LUWRT,*) ' GOT NEW OFFSET FOR C-VECTOR FILE',
CSK     &                 IOFF_SAVE
CSK      WRITE(LUWRT,*) 'INT_IOFF3 in SIGDEN4',INT_IOFF3
CSK      WRITE(LUWRT,*) ' ISCLFAC_GROUP in SIGDEN4'
CSK      CALL IWRTMAMN(ISCLFAC_GROUP,1,NUM_BLOCKS2,1,NUM_BLOCKS2,LUWRT)
#endif
C
      IOCTPA = IBSPGPFTP(IASTP)
      IOCTPB = IBSPGPFTP(IBSTP)
      JOCTPA = IBSPGPFTP(IACTP)
      JOCTPB = IBSPGPFTP(IBCTP)
C
      NSTT_BLK = NSBLOCK/NSMST
C
C     loop over batches over C blocks      
C
      DO 20000 JCBATCH = 1, NCBATCH             
C
C      C blocks offset in current batch
C
        NJBLOCK = LCBLOCK(JCBATCH)
        NCTT_BLK = NJBLOCK/NSMST
        I1C = I1CBLOCK(JCBATCH)
!       WRITE(LUWRT,*) ' NJBLOCK, NCTT_BLK, I1C, NSBLOCK, NSTT_BLK',
!    &                   NJBLOCK, NCTT_BLK, I1C, NSBLOCK, NSTT_BLK
C
C       loop over TT blocks of sigma and C in batches and 
C       obtain contributions 
C
        DO 9000 ICTT_BLK = 1, NCTT_BLK
          IREAD = 0
C
C         first block of next TT block of C    
C
          ICBLK = I1C + (ICTT_BLK-1)*NSMST
          JATP  = ICBLOCK(1,ICBLK)
          JBTP  = ICBLOCK(2,ICBLK)
          ICOFF = ICBLOCK(5,ICBLK)
C
#if defined LUCI_DEBUG
          IF(NTEST.GE.500) THEN
            WRITE(LUWRT,*) ' Next block of C, ICBLK,JATP,JBTP,ICOFF ',
     &      ICBLK,JATP,JBTP
          END IF
#endif
C
#if defined (VAR_MPI2)
C
C         check if TT-blocks are 'active'! if not, 
C         skip all loops that will follow.
C
          ICOMPUTE_C = 0
          NCBLK = NSMST
          IC_OFF_BLK = INT_IOFF1_C
          IF( IRIC .eq. 1 ) THEN
            IST_C_BLK_CT = IC_OFF_BLK
          ELSE
            IST_C_BLK_CT = IC_OFF_BLK - NUM_BLOCKS
          END IF
          DO JBLK = ICBLK, ICBLK + NCBLK - 1
CSK         WRITE(LUWRT,*) ' Checking for c block',IC_OFF_BLK+JBLK-1
            IF( ISCLFAC_GROUP(IC_OFF_BLK+JBLK-1) .gt. 0 ) THEN
              ICOMPUTE_C = 1
CSK           WRITE(LUWRT,*) ' active c block found',IC_OFF_BLK+JBLK-1
            END IF
          END DO
          IF( ICOMPUTE_C .eq. 0 ) GOTO 8999
*
#endif
          IRATP = JATP + JOCTPA - 1
          IRBTP = JBTP + JOCTPB - 1
C
          DO 10000 ISTT_BLK = 1, NSTT_BLK
C
C           first block of next TT block of sigma
            ISBLK = (ISTT_BLK-1)*NSMST + 1
#if defined (VAR_MPI2)
C
C           check if TT-blocks need to be calculated! if not,
C           skip all loops that follow.
            ICOMPUTE_S = 0
            NSBLK = NSMST
            IS_OFF_BLK = 0
            IS_OFF_BLK = INT_IOFF3
            DO JJBLK = ISBLK, ISBLK + NSBLK - 1
             IF(NPARBLOCK_S(JJBLK+IS_OFF_BLK-1).eq.MYPROC) ICOMPUTE_S=1
            END DO
            IF( ICOMPUTE_S .eq. 0 ) GOTO 9999
#endif
            IATP = ISBLOCK(1,ISBLK)
            IBTP = ISBLOCK(2,ISBLK)
            ISOFF = ISBLOCK(5,ISBLK)
CSK         WRITE(LUWRT,*) ' Next block of S, ISBLK,IATP,IBTP,ISOFF ',
CSK  &                                        ISBLK,IATP,IBTP,ISOFF
            ILATP = IATP + IOCTPA - 1
            ILBTP = IBTP + IOCTPB - 1
C
C           loop over spinorbital-excitation types 
            ITB_BUFF = 1
C
            DO 8000 ITTP = 1, NSPOBEX_TP
              ICA_OFF = 1
              ICB_OFF = 1 +  NGAS
              IAA_OFF = 1 +2*NGAS
              IAB_OFF = 1 +3*NGAS
#if defined (VAR_MPI2)
              IF( SPLIT_IJKL ) THEN
C               determine T type for use in T list
                IXXTTP = ITTP
                IF( (IRIS .eq. 1 .and. IRIC .eq. 2)
     &             .or. ( IRIS .eq. 2 .and. IRIC .eq. 1) ) THEN
                     IXXTTP = ITTP + NSPOBEX_TP
                END IF
C               active T block? (complex case included)
                ID_GET = IT_TTPL( IXXTTP )
csk             WRITE(LUWRT,*) ' type IXXTTP and ID_GET',IXXTTP,ID_GET
                IF( ID_GET .le. 0 ) THEN
                  ITB_BUFF_ADD = 0
                  GOTO 8000
                ELSE
C                 length of T block to compute T_BUFF offset
                  ITB_BUFF_ADD = NELM_CC(ITTP,NSPOBEX_TP,LEN_T_BUFF_NZ)
                END IF
              END IF
#endif
C
C             check connections 
              CALL GXFSTR(NELFSPGP(1,ILATP),NELFSPGP(1,ILBTP),
     &                    NELFSPGP(1,IRATP),NELFSPGP(1,IRBTP),
     &                    ITSPOBEX_TP(ICA_OFF,ITTP), 
     &                    ITSPOBEX_TP(IAA_OFF,ITTP),
     &                    ITSPOBEX_TP(ICB_OFF,ITTP), 
     &                    ITSPOBEX_TP(IAB_OFF,ITTP),
     &                    NGAS,ICON)
!             WRITE(LUWRT,*) ' type ITTP and ICON',ITTP,ICON
              IF(ICON .eq. 1)THEN
C
C                offset for T array
                 ITB = IBTSOSO_TP(ITTP)
                 IF( (IRIS .eq. 1 .and. IRIC .eq. 2)
     &                .or. ( IRIS .eq. 2 .and. IRIC .eq. 1) ) THEN
                      ITB = ITB + LEN_T_VEC
                 END IF
C
C                ISIGDEN ==1
C
C                "shared memory" MPI mode:
C                copy T-block from window to T_SCR_CC
#if defined (VAR_MPI2)
                 IF( IT_SHL .ge. 0 )THEN
C
C                  get ICPL8 elements of T
                   ICPL_I8     = NELM_CC(ITTP,NSPOBEX_TP,LEN_T_BUFF_NZ)
                   XNINT_TP_I8 = REAL( ICPL_I8 )
                   ICPL        = IGIVE_I_B(XNINT_TP_I8)
C                  determine T type for use in T list
                   IXXTTP = ITTP
                   IF( (IRIS .eq. 1 .and. IRIC .eq. 2)
     &                .or. ( IRIS .eq. 2 .and. IRIC .eq. 1) ) THEN
                      IXXTTP = ITTP + NSPOBEX_TP
                   END IF
C                  process id and window offset (complex case included)
                   ID_GET = IT_TTPL( IXXTTP )
C                  check for availability
                   IF( ID_GET .lt. 0) GOTO 8000
C                  window offset
                   ITB_I8 = IT_TTOL( IXXTTP )
C
                   IF( ISIGDEN .eq. 1 )THEN
csk                  write(luwrt,*) ' ID_GET, ITB_I8, IXXTTP, ICPL',
csk  &                                ID_GET, ITB_I8, IXXTTP, ICPL
                     start_timer = interface_MPI_WTIME() 
                     IF( MYNEW_ID_SM .eq. ID_GET )THEN
                       CALL DCOPY(ICPL,T_BUFF(ITB_I8+1),1,T_SCR_CC,1)
                     ELSE
                       CALL MPIXGET(T_SCR_CC,ICPL,2,ID_GET,
     &                              ITB_I8,ICPL,2,MY_T_WIN)
                     END IF
                     mem_cp_time = mem_cp_time + 
     &                             interface_MPI_WTIME() - start_timer
                   ELSE IF( ISIGDEN .eq. 2 )THEN
                     CALL DZERO8( T_SCR_CC, ICPL_I8)
                   END IF
C                  ^ ISIGDEN
                 END IF
C                ^ IT_SHL 
#endif
C
C                read C block in
                 IF(IREAD.EQ.0) THEN
C                  number of blocks
                   NCBLK = NSMST
C
C                  fetch c-blocks
#if defined (VAR_MPI2)
                   IC_OFF_BLK     = INT_IOFF1_C
                   IOFF_SCRATCH_C = 0
#endif
                   DO JBLK = ICBLK, ICBLK + NCBLK - 1
                     JASM = ICBLOCK(3,JBLK)
                     JBSM = ICBLOCK(4,JBLK)
                     JOFF = ICBLOCK(5,JBLK)
                     JLEN = ICBLOCK(7,JBLK)
#if defined (VAR_MPI2)
CSK                  WRITE(LUWRT,*) ' checking for IC_OFF_BLK+JBLK-1',
CSK  &                                IC_OFF_BLK+JBLK-1
CSK                  WRITE(LUWRT,*) ' IOFF_SCR_C is', IOFF_SCR_C
CSK                  WRITE(LUWRT,*) ' JLEN is for IST_C_BLK_CT + JBLK', 
CSK  &                                JLEN, IST_C_BLK_CT + JBLK - 1
C
C                    check for active blocks
                     IF(ISCLFAC_GROUP(IC_OFF_BLK+JBLK-1).eq.0) GOTO 8888
CSK                  WRITE(LUWRT,*) ' Read-in for JBLK',JBLK,
CSK  &                                IC_OFF_BLK+JBLK-1
C
C                    new offset in MPI-2 parallel file
                     IOFF_SCR_C_EXPL = IOFF_SAVE + IOFF_SCR_C 
CSK                  WRITE(LUWRT,*) ' Read-in at file offset',
CSK  &                                IOFF_SCR_C_EXPL
CSK                  WRITE(LUWRT,*) ' memory offset',
CSK  &                                JOFF
C
C                    read block in core
                     xxxbitime = interface_MPI_WTIME()
                     CALL GSTTBLD_PAR2(CB(JOFF),LLUC,
     &                                 IOFF_SCR_C_EXPL,JLEN)
                     xreadtimebi = xreadtimebi-xxxbitime
     &                           + interface_MPI_WTIME()
#else
                     CALL GSTTBLD2(CB(JOFF),LUC)
#endif
                     IBI_MULT_BL = IBI_MULT_BL + 1
C                    real/imaginary scaling according to:
C                    S_r = (H_r . C_r) - (H_i . C_i)
                     if (IRIS.eq.1.and.IRIC.eq.2) then
                       CALL DSCAL(JLEN,ONEM,CB(JOFF),1)
                     end if
#if defined (VAR_MPI2)
 8888                CONTINUE
                     IOFF_SCR_C = IOFF_SCR_C + JLEN
#endif
                   END DO
                   IREAD = 1
                 END IF
C                ^ End if block should be read in 
C

                 New_GNSIDE = .true.
#if defined (VAR_MPI2)
                 gnside1 = interface_mpi_wtime()
#else
                 call CPU_TIME(gnside1)
#endif
                 if(linear.or.dougrp.lt.10)then

!                  if(New_GNSIDE.and.(ISIGDEN==1)) then
!                     write(LUWRT,*) 'calling New_GNSIDE'
                   CALL New_GNSIDE_REL_opt(ISIGDEN,IRIS,IRIC,
     &                                 ITSPOBEX_TP(ICA_OFF,ITTP),
     &                                 ITSPOBEX_TP(ICB_OFF,ITTP),
     &                                 ITSPOBEX_TP(IAA_OFF,ITTP),
     &                                 ITSPOBEX_TP(IAB_OFF,ITTP),
     &                                 NELFSPGP(1,ILATP),
     &                                 NELFSPGP(1,ILBTP),
     &                                 NELFSPGP(1,IRATP),
     &                                 NELFSPGP(1,IRBTP),
     &                                 NSSOA_S(1,IATP),NSSOB_S(1,IBTP),
     &                                 NSSOA_C(1,JATP),NSSOB_C(1,JBTP),
     &                                 T(ITB),T_BUFF(ITB_BUFF),T_SCR_CC,
     &                                 ITTP,SB(ISOFF),CB(ICOFF),ISSM,
     &                                 ICSM,I1,XI1S,I2,XI2S,I3,XI3S,I4,
     &                                 XI4S,XINT,CJRES,SIRES,MAXK,
     &                                 ITOCC1,ITOCC2,ITOCC3,ITOCC4,
     &                                 I1G,XI1G,I2G,XI2G,I3G,XI3G,I4G,
     &                                 XI4G,I1GE,XI1GE,I2GE,XI2GE,I3GE,
     &                                 XI3GE,I4GE,XI4GE,SIGN_NHX(ITTP),
     &                                 IPRS,IPRD,ISMDST,
     &                                 NICA,NICB,NIAA,NIAB,NKA,NKB,
     &                                 IB_CA,IB_CB,
     &                                 IB_AA,IB_AB,IB_T,
     &                                 NIKAINTM,NIKBINTM,
     &                                 NJKAINTM,NJKBINTM,
     &                 L_Sym_Block,L_A_Block,L_B_Block,INum_Sym_A,
     &                 ISym_AA,ISym_AB,IAA_SM_STR_S,IAB_SM_STR_S,
     &                 IAA_SM_STR_E,IAB_SM_STR_E,NSubBlk_A,NStrings_A,
     &                 INum_Sym_C,ISym_CA,ISym_CB,ICA_SM_STR_S,
     &                 ICB_SM_STR_S,ICA_SM_STR_E,ICB_SM_STR_E,NSubBlk_C,
     &                 NStrings_C,CJRES_BAT,SIRES_BAT,T_BAT
#if defined (VAR_MPI2)
     &                                ,INT_IOFF1_C+ICBLK-1,
     &                                 IS_OFF_BLK+ISBLK-1,
     &                                 ISCLFAC_GROUP,NPARBLOCK_S
#endif
     &           )
!                  else
!                     write(LUWRT,*) 'ISD=2!!!'
!                   CALL GNSIDE_REL_opt(ISIGDEN,IRIS,IRIC,
!     &                                 ITSPOBEX_TP(ICA_OFF,ITTP),
!     &                                 ITSPOBEX_TP(ICB_OFF,ITTP),
!     &                                 ITSPOBEX_TP(IAA_OFF,ITTP),
!     &                                 ITSPOBEX_TP(IAB_OFF,ITTP),
!     &                                 NELFSPGP(1,ILATP),
!     &                                 NELFSPGP(1,ILBTP),
!     &                                 NELFSPGP(1,IRATP),
!     &                                 NELFSPGP(1,IRBTP),
!     &                                 NSSOA_S(1,IATP),NSSOB_S(1,IBTP),
!     &                                 NSSOA_C(1,JATP),NSSOB_C(1,JBTP),
!     &                                 T(ITB),T_BUFF(ITB_BUFF),T_SCR_CC,
!     &                                 ITTP,SB(ISOFF),CB(ICOFF),ISSM,
!     &                                 ICSM,I1,XI1S,I2,XI2S,I3,XI3S,I4,
!     &                                 XI4S,XINT,CJRES,SIRES,MAXK,
!     &                                 ITOCC1,ITOCC2,ITOCC3,ITOCC4,
!     &                                 I1G,XI1G,I2G,XI2G,I3G,XI3G,I4G,
!     &                                 XI4G,I1GE,XI1GE,I2GE,XI2GE,I3GE,
!     &                                 XI3GE,I4GE,XI4GE,SIGN_NHX(ITTP),
!     &                                 IPRS,IPRD,ISMDST,
!     &                                 NICA,NICB,NIAA,NIAB,NKA,NKB,
!     &                                 IB_CA,IB_CB,
!     &                                 IB_AA,IB_AB,IB_T,
!     &                                 NIKAINTM,NIKBINTM,
!     &                                 NJKAINTM,NJKBINTM
!#if defined (VAR_MPI2)
!     &                                ,INT_IOFF1_C+ICBLK-1,
!     &                                 IS_OFF_BLK+ISBLK-1,
!     &                                 ISCLFAC_GROUP,NPARBLOCK_S
!#endif
!     &           )
!                  end if
                 else
                   call quit('*** sigden_rel4: this branch is no'//
     &                       ' longer active.***')
                   CALL GNSIDE_REL()
                 end if
#if defined (VAR_MPI2)
                 gnside2 = interface_mpi_wtime()
#else
                 call CPU_TIME(gnside2)
#endif

                 gnside_time = gnside_time + gnside2 - gnside1
C
C                ISIGDEN ==2
C
C                "shared memory" MPI mode:
C                all : T_SCR_CC --> MY_T_WIN 
C
                 IF( IT_SHL .ge. 0 )THEN
C
                   IF( ISIGDEN .eq. 2 )THEN
C
                     XXX = DDOT( ICPL, T_SCR_CC, 1, T_SCR_CC, 1 )
C                    update if necessary
                     IF( XXX .ne. 0.0D0 ) THEN
C                       process id and window offset
C                       (complex case included)
#if defined (VAR_MPI2)
C                       use ID_GET as ID_ACCUM
                        ID_ACCUM = ID_GET
C                       window offset determined above
                        CALL MPIXACCUM(T_SCR_CC,ICPL,2,ID_ACCUM,
     &                                 ITB_I8,ICPL,2,MY_T_WIN)
#endif
                     END IF
                   END IF ! ISIGDEN
                 END IF ! IT_SHL
               END IF ! connection check
#if defined (VAR_MPI2)
            ITB_BUFF = ITB_BUFF + ITB_BUFF_ADD
#endif
C
 8000       CONTINUE ! loop over spinorbital-excitation types 
C
!#define LUCI_DEBUG
#ifdef LUCI_DEBUG
            WRITE(LUWRT,*) ' Updated sigma blocks ' 
#ifdef VAR_MPI2
            CALL WRTVH1_PAR(SB(ISOFF),ISSM,NSSOA_S(1,IATP),
     &                      NSSOB_S(1,IBTP),NPARBLOCK_S,
     &                      IS_OFF_BLK+ISBLK-1,1)
#else
            CALL WRTVH1(SB(ISOFF),ISSM,NSSOA_S(1,IATP),
     &                  NSSOB_S(1,IBTP))
#endif
#endif /* debug mode */
!#undef LUCI_DEBUG
C
 9999       CONTINUE ! skip TT-blocks for sigma if not included in nodelist
10000     CONTINUE ! loop over blocks of sigma 
#if defined (VAR_MPI2)
          IF(IREAD.EQ.0) THEN
C
C           these C blocks were not needed, skip them
            DO JBLK = ICBLK, ICBLK + NCBLK - 1
CSK            WRITE(LUWRT,*) 'IREAD == 0: skipping for block',
CSK  &                         IST_C_BLK_CT+JBLK - 1
              IOFF_SCR_C = IOFF_SCR_C + IBLOCKL_C(IST_C_BLK_CT+JBLK-1)
            END DO
C
          END IF ! unused c-blocks
 8999     CONTINUE ! skip TT-c-blocks if not 'active'
          IF( ICOMPUTE_C .eq. 0 ) THEN
C           skip c-blocks on file
            DO JBLK = ICBLK, ICBLK + NCBLK - 1
CSK           WRITE(LUWRT,*) 'skipping for block',IST_C_BLK_CT+JBLK - 1
              IOFF_SCR_C = IOFF_SCR_C +IBLOCKL_C(IST_C_BLK_CT+JBLK-1)
            END DO
          END IF
C
#else
          IF(IREAD.EQ.0) THEN
C           these C blocks were not needed, skip them
            DO JBLK = 1, NSMST
              CALL IFRMDS(LBL,-1,1,LUC)
              CALL SKPRCD2(LBL,-1,LUC)
            END DO
          END IF
#endif
 9000   CONTINUE ! loop over TT C blocks in batch
20000 CONTINUE ! loop over batches of C blocks
      END
***********************************************************************

      SUBROUTINE TCC_SUBBLK(TCC,TCC_BUFF,T_SCR_CC,TCC_SUB,IWAY,
     &                      NCA,NCA_SUB,ICA_B,NCB,NCB_SUB,ICB_B,
     &                      NAA,NAA_SUB,IAA_B,NAB,NAB_SUB,IAB_B,
     &                      IAB_TRNSP,IDIAG,IPRNT)
*
* Extract - or add- subbblock of a TCC block
*
* IWAY = 1 Obtain TCC_SUB from TCC
* IWAY = 2 Add TCC_SUB to TCC
*
* Jeppe Olsen, Summer of 99
*              Updated July 2000, IAB_TRNSP, IDIAG added
*
* IAB_TRNSP = 1 : Input block is TCC(ICB,ICA,IAB,IAA)
* IDIAG     = 1 : Input block is lower diagonal
*
* Stefan Knecht, Nov. 2007 
*                use of T_SCR_CC in MPI "shared memory" mode added
*                --> treated in same way as TCC_SUB
*
* Stefan Knecht, May  2008 
*                use of TCC_BUFF in split mode added
*
#include "implicit.inc"
#include "ipoist8.inc"
#include "parluci.h"
*. Input and output
      DIMENSION TCC(NCA*NCB*NAA*NAB), TCC_BUFF(*), T_SCR_CC(*)
      DIMENSION TCC_SUB(NCA_SUB,NCB_SUB,NAA_SUB,NAB_SUB)
*
!     NTESTL = 500 ! debug
      NTESTL = 000
      NTEST = max(NTESTL,IPRNT)
*
!#define LUCI_DEBUG
#ifdef LUCI_DEBUG
!      IF(NTEST.GE.500) THEN
        WRITE(LUWRT,*) ' Input to TCC_SUBBLK '
        WRITE(LUWRT,*) ' NCA, NCB, NAA, NAB', NCA,NCB,NAA,NAB
        WRITE(LUWRT,*) ' NCA_SUB, NCB_SUB, NAA_SUB, NAB_SUB',
     &               NCA_SUB, NCB_SUB, NAA_SUB, NAB_SUB
        WRITE(LUWRT,*) ' IAB_TRNSP, IDIAG = ', IAB_TRNSP, IDIAG
        WRITE(LUWRT,*) ' Iway = ', IWAY
        IF( SHARED_M )THEN
          WRITE(LUWRT,*) ' T_SCR_CC input BLOCK'
          CALL WRTMATMN(T_SCR_CC,NCA*NCB,NAA*NAB,NCA*NCB,NAA*NAB,LUWRT)
        ELSE IF(SPLIT_IJKL)THEN
          WRITE(LUWRT,*) ' TCC_BUFF input BLOCK'
          CALL WRTMATMN(TCC_BUFF,NCA*NCB,NAA*NAB,NCA*NCB,NAA*NAB,LUWRT)
        ELSE
          WRITE(LUWRT,*) ' TCC input BLOCK'
          CALL WRTMATMN(TCC,NCA*NCB,NAA*NAB,NCA*NCB,NAA*NAB,LUWRT)
        END IF
!      END IF
#endif
*
      IF(IAB_TRNSP.EQ.0.AND.IDIAG.EQ.0) THEN

       DO ICA = 1, NCA_SUB
         DO ICB = 1, NCB_SUB
           DO IAA = 1, NAA_SUB
             DO IAB = 1, NAB_SUB
               IADR_FULL = (IAB+IAB_B-2)*NAA*NCB*NCA + 
     &                     (IAA+IAA_B-2)*NCB*NCA +
     &                     (ICB+ICB_B-2)*NCA +
     &                      ICA+ICA_B-1
C?             WRITE(6,*) ' ICA, ICB, IAA, IAB =', ICA,ICB,IAA,IAB
csk               WRITE(LUWRT,*) ' IADR_FULL 1 is',IADR_FULL
               IF( SHARED_M )THEN
                 IF(IWAY.EQ.1) THEN
                   TCC_SUB(ICA,ICB,IAA,IAB) =  T_SCR_CC(IADR_FULL)
                 ELSE
                   T_SCR_CC(IADR_FULL) = T_SCR_CC(IADR_FULL) + 
     &                                   TCC_SUB(ICA,ICB,IAA,IAB)
                 END IF
               ELSE IF( SPLIT_IJKL )THEN
                 IF(IWAY.EQ.1) THEN
                   TCC_SUB(ICA,ICB,IAA,IAB) =  TCC_BUFF(IADR_FULL)
                 ELSE
                   TCC_BUFF(IADR_FULL) = TCC_BUFF(IADR_FULL) + 
     &                                   TCC_SUB(ICA,ICB,IAA,IAB)
                 END IF
               ELSE 
                 IF(IWAY.EQ.1) THEN
                   TCC_SUB(ICA,ICB,IAA,IAB) =  TCC(IADR_FULL)
                 ELSE
                   TCC(IADR_FULL) = TCC(IADR_FULL) + 
     &                              TCC_SUB(ICA,ICB,IAA,IAB)
                 END IF
               END IF
C              ^ "shared memory" / split mode
             END DO
           END DO
         END DO
       END DO
      ELSE IF (IAB_TRNSP.EQ.1.AND.IDIAG.EQ.0) THEN
       DO ICA = 1, NCA_SUB
       DO ICB = 1, NCB_SUB
       DO IAA = 1, NAA_SUB
       DO IAB = 1, NAB_SUB
*. Obtain T(ICA,ICB,IAA,IAB) as T(ICB,ICA,IAB,IAA)
         IADR_FULL = (IAA+IAA_B-2)*NAB*NCA*NCB + (IAB+IAB_B-2)*NCA*NCB
     +             + (ICA+ICA_B-2)*NCB + ICB+ICB_B-1
csk               WRITE(LUWRT,*) ' IADR_FULL 2 is',IADR_FULL
C?       WRITE(6,*) ' ICA, ICB, IAA, IAB =', ICA,ICB,IAA,IAB
         IF( SHARED_M )THEN
           IF(IWAY.EQ.1) THEN
             TCC_SUB(ICA,ICB,IAA,IAB) =  T_SCR_CC(IADR_FULL)
           ELSE
             T_SCR_CC(IADR_FULL)  =  T_SCR_CC(IADR_FULL) + 
     &                               TCC_SUB(ICA,ICB,IAA,IAB)
           END IF
         ELSE IF (SPLIT_IJKL) THEN
           IF(IWAY.EQ.1) THEN
             TCC_SUB(ICA,ICB,IAA,IAB) =  TCC_BUFF(IADR_FULL)
           ELSE
             TCC_BUFF(IADR_FULL)  =  TCC_BUFF(IADR_FULL) + 
     &                               TCC_SUB(ICA,ICB,IAA,IAB)
           END IF
         ELSE
           IF(IWAY.EQ.1) THEN
             TCC_SUB(ICA,ICB,IAA,IAB) =  TCC(IADR_FULL)
           ELSE
             TCC(IADR_FULL)  =  TCC(IADR_FULL) + 
     &                          TCC_SUB(ICA,ICB,IAA,IAB)
           END IF
         END IF
C        ^ "shared memory" / split mode
       END DO
       END DO
       END DO
       END DO
      ELSE IF (IDIAG.EQ.1) THEN
       DO ICA = 1, NCA_SUB
       DO ICB = 1, NCB_SUB
       DO IAA = 1, NAA_SUB
       DO IAB = 1, NAB_SUB
         ICA_ABS = ICA + ICA_B -1
         ICB_ABS = ICB + ICB_B -1
         IAA_ABS = IAA + IAA_B -1
         IAB_ABS = IAB + IAB_B -1
*
         IF((IAA_ABS.GT.IAB_ABS).OR.
     &      (IAA_ABS.EQ.IAB_ABS.AND.ICA_ABS.GE.ICB_ABS)) THEN
            IADR_FULL = ITDIANUM(ICA_ABS,ICB_ABS,IAA_ABS,IAB_ABS,
     &                  NCA,NAA)
            ILOW = 1
         ELSE 
            IADR_FULL = ITDIANUM(ICB_ABS,ICA_ABS,IAB_ABS,IAA_ABS,
     &                  NCA,NAA)
            ILOW = 0
         END IF
csk               WRITE(LUWRT,*) ' IADR_FULL 3 is',IADR_FULL
*
         IF( SHARED_M )THEN
           IF(IWAY.EQ.1) THEN
             TCC_SUB(ICA,ICB,IAA,IAB) =  T_SCR_CC(IADR_FULL)
           ELSE IF(ILOW.EQ.1) THEN
             T_SCR_CC(IADR_FULL)  =  T_SCR_CC(IADR_FULL) + 
     &                               TCC_SUB(ICA,ICB,IAA,IAB)
           END IF
         ELSE IF (SPLIT_IJKL) THEN
           IF(IWAY.EQ.1) THEN
             TCC_SUB(ICA,ICB,IAA,IAB) =  TCC_BUFF(IADR_FULL)
           ELSE IF(ILOW.EQ.1) THEN
             TCC_BUFF(IADR_FULL)  =  TCC_BUFF(IADR_FULL) + 
     &                               TCC_SUB(ICA,ICB,IAA,IAB)
           END IF
         ELSE
           IF(IWAY.EQ.1) THEN
             TCC_SUB(ICA,ICB,IAA,IAB) =  TCC(IADR_FULL)
           ELSE IF(ILOW.EQ.1) THEN
             TCC(IADR_FULL)  =  TCC(IADR_FULL) + 
     &                          TCC_SUB(ICA,ICB,IAA,IAB)
           END IF
         END IF
C        ^ "shared memory" / split mode
       END DO
       END DO
       END DO
       END DO
      END IF
*
#ifdef LUCI_DEBUG
      WRITE(LUWRT,*) ' TCC_SUBBLK : TCC_SUB '
      NCAB_SUB = NCA_SUB*NCB_SUB
      NAAB_SUB = NAA_SUB*NAB_SUB
      CALL WRTMATMN(TCC_SUB,NCAB_SUB,NAAB_SUB,NCAB_SUB,NAAB_SUB,LUWRT)
#endif
!#undef LUCI_DEBUG
*  
      END
***********************************************************************

      SUBROUTINE WRT_TP_GENOP(ICA,ICB,IAA,IAB,NGAS)
*
* Write occupation in each GASspace for general operator
*
* Jeppe Olsen, August 1999
*
#include "implicit.inc"
*
      INTEGER ICA(NGAS),ICB(NGAS),IAA(NGAS),IAB(NGAS)
*
      WRITE(6,*) ' Occupation of alpha-creation string '
      CALL IWRTMA(ICA,1,NGAS,1,NGAS)
      WRITE(6,*) ' Occupation of beta -creation string '
      CALL IWRTMA(ICB,1,NGAS,1,NGAS)
      WRITE(6,*) ' Occupation of alpha-annihilation string '
      CALL IWRTMA(IAA,1,NGAS,1,NGAS)
      WRITE(6,*) ' Occupation of beta -annihilation string '
      CALL IWRTMA(IAB,1,NGAS,1,NGAS)
*
      RETURN
      END
***********************************************************************

      SUBROUTINE WRT_SPOX_TP(IEX_TP,NEX_TP)
*
* Print types of spin-orbital excitations
*
#include "implicit.inc"
#include "mxpdim.inc"
#include "cgas.inc"
*
      INTEGER IEX_TP(4*NGAS,NEX_TP)
*
      WRITE(6,*)
      WRITE(6,*) ' ***************************************** '
      WRITE(6,*) ' Information about spinorbital excitations '
      WRITE(6,*) ' ***************************************** '
      WRITE(6,*)
*
      DO JEX_TP = 1, NEX_TP
        WRITE(6,*)
        WRITE(6,*) ' Included spinorbitalexcitation ', JEX_TP
        WRITE(6,'(A,16I4)')
     &  ' Creation of alpha     :',
     &  (IEX_TP(I+0*NGAS,JEX_TP),I=1,NGAS)
        WRITE(6,'(A,16I4)')
     &  ' Creation of beta      :',
     &  (IEX_TP(I+1*NGAS,JEX_TP),I=1,NGAS)
        WRITE(6,'(A,16I4)')
     &  ' Annihilation of alpha :',
     &  (IEX_TP(I+2*NGAS,JEX_TP),I=1,NGAS)
        WRITE(6,'(A,16I4)')
     &  ' Annihilation of beta  :',
     &  (IEX_TP(I+3*NGAS,JEX_TP),I=1,NGAS)
      END DO
*
      END
***********************************************************************

      SUBROUTINE WRTVH1(H,IHSM,NRPSM,NCPSM)
*
* Write one-electron integrals with symmetry IVSM
*
* Jeppe Olsen, Jan. 1999
* Timo Fleig, June 2001: relativistic case
*
      use symmetry_setup_krci
#include "implicit.inc"
*. General input
      INTEGER NRPSM(NSMOB),NCPSM(NSMOB)
*. Specific input
      DIMENSION H(*)
*
      IOFF = 1
!       DO ISM = 1, NSMOB
        DO ISM = NSMOB/2+1,NSMOB
          JSM = IDBGMULT(INVELM(ISM),IHSM)
          NI = NRPSM(ISM)
          NJ = NCPSM(JSM)
          if(NI*NJ.gt.0)then
            WRITE(6,*) ' Block with symmetry ISM, JSM ',ISM,JSM
            CALL WRTMAT(H(IOFF),NI,NJ,NI,NJ)
          end if
          IOFF = IOFF + NI*NJ
        END DO
*
      END
***********************************************************************

      SUBROUTINE WRTVH1_PAR(H,IHSM,NRPSM,NCPSM,IACTL,
     &                      IOFFLST,IVERS)
*
* Write one-electron integrals with symmetry IVSM
*
* Jeppe Olsen, Jan. 1999
* Timo Fleig, June 2001: relativistic case
* Stefan Knecht, May 2007: parallel adaption
*
      use symmetry_setup_krci
#include "implicit.inc"
*. General input
#include "parluci.h"
      INTEGER NRPSM(NSMOB),NCPSM(NSMOB), IACTL(*)
*. Specific input
      DIMENSION H(*)
*
      IOFF = 1
      IRUN = 0
      IRUN = IOFFLST
      IF( IVERS .eq. 0 ) THEN
!       DO ISM = 1,NSMOB
        DO ISM = NSMOB/2+1,NSMOB
          IF( IACTL( IRUN ) .eq. 0 ) GOTO 100
          JSM = IDBGMULT(INVELM(ISM),IHSM)
          NI = NRPSM(ISM)
          NJ = NCPSM(JSM)
*. Complete block
          WRITE(LUWRT,*) ' Block with symmetry ISM, JSM ',ISM,JSM
          CALL WRTMATMN(H(IOFF),NI,NJ,NI,NJ,LUWRT)
          IOFF = IOFF + NI*NJ
 100      CONTINUE
          IRUN = IRUN + 1
        END DO
      ELSE
!       DO ISM = 1, NSMOB
        DO ISM = NSMOB/2+1,NSMOB
          IF( IACTL( IRUN ) .ne. MYPROC ) GOTO 200
          JSM = IDBGMULT(INVELM(ISM),IHSM)
          NI = NRPSM(ISM)
          NJ = NCPSM(JSM)
*. Complete block
          WRITE(LUWRT,*) ' Block with symmetry ISM, JSM ',ISM,JSM
          CALL WRTMATMN(H(IOFF),NI,NJ,NI,NJ,LUWRT)
          IOFF = IOFF + NI*NJ
 200      CONTINUE
          IRUN = IRUN + 1
        END DO
      END IF
*
      END
C&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&&
      SUBROUTINE XSIGDEN_CTRL(VEC1,VEC2,T_X,COPY_NEW_C,NVC_LUC,IZ
#if defined (VAR_MPI2)
     &                        ,LU1LIST,LU2LIST,LUCLIST,LBATX,LEBATX,
     &                        I1BATX,IBATX,NBATX,IBLOCKL_X,
     &                        NPARBLOCK_X,IGROUPLIST,IPROCLIST,
     &                        RCCTOS_X,IXSYMPAIRS,ICSM,ISSM,IX_CT,
     &                        IX_ST,IOFF_LU1
#endif
     &                        )
C**********************************************************************
C
C     sigma vector calculation wrapper to be used in CI property runs.
C
C     written by S. Knecht - Nov 2008
C
C     last revision:
C
C**********************************************************************
      use interface_to_mpi
#include "implicit.h"
#include "ipoist8.inc"
#include "krciprop.h"
#include "parluci.h"
#if defined (VAR_MPI2)
#include "infpar.h"
      INTEGER   ISTAT(df_MPI_STATUS_SIZE), IBLOCKL_X(NUM_BLOCKS,*)
      DIMENSION NPARBLOCK_X(NUM_BLOCKS,*) 
      DIMENSION IXSYMPAIRS(MXPROPKRCI_SYM,*), LU1LIST(*), LU2LIST(*)
      DIMENSION LUCLIST(*), LBATX(*), LEBATX(*), I1BATX(*), IBATX(8,*)
      INTEGER RCCTOS_X(NUM_BLOCKS2,*)
#endif
      DIMENSION VEC1(*), VEC2(*), T_X(*)
#include "clunit.inc"
#include "dummy.h"
      LOGICAL COPY_NEW_C
C
C
      IF( .not. COPY_NEW_C ) GOTO 100
#if defined (VAR_MPI2)
C
C     erase old LUCLIST
      CALL IZERO(LUCLIST,IALL_LUC)
C
!     WRITE(LUWRT,*) ' IOFF_LU1 is',IOFF_LU1
      IF( IZ .eq. 1 ) THEN
C       real quaternion double group
        CALL COPVCD_PP_CC_B(ILU1,ILUC,VEC1,NBATX,
     &                      LBATX,LEBATX,I1BATX,IBATX,
     &                      MY_LU1_OFF,MY_LUC_OFF,
     &                      LU1LIST,LUCLIST,
     &                      IBLOCKL_X(1,IX_CT),IOFF_LU1)
      ELSE
C       complex quaternion double group
        CALL COPVCD_PP_CC_B_C(ILU1,ILUC,VEC1,NBATX,
     &                        LBATX,LEBATX,I1BATX,IBATX,
     &                        MY_LU1_OFF,MY_LUC_OFF,
     &                        LU1LIST,LUCLIST,
     &                        IBLOCKL_X(1,IX_CT),IOFF_LU1)
      END IF
      COPY_NEW_C = .FALSE.
C     find corresponding symmetry pair
 100  IXPAIR = 0
      IF( IXSYMPAIRS(ICSM,ISSM) .gt. 0 ) THEN 
        IXPAIR = IXSYMPAIRS(ICSM,ISSM)
      ELSE
        WRITE(LUWRT,'(/A,2I4)')' *** ERROR in XSIGDEN_CTRL. no pair'//
     &                        ' type found for ICSM and ISSM:',ICSM,ISSM
        CALL QUIT(' *** ERROR in XSIGDEN_CTRL: unknown pair type.')
      END IF
C     erase old LU2LIST
      CALL IZERO(LU2LIST,IALL_LU2)
#else
C     copy new C vector to scratch file
      CALL REWINE(LUSC61,-1)
      CALL SKPVCD(LUC,IZ*(NVC_LUC-1),VEC1,1,-1)
      CALL COPVCDC(LUC,LUSC61,VEC1,0,IZ,-1)
      COPY_NEW_C = .FALSE.
 100  CALL REWINE(LUSC61,-1)
      CALL REWINE(LUHC,-1)
#endif
C     set offset for sigma-file
      JVEC_SF = 0
C
C     start calculation: sigma = T_X x C
C     ----------------------------------
      CALL SIGDEN_CTRL(VEC1,VEC2,
#if defined (VAR_MPI2)
     &                 ILUC,ILU2,
#else
     &                 LUSC61,LUHC,
#endif
     &                 T_X,DUMMY,1
#if defined (VAR_MPI2)
     &                ,LUCLIST,LU2LIST,IBLOCKL_X(1,IX_CT),
     &                 NPARBLOCK_X(1,IX_CT),IGROUPLIST,IPROCLIST,
     &                 RCCTOS_X(1,IXPAIR),DUMMY,DUMMY,
     &                 IBLOCKL_X(1,IX_ST),NPARBLOCK_X(1,IX_ST)
#endif
     &                 )
C
      END
***********************************************************************

      SUBROUTINE Z_TCC_OFF(IBT,NCA,NCB,NAA,NAB,ITSYM)
*
* Offsets for symmetryblocks of TCC elements, sym of CA,CB,AA used 
*
*
* Jeppe Olsen, Summer of 99
*              July 2000, HNIE : IDIAG added
* Timo Fleig, summer of 2001, modified for relativistic case
*
      use symmetry_setup_krci
#include "implicit.inc"
#include "ipoist8.inc"
#include "mxpdim.inc"
*. Input
*. Number of strings of different types, assumed to be 
*. creations strings
      INTEGER NCA(*),NCB(*),NAA(*),NAB(*)
*. Output
      INTEGER IBT(MXNDGIRR,MXNDGIRR,MXNDGIRR)
*
#if defined LUCI_DEBUG
      NTEST = 000
      IF(NTEST.GE.100) THEN
        WRITE(6,*) ' Z_TCC_OFF speaking '
        WRITE(6,*) ' NSMST, IDIAG = ', NSMST, IDIAG
      END IF
#endif
*
      IOFF = 1
      DO ISM_C = 1, NSMST
*. Symmetry of annihilation part
        ISM_A = IDBGMULT(ITSYM,ISM_C)
        DO ISM_CA = 1, NSMST
          ISM_CB = IDBGMULT(ISM_C,INVELM(ISM_CA))
          DO ISM_AA = 1, NSMST
            ISM_AB = IDBGMULT(ISM_A,INVELM(ISM_AA))
*
            ISM_ALPHA = (ISM_AA-1)*NSMST+ISM_CA
            ISM_BETA  = (ISM_AB-1)*NSMST+ISM_CB
*
            IBT(ISM_CA,ISM_CB,ISM_AA) = IOFF
            IOFF = IOFF + 
     &      NCA(ISM_CA)*NCB(ISM_CB)*NAA(ISM_AA)*NAB(ISM_AB)
*           ^ NCA was number of creation strings per sym
!
!           debug print
!           if(NCA(ISM_CA)*NCB(ISM_CB)*NAA(ISM_AA)*NAB(ISM_AB).gt.0) 
!    &      print '(a,5i4)', 'nonzero length: symmetries + length ==>',
!    &      ISM_CA,ISM_CB,ISM_AA,ISM_AB,
!    &      NCA(ISM_CA)*NCB(ISM_CB)*NAA(ISM_AA)*NAB(ISM_AB)
#if defined LUCI_DEBUG
            if (NTEST.ge.100) then
              write(6,'(A,I2,A,I2,A,I2,A,I5)') 
     &                'IBT(',ISM_CA,',',ISM_CB,',',ISM_AA,') =',
     &                 IBT(ISM_CA,ISM_CB,ISM_AA)
            end if
#endif
*
          END DO
        END DO
      END DO
*
      END
***********************************************************************

      SUBROUTINE Z_TCC_OFF_opt(IBT,NCA,NCB,NAA,NAB,ITSYM)
*
* Offsets for symmetryblocks of TCC elements, sym of CA,CB,AA used 
*
*
* Jeppe Olsen, Summer of 99
*              July 2000, HNIE : IDIAG added
* Timo Fleig, summer of 2001, modified for relativistic case
*
      use symmetry_setup_krci
#include "implicit.inc"
#include "mxpdim.inc"
*. Input
*. Number of strings of different types, assumed to be 
*. creations strings
      INTEGER NCA(*),NCB(*),NAA(*),NAB(*)
*. Output
      INTEGER IBT(MXNDGIRR,MXNDGIRR,MXNDGIRR)
*
!     print *,'ITSYM is',ITSYM
      IOFF = 1
      DO ISM_CA = 1, NSMST
        if(NCA(ISM_CA).gt.0)then
!         print '(a,i4)', 'nonzero ISM_CA ==>',ISM_CA
          DO ISM_AA = 1, NSMST
          if(NAA(ISM_AA).gt.0)then
!         print '(a,i4)', 'nonzero ISM_AA ==>',ISM_AA
            DO ISM_C = 1, NSMST

              ISM_A  = IDBGMULT(ISM_C,IADJSYM(ITSYM))
              ISM_CB = IDBGMULT(ISM_C,INVELM(ISM_CA))
              ISM_AB = IDBGMULT(ISM_A,INVELM(ISM_AA))
*
              IBT(ISM_CA,ISM_CB,ISM_AA) = IOFF
              IOFF = IOFF + 
     &        NCA(ISM_CA)*NCB(ISM_CB)*NAA(ISM_AA)*NAB(ISM_AB)
*             ^ NCA was number of creation strings per sym
!
!           debug print
!           if(NCA(ISM_CA)*NCB(ISM_CB)*NAA(ISM_AA)*NAB(ISM_AB).gt.0) 
!    &      print '(a,5i4)', 'nonzero length: symmetries + length ==>',
!    &      ISM_CA,ISM_CB,ISM_AA,ISM_AB,
!    &      NCA(ISM_CA)*NCB(ISM_CB)*NAA(ISM_AA)*NAB(ISM_AB)
#if defined LUCI_DEBUG
            write(6,'(A,I2,A,I2,A,I2,A,I5)') 
     &            'IBT(',ISM_CA,',',ISM_CB,',',ISM_AA,') =',
     &             IBT(ISM_CA,ISM_CB,ISM_AA)
#endif
*
            END DO
           end if
          END DO
        end if
      END DO
*
      END

***********************************************************************
      SUBROUTINE SPOBEX_TO_ABOBEX(ISPOBEX_TP,NSPOBEX_TP,NGAS,
     &                            IFLAG,NAOBEX_TP,NBOBEX_TP,IAOBEX_TP,
     &                            IBOBEX_TP)
*
* Split spin-orbital excitations into alpha- and beta-orbital excitations
*
* IFLAG = 1 : Find only number of alpha- and beta- orbital excitations
*
* Jeppe Olsen, July 2000
*
#include "implicit.inc"
*
*. Input
      INTEGER ISPOBEX_TP(4*NGAS,NSPOBEX_TP)
*. Output
      INTEGER IAOBEX_TP(2*NGAS,*),IBOBEX_TP(2*NGAS,*)
*
C?    WRITE(6,*) ' SPOBEX_TO_ABOBEX : NSPOBEX_TP = ', NSPOBEX_TP
      DO IAB = 1, 2
        LEX_TP = 0
        DO JSPOBEX_TP = 1, NSPOBEX_TP
*. Has this a or b excitation been observed before
          I_AM_OLD_HAT = 0
          DO KSPOBEX_TP = 1, LEX_TP
            I_DENTICAL = 1
            DO ICA = 1, 2
              IEXP_OFF = (IAB-1)*NGAS + (ICA-1)*2*NGAS + 1
              DO IGAS = 1, NGAS
                IF(ISPOBEX_TP(IGAS+IEXP_OFF-1,JSPOBEX_TP).NE.
     &             ISPOBEX_TP(IGAS+IEXP_OFF-1,KSPOBEX_TP)    )
     &             I_DENTICAL = 0
              END DO
            END DO
            IF(I_DENTICAL.EQ.1) I_AM_OLD_HAT = 1
          END DO
          IF(I_AM_OLD_HAT.EQ.0) THEN
            LEX_TP = LEX_TP + 1
            IF(IFLAG.EQ.0) THEN
              DO ICA = 1, 2
               IEXP_OFF =  (IAB-1)*NGAS + (ICA-1)*2*NGAS + 1
               IAB_OFF  =  (ICA-1)*NGAS + 1
               IF(IAB.EQ.1) THEN
                 CALL ICOPVE(ISPOBEX_TP(IEXP_OFF,JSPOBEX_TP),
     &                        IAOBEX_TP(IAB_OFF,LEX_TP),NGAS)
               ELSE IF (IAB.EQ.2) THEN
                 CALL ICOPVE(ISPOBEX_TP(IEXP_OFF,JSPOBEX_TP),
     &                        IBOBEX_TP(IAB_OFF,LEX_TP),NGAS)
               END IF
              END DO
            END IF
          END IF ! I_AM_OLD_HAT = 0
        END DO ! loop over JSPOBEX_TP
      IF(IAB.EQ.1) THEN
        NAOBEX_TP = LEX_TP
      ELSE
        NBOBEX_TP = LEX_TP
      END IF
      END DO ! loop over IAB
*
#ifdef LUCI_DEBUG
      WRITE(6,*) ' Number of alpha-excitation operators ', NAOBEX_TP
      WRITE(6,*) ' Number of beta-excitation operators ',  NBOBEX_TP
      IF(IFLAG.EQ.0) THEN
        WRITE(6,*) ' Alpha-excitation operators : '
        WRITE(6,*) ' ============================='
        WRITE(6,*)
        DO JEX_TP = 1, NAOBEX_TP  
         WRITE(6,*)
         WRITE(6,*) ' alpha-orbital excitation ', JEX_TP
         WRITE(6,'(A,16I4)') 
     &   ' Creation      :',  (IAOBEX_TP(I+0*NGAS,JEX_TP),I=1,NGAS)
         WRITE(6,'(A,16I4)') 
     &   ' Annihilation  :',  (IAOBEX_TP(I+1*NGAS,JEX_TP),I=1,NGAS)
        END DO
        WRITE(6,*)
        WRITE(6,*) ' beta-excitation operators : '
        WRITE(6,*) ' ============================='
        WRITE(6,*)
        DO JEX_TP = 1, NBOBEX_TP  
         WRITE(6,*)
         WRITE(6,*) ' beta-orbital excitation ', JEX_TP
         WRITE(6,'(A,16I4)') 
     &   ' Creation      :',  (IBOBEX_TP(I+0*NGAS,JEX_TP),I=1,NGAS)
         WRITE(6,'(A,16I4)') 
     &   ' Annihilation  :',  (IBOBEX_TP(I+1*NGAS,JEX_TP),I=1,NGAS)
        END DO
      END IF ! iflag
#endif
*
      END
